const RESULTS = [{"id":"001","title":"Milne’s rationality conjecture and algebraic specialization","desc":"Proves Milne&#x27;s rationality conjecture for abelian varieties over $\\overline{\\mathbb Q}$ with good reduction: specialized Hodge classes pair rationally with complementary divisor products, independently of cohomology theory. Together with result 032, every specialized Hodge class is represented by a single rational algebraic cycle simultaneously in all prime-to-<i>p<\/i> and crystalline realizations, for every residue characteristic <i>p<\/i>.","subject":"Number theory","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Cohomology of abelian varieties. No route to computation or modelling identified.","papers":[{"title":"Milne&#x27;s rationality conjecture for abelian varieties","path":"preprints/Milnes-rationality-conjecture-for-abelian-varieties-September-23-2026/paper.pdf"}]},{"id":"002","title":"The full BSD formula from low Selmer corank","desc":"Proves the full Birch–Swinnerton-Dyer leading-term formula for every elliptic curve over ℚ whose full <i>q<\/i>-power Selmer group has corank zero or one for some prime <i>q<\/i>, including finiteness of the Tate–Shafarevich group. With result 006, this gives full BSD for a density-one set of quadratic twists of every elliptic curve over ℚ.","subject":"Number theory","lean":0,"applied":1,"difficulty":5,"year":1965,"note":"Arithmetic of elliptic curves. Curve cryptography does not depend on the formula.","papers":[{"title":"Exact Birch–Swinnerton-Dyer Formula from Low Selmer Corank","path":"preprints/Exact-Birch-Swinnerton-Dyer-Formula-from-Low-Selmer-Corank-October-3-2026/exact-bsd-low-selmer-corank.pdf"},{"title":"The Selmer converse for elliptic curves at every prime","path":"preprints/The-Selmer-converse-for-elliptic-curves-at-every-prime-September-24-2026/main.pdf"},{"title":"The two-primary Birch–Swinnerton-Dyer formula in Selmer corank at most one","path":"preprints/The-two-primary-Birch-Swinnerton-Dyer-formula-in-Selmer-corank-at-most-one-September-24-2026/paper.pdf"}]},{"id":"003","title":"The quasi-Riemann hypothesis","desc":"Proves that every Dirichlet <i>L<\/i>-function, including $\\zeta(s)$, is zero-free in $\\Re s\\gt 7/8$, resolving the quasi-Riemann hypothesis. The same half-plane is zero-free for every finite-order Hecke <i>L<\/i>-function over $\\mathbb Q(\\sqrt{-3})$. A companion gives a different proof of the zero-free half-plane $\\Re s\\gt 11/12$.","subject":"Number theory","lean":2,"applied":3,"difficulty":5,"year":1859,"note":"A zero-free half-plane gives power-saving error terms for primes in short intervals and progressions, which the analysis of number-theoretic algorithms uses.","papers":[{"title":"The Quasi-Riemann Hypothesis: A Zero-Free Half-Plane $\\Re s\\gt 7/8$","path":"preprints/The-Quasi-Riemann-Hypothesis-September-30-2026/paper.pdf"},{"title":"The Quasi-Riemann Hypothesis (alternate 11/12 proof)","path":"preprints/The-Quasi-Riemann-Hypothesis-October-5-2026/paper2.pdf"},{"title":"Uniform exclusion of Landau–Siegel zeros","path":"preprints/Uniform-exclusion-of-Landau-Siegel-zeros-October-1-2026/paper.pdf"}]},{"id":"004","title":"Hilbert’s tenth problem over ℚ","desc":"Proves that no algorithm decides whether an integer-coefficient polynomial in an arbitrary number of variables has a rational zero, resolving Hilbert&#x27;s tenth problem over ℚ negatively.","subject":"Number theory","lean":0,"applied":2,"difficulty":5,"year":1970,"note":"Rules out a general algorithm for rational solutions of polynomial equations. A negative result for computer algebra.","papers":[{"title":"Hilbert’s tenth problem over the rational numbers","path":"preprints/Hilberts-tenth-problem-over-the-rational-numbers-September-24-2026/main.pdf"},{"title":"A pointwise 2-converse for elliptic curves with rational two-torsion","path":"preprints/A-pointwise-2-converse-for-elliptic-curves-with-rational-two-torsion-September-24-2026/paper.pdf"}]},{"id":"005","title":"Irrationality of Catalan’s constant","desc":"Proves that Catalan&#x27;s constant $G=\\sum_{j\\ge0}(-1)^j/(2j+1)^2$ is irrational.","subject":"Number theory","lean":1,"applied":1,"difficulty":5,"year":null,"note":"Transcendence theory. No route identified.","papers":[{"title":"Catalan&#x27;s constant is irrational","path":"preprints/Catalans-constant-is-irrational-September-24-2026/paper.pdf"}]},{"id":"006","title":"Goldfeld’s conjecture: densities and mean analytic rank","desc":"Proves Goldfeld&#x27;s conjecture for quadratic twists of every elliptic curve over ℚ: analytic ranks zero and one each have density 1/2, and the mean analytic rank tends to 1/2. Both statements order signed squarefree twist parameters by absolute value.","subject":"Number theory","lean":0,"applied":1,"difficulty":4,"year":1979,"note":"Rank statistics of elliptic curves. No route identified.","papers":[{"title":"Goldfeld&#x27;s analytic density conjecture and the 2-converse for elliptic curves","path":"preprints/Goldfelds-analytic-density-conjecture-and-the-2-converse-for-elliptic-curves-September-23-2026/paper.pdf"},{"title":"The mean analytic rank of quadratic twists of elliptic curves","path":"preprints/The-mean-analytic-rank-of-quadratic-twists-of-elliptic-curves-September-23-2026/paper.pdf"}]},{"id":"007","title":"Ordinary two-point correlations and the corrected Elliott conjecture","desc":"Proves the ordinary two-point Chowla conjecture, with a bound $O(X/(\\log X)^c)$ for Liouville correlation sums along fixed nonproportional affine forms, where <i>c<\/i> &gt; 0 is absolute. More generally, proves the binary corrected Elliott conjecture for complex multiplicative functions bounded by one when one factor is uniformly nonpretentious against each fixed Dirichlet character times $n^{it}$ for $|t|\\le X$.","subject":"Number theory","lean":1,"applied":1,"difficulty":5,"year":1965,"note":"Pseudorandomness of the Liouville function. No algorithmic use identified.","papers":[{"title":"Ordinary two-point correlations of multiplicative functions","path":"preprints/Ordinary-two-point-correlations-of-multiplicative-functions-September-24-2026/final.pdf"}]},{"id":"008","title":"The Deligne–Drinfeld conjecture","desc":"Proves that the rational Grothendieck–Teichmüller Lie algebra, with the Ihara bracket, is freely generated by one element in each odd weight 3, 5, 7, …, resolving the Deligne–Drinfeld conjecture.","subject":"Number theory","lean":2,"applied":1,"difficulty":4,"year":1990,"note":"Structure of a Lie algebra from Galois theory. No route identified.","papers":[{"title":"The Deligne-Drinfeld conjecture","path":"preprints/The-Deligne-Drinfeld-conjecture-September-23-2026/paper.pdf"}]},{"id":"009","title":"Function-field reconstruction from Milnor K-theory and Galois data","desc":"Reconstructs function fields of transcendence degree at least two over algebraically closed constants from $K^{\\mathrm M}_1/\\ell$, $K^{\\mathrm M}_2/\\ell$, and their product. These data recover the perfect closure and constants when <i>ℓ<\/i> differs from the characteristic, and the original field and its named base in equal characteristic. Also proves Bogomolov–Pop reconstruction from abelian-by-central pro-<i>ℓ<\/i> Galois data away from the characteristic.","subject":"Number theory","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Anabelian geometry. No route identified.","papers":[{"title":"Reconstruction of Function Fields from Mod-ℓ Milnor K-Theory","path":"preprints/Reconstruction-of-Function-Fields-from-Mod-ell-Milnor-K-Theory-October-5-2026/mod-ell-bogomolov-pop.pdf"},{"title":"Reconstruction from Milnor K-theory modulo the characteristic","path":"preprints/Reconstruction-from-Milnor-K-theory-modulo-the-characteristic-October-5-2026/paper.pdf"},{"title":"The Bogomolov-Pop reconstruction theorem","path":"preprints/The-Bogomolov-Pop-reconstruction-theorem-September-23-2026/paper.pdf"}]},{"id":"010","title":"Unrestricted pro-modularity at the prime two","desc":"Every continuous odd absolutely irreducible two-dimensional 2-adic representation of $G_{\\mathbb Q}$ unramified outside finitely many primes occurs in a completed Hecke algebra at some odd tame level. Also proves classical modularity up to Tate twist for irreducible odd representations with these finiteness conditions that are de Rham at 2 with distinct Hodge–Tate weights, resolving the dyadic Fontaine–Mazur case without residual restrictions.","subject":"Number theory","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Galois representations. No route identified.","papers":[{"title":"Unrestricted pro-modularity at the prime two","path":"preprints/Unrestricted-pro-modularity-at-the-prime-two-October-4-2026/two-adic-promodularity.pdf"},{"title":"The Dimension of the Two-Adic Hecke Algebra at Odd Level","path":"preprints/The-Dimension-of-the-Two-Adic-Hecke-Algebra-at-Odd-Level-October-5-2026/two-adic-hecke.pdf"},{"title":"Fontaine–Mazur modularity at the prime 2","path":"preprints/Fontaine-Mazur-modularity-at-the-prime-2-September-23-2026/paper.pdf"}]},{"id":"011","title":"Prime-factor statistics of $p-1$","desc":"Proves that the normalized ordered logarithms of the prime factors of $p-1$, counted with multiplicity, converge jointly to the Poisson–Dirichlet law $\\mathrm{PD}(1)$ as <i>p<\/i> ranges uniformly over primes up to <i>x<\/i> and $x\\to\\infty$. This resolves the Ford–Konyagin–Luca conjecture. It also proves that infinitely many integers <i>n<\/i> have more than $n^{1-\\varepsilon}$ totient preimages, for every <i>ε<\/i> &gt; 0.","subject":"Number theory","lean":0,"applied":2,"difficulty":2,"year":null,"note":"The factor structure of p-1 enters the analysis of the Pollard p-1 method and smoothness assumptions in discrete-logarithm algorithms.","papers":[{"title":"Weighted dilation graphs, smooth shifted primes and totient fibers","path":"preprints/Weighted-Dilation-Graphs-Smooth-Shifted-Primes-and-Totient-Fibers-September-24-2026/paper.pdf"},{"title":"The Poisson-Dirichlet law for prime predecessors","path":"preprints/The-Poisson-Dirichlet-Law-for-Prime-Predecessors-September-24-2026/paper.pdf"},{"title":"Prime Predecessors with an Even Number of Prime Factors","path":"preprints/Prime-Predecessors-with-an-Even-Number-of-Prime-Factors-September-17-2026/paper.pdf"}]},{"id":"012","title":"Independent largest prime factors of consecutive integers","desc":"Resolves the Erdős–Pomerance joint Dickman conjecture: the logarithmic sizes of the largest prime factors of <i>n<\/i> and $n+1$ are asymptotically independent in ordinary natural density. In particular, the integers satisfying $P^+(n)\\lt P^+(n+1)$ have density 1/2.","subject":"Number theory","lean":1,"applied":1,"difficulty":4,"year":1978,"note":"Statistics of largest prime factors. A weak link to smoothness heuristics in factoring.","papers":[{"title":"The joint Dickman law for consecutive integers","path":"preprints/The-joint-Dickman-law-for-consecutive-integers-September-24-2026/paper.pdf"}]},{"id":"013","title":"Ostmann’s inverse Goldbach conjecture","desc":"Proves that no finite modification of the primes can be written as $A+B$ with $A,B\\subseteq\\mathbb Z_{\\ge0}$ each containing at least two elements. This resolves Ostmann&#x27;s inverse Goldbach conjecture on additive indecomposability.","subject":"Number theory","lean":1,"applied":1,"difficulty":4,"year":1956,"note":"Additive structure of the primes. No route identified.","papers":[{"title":"The additive indecomposability of the primes","path":"preprints/the-additive-indecomposability-of-the-primes-September-24-2026/paper.pdf"}]},{"id":"014","title":"Restricted geometric Langlands, global Arthur enhancements, and generic Ramanujan","desc":"Proves the restricted geometric Langlands equivalence for connected reductive groups on smooth projective connected curves over $\\overline{\\mathbb F}_q$ under the four stated Lie-theoretic characteristic hypotheses. Over arbitrary algebraically closed fields of characteristic <i>p<\/i> &gt; 0, the same conclusion holds assuming additionally that <i>p<\/i> is very good for the group and $p\\nmid |W_G|$. Over global function fields, proves Ramanujan at every place for globally generic cuspidal representations of split adjoint absolutely simple exceptional groups, without characteristic or ramification-depth restrictions, and at every unramified place for cuspidal representations of split adjoint absolutely simple groups with a generic unramified component. Assuming the finite-level Ramanujan–Arthur decomposition, constructs global Arthur enhancements of occurring cuspidal excursion parameters for split connected semisimple groups at full finite level, recovering the given parameters by diagonal specialization on the entire Weil group, including inertia.","subject":"Number theory","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Geometric Langlands. No route identified.","papers":[{"title":"Global Arthur Enhancements of Cuspidal Excursion Parameters","path":"preprints/Global-Arthur-Enhancements-of-Cuspidal-Excursion-Parameters-October-5-2026/manuscript.pdf"},{"title":"Rationality of the Canonical Unramified Arthur Filtration","path":"preprints/Rationality-of-the-Canonical-Unramified-Arthur-Filtration-September-24-2026/paper.pdf"},{"title":"Ramanujan-Arthur Decompositions of Cuspidal Functions at Full Finite Level","path":"preprints/Ramanujan-Arthur-Decompositions-of-Cuspidal-Functions-at-Full-Finite-Level-September-24-2026/paper.pdf"},{"title":"Temperedness at ramified places for globally generic exceptional groups","path":"preprints/Temperedness-at-ramified-places-for-globally-generic-exceptional-groups-October-5-2026/ramified-ramanujan.pdf"},{"title":"The Restricted Geometric Langlands Equivalence in Positive Characteristic","path":"preprints/The-Restricted-Geometric-Langlands-Equivalence-in-Positive-Characteristic-September-24-2026/paper.pdf"},{"title":"Constructible tame Hecke eigensheaves in positive characteristic","path":"preprints/Constructible-tame-Hecke-eigensheaves-in-positive-characteristic-October-5-2026/constructible-tame-hecke-eigensheaves-positive-characteristic.pdf"},{"title":"Tame Hecke Eigensheaves with Several Marked Points","path":"preprints/Tame-Hecke-Eigensheaves-with-Several-Marked-Points-October-5-2026/Tame-Hecke-Eigensheaves-with-Several-Marked-Points.pdf"},{"title":"Frobenius Structures on Tame Hecke Eigensheaves","path":"preprints/Frobenius-Structures-on-Tame-Hecke-Eigensheaves-October-5-2026/tame-hecke-frobenius.pdf"}]},{"id":"015","title":"Torus-packet equidistribution in prime, quartic, and sextic degrees","desc":"Proves Haar equidistribution without escape of mass for complete volume-weighted torus packets from totally real fields: arbitrary lattices and prescribed local types in fixed prime degree at least five, arbitrary-order Picard packets in primitive quartic fields, and maximal-order ideal-class packets in primitive sextic fields. Here primitive means having no proper intermediate field; the relevant order or field discriminant tends to infinity.","subject":"Number theory","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Homogeneous dynamics. No route identified.","papers":[{"title":"Equidistribution of Prime-Degree Torus Packets with Arbitrary Local Type","path":"preprints/Equidistribution-of-Prime-Degree-Torus-Packets-with-Arbitrary-Local-Type-September-24-2026/paper.pdf"},{"title":"Equidistribution of primitive quartic torus packets for arbitrary orders","path":"preprints/Equidistribution-of-Primitive-Quartic-Torus-Packets-for-Arbitrary-Orders-October-5-2026/quartic-torus-packets.pdf"},{"title":"Equidistribution of Primitive Sextic Torus Packets","path":"preprints/Equidistribution-of-Primitive-Sextic-Torus-Packets-October-5-2026/primitive-sextic-torus-packets.pdf"}]},{"id":"016","title":"Zilber–Pink in abelian varieties and the Siegel threefold","desc":"Proves the abelian Zilber–Pink conjecture over $\\overline{\\mathbb Q}$: every irreducible subvariety has finitely many maximal atypical subvarieties relative to its smallest containing torsion coset. It also proves the full curve case in the Siegel threefold $\\mathcal A_2$ for Hodge-generic curves defined over $\\overline{\\mathbb Q}$, without boundary or reduction assumptions.","subject":"Number theory","lean":0,"applied":1,"difficulty":4,"year":2002,"note":"Unlikely intersections. No route identified.","papers":[{"title":"The abelian Zilber–Pink conjecture","path":"preprints/The-Abelian-Zilber-Pink-Conjecture-September-24-2026/paper.pdf"},{"title":"The E×CM component of Zilber–Pink for curves in A2","path":"preprints/The-E-times-CM-Component-of-Zilber-Pink-for-Curves-in-A2-September-24-2026/paper.pdf"},{"title":"Quaternionic division points on curves in the Siegel threefold","path":"preprints/Quaternionic-Division-Points-on-Curves-in-the-Siegel-Threefold-September-24-2026/paper.pdf"},{"title":"Elliptic squares and Zilber–Pink for curves in A2","path":"preprints/Elliptic-Squares-and-Zilber-Pink-for-Curves-in-A2-September-24-2026/paper.pdf"}]},{"id":"017","title":"The irrationality exponent of <i>π<\/i> is 2","desc":"Proves that the irrationality exponent of <i>π<\/i> is exactly 2: for every <i>ε<\/i> &gt; 0 and all sufficiently large denominators <i>q<\/i>, every rational $p/q$ satisfies $|\\pi-p/q|\\ge q^{-2-\\varepsilon}$. This also proves convergence of the Flint–Hills series $\\sum_{n\\ge1}1/(n^3\\sin^2 n)$, with angles in radians.","subject":"Number theory","lean":1,"applied":1,"difficulty":5,"year":1953,"note":"Diophantine approximation of a single constant. No route identified.","papers":[{"title":"The irrationality exponent of pi is 2","path":"preprints/The-irrationality-exponent-of-pi-is-2-September-24-2026/paper.pdf"}]},{"id":"018","title":"The Margulis–Platonov conjecture over global fields","desc":"Proves the Margulis–Platonov conjecture over every global field, including function fields of characteristic two. For an absolutely almost simple simply connected algebraic group <i>G<\/i> over <i>k<\/i>, every noncentral abstract normal subgroup of $G(k)$ is the inverse image of an open normal subgroup in the finite product of its anisotropic nonarchimedean local groups.","subject":"Number theory","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Normal subgroups of arithmetic groups. No route identified.","papers":[{"title":"The Margulis–Platonov conjecture over global function fields","path":"preprints/The-Margulis-Platonov-conjecture-over-global-function-fields-October-5-2026/margulis-platonov-global-function-fields.pdf"},{"title":"The Margulis–Platonov conjecture over number fields","path":"preprints/The-Margulis-Platonov-conjecture-over-number-fields-September-23-2026/paper.pdf"}]},{"id":"019","title":"The local <i>p<\/i>-adic section conjecture and global consequences","desc":"Proves that rational points on every smooth proper geometrically connected curve of genus at least two over a finite extension of ℚ<sub><i>p<\/i><\/sub> correspond bijectively to conjugacy classes of sections of its full arithmetic étale fundamental group. It also proves Grothendieck&#x27;s section conjecture over ℚ for the modular curves $X_0(N)$ and $X_1(N)$ of genus at least two.","subject":"Number theory","lean":0,"applied":1,"difficulty":4,"year":1983,"note":"Anabelian geometry. No route identified.","papers":[{"title":"Étale covers with a prescribed exterior sheet","path":"preprints/Etale-covers-with-a-prescribed-exterior-sheet-September-24-2026/main.pdf"},{"title":"The p-adic section conjecture","path":"preprints/The-p-adic-section-conjecture-September-24-2026/main.pdf"}]},{"id":"020","title":"Squarefree quartics and power-free polynomial values","desc":"Proves the squarefree-values conjecture for irreducible integer quartics with no fixed prime-square divisor: squarefree values on positive integers have the predicted positive Euler-product density. More generally, establishes the $(d-2)$-power-free density for irreducible integer polynomials of degrees four through eight under the necessary local condition; together with Browning&#x27;s higher-degree theorem, this covers every <i>d<\/i> ≥ 4.","subject":"Number theory","lean":2,"applied":1,"difficulty":4,"year":null,"note":"Squarefree values of polynomials. No route identified.","papers":[{"title":"Squarefree values of quartics and power-free values of polynomials","path":"preprints/Squarefree-values-of-quartics-and-power-free-values-of-polynomials-September-24-2026/manuscript.pdf"}]},{"id":"021","title":"A quadratic bound for Jacobsthal’s function","desc":"Answers Jacobsthal&#x27;s quadratic-bound question: every interval of $Ck^2$ consecutive integers contains an integer coprime to any prescribed positive integer with at most <i>k<\/i> distinct prime divisors, for an absolute constant <i>C<\/i>. The bound is uniform over prime sets and interval positions and removes the classical logarithmic loss.","subject":"Number theory","lean":2,"applied":1,"difficulty":4,"year":1960,"note":"Sieve bound. A weak link to gaps between coprime residues in sieving algorithms.","papers":[{"title":"A quadratic bound for Jacobsthal&#x27;s function","path":"preprints/A-quadratic-bound-for-Jacobsthals-function-September-25-2026/paper.pdf"}]},{"id":"022","title":"The weak inhomogeneous Duffin–Schaeffer conjecture","desc":"Proves that for every real shift <i>γ<\/i> and finite-valued $\\psi:\\mathbb N\\to[0,\\infty)$, divergence of $\\sum_q\\phi(q)\\psi(q)/q$ implies $\\|qx-\\gamma\\|\\lt \\psi(q)$ for infinitely many <i>q<\/i>, for almost every <i>x<\/i>. Here <i>ϕ<\/i> is Euler&#x27;s totient and the norm is distance to the nearest integer. Numerators are unrestricted; no monotonicity or Diophantine condition on <i>γ<\/i> is needed.","subject":"Number theory","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Metric Diophantine approximation. No route identified.","papers":[{"title":"The Weak Inhomogeneous Duffin–Schaeffer Conjecture","path":"preprints/The-weak-inhomogeneous-Duffin-Schaeffer-conjecture-September-25-2026/paper.pdf"}]},{"id":"023","title":"Patterson&#x27;s first moment for cubic Gauss sums","desc":"Proves unconditionally the all-primary-prime form of Patterson’s first-moment asymptotic: normalized cubic Gauss sums over primary Eisenstein primes of norm at most <i>X<\/i>, including both conjugates, have an explicit positive main term of order $X^{5/6}/\\log X$. Every fixed nonzero prime-angle Fourier mode has smaller order.","subject":"Number theory","lean":1,"applied":1,"difficulty":4,"year":1978,"note":"Exponential sums. No route identified.","papers":[{"title":"An unconditional first moment for cubic Gauss sums","path":"preprints/An-unconditional-first-moment-for-cubic-Gauss-sums-September-25-2026/paper.pdf"}]},{"id":"024","title":"An asymptotic formula for the number of totients","desc":"Gives an asymptotic equivalent for the number $V(x)$ of distinct totient values up to <i>x<\/i>, with a positive bounded phase-dependent factor determined by convergent arithmetic approximations. In particular, $V(cx)/V(x)\\to c$ for every fixed <i>c<\/i> &gt; 0, answering Erdős and Hall’s scaling question.","subject":"Number theory","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Distribution of totient values. No route identified.","papers":[{"title":"An asymptotic formula for the number of totients","path":"preprints/An-asymptotic-formula-for-the-number-of-totients-September-25-2026/An-asymptotic-formula-for-the-number-of-totients-September-25-2026.pdf"}]},{"id":"025","title":"Short Egyptian fractions","desc":"Every rational $a/b$ with $1\\le a\\lt b$ is a sum of $O(\\log\\log b)$ distinct positive unit fractions. The worst-case minimum number of terms has the same order, resolving Erdős’s conjecture on short Egyptian fractions.","subject":"Number theory","lean":2,"applied":1,"difficulty":4,"year":1950,"note":"Representation of rationals. No route identified.","papers":[{"title":"Short Egyptian fractions","path":"preprints/Short-Egyptian-fractions-September-25-2026/Short-Egyptian-fractions-September-25-2026.pdf"}]},{"id":"026","title":"Positive lower density of large prime gaps","desc":"For every fixed <i>C<\/i> &gt; 0, a positive proportion of consecutive prime gaps exceed $C\\log p_n$, throughout every sufficiently large initial segment of the primes. The proportion may depend on <i>C<\/i>. Consequently, the indices where $p_n/n$ increases have positive lower density, answering Erdős and Prachar.","subject":"Number theory","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Distribution of prime gaps. No route identified.","papers":[{"title":"Positive lower density of large prime gaps","path":"preprints/Positive-lower-density-of-large-prime-gaps-September-25-2026/main.pdf"}]},{"id":"027","title":"Potential integral density on curve character varieties","desc":"Resolves the determinant-one curve case of Litt&#x27;s integral-density question. For every smooth connected complex algebraic curve and every rank, integral points become Zariski dense in every component of its SL<sub><i>r<\/i><\/sub> character variety over the full ring of integers of one number field. Prescribed quasi-unipotent boundary conjugacy classes are allowed, including nonsemisimple classes.","subject":"Number theory","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Character varieties. No route identified.","papers":[{"title":"Integral points on character varieties of curves","path":"preprints/Integral-points-on-character-varieties-of-curves-September-25-2026/paper.pdf"}]},{"id":"028","title":"Uniformly bounded components of Gaussian-prime graphs","desc":"Proves the Gaussian moat conjecture: no infinite walk through distinct Gaussian primes can have uniformly bounded steps. More strongly, for every distance bound <i>D<\/i>, the graph joining Gaussian primes at distance at most <i>D<\/i> has uniformly bounded finite component sizes, depending only on <i>D<\/i>, including primes on the coordinate axes.","subject":"Number theory","lean":2,"applied":1,"difficulty":4,"year":1962,"note":"Geometry of Gaussian primes. No route identified.","papers":[{"title":"Bounded-Step Walks on Gaussian Primes","path":"preprints/Bounded-Step-Walks-on-Gaussian-Primes-September-26-2026/paper.pdf"}]},{"id":"029","title":"Primitive roots for every admissible integer base","desc":"Proves the infinitude assertion in Artin&#x27;s primitive root conjecture for every integer <i>a<\/i> that is neither −1 nor a square. For each such base, at least $c_a x/(\\log x)^2$ primes in every sufficiently large interval $(x,2x)$ have primitive root <i>a<\/i>, with $c_a\\gt 0$.","subject":"Number theory","lean":0,"applied":2,"difficulty":5,"year":1927,"note":"Discrete-logarithm cryptography picks generators on the assumption that a fixed base is a primitive root for many primes. The theorem confirms it without the Riemann hypothesis.","papers":[{"title":"Primitive roots for every admissible integer base","path":"preprints/Primitive-roots-for-every-admissible-integer-base-October-4-2026/primitive-roots-all-integer-bases.pdf"},{"title":"Simultaneous primitive roots: a conditional lower bound for prime bases","path":"preprints/Simultaneous-primitive-roots-a-conditional-lower-bound-for-prime-bases-October-4-2026/simultaneous-primitive-roots-conditional-lower-bound-prime-bases.pdf"}]},{"id":"030","title":"Modularity of elliptic curves over imaginary quadratic fields","desc":"Proves the modularity conjecture for elliptic curves over imaginary quadratic fields: every elliptic curve over every imaginary quadratic field is modular, with matching local parameters at every place.","subject":"Number theory","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Modularity. No route identified.","papers":[{"title":"Modularity of elliptic curves over imaginary quadratic fields","path":"preprints/Modularity-of-elliptic-curves-over-imaginary-quadratic-fields-October-4-2026/paper.pdf"}]},{"id":"031","title":"Uchida’s conjecture for open homomorphisms of Galois groups","desc":"Proves Uchida&#x27;s conjecture: every continuous open homomorphism between Galois groups of possibly infinite solvably closed Galois extensions of number fields comes from a unique equivariant field embedding in the opposite direction. No restriction on the kernel or separate cyclotomic-compatibility assumption is needed.","subject":"Number theory","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Anabelian geometry. No route identified.","papers":[{"title":"Open Homomorphisms of Global Solvably Closed Galois Groups","path":"preprints/Open-Homomorphisms-of-Global-Solvably-Closed-Galois-Groups-October-5-2026/open-homomorphisms-solvably-closed-galois-groups.pdf"}]},{"id":"032","title":"Hodge and Kuga–Satake results for all projective K3 surfaces","desc":"Proves the rational Hodge conjecture for every complex CM abelian variety, in every dimension and codimension. Through Milne&#x27;s theorems, this also gives the Tate conjecture for all abelian varieties over finite fields and the Hodge standard conjecture for abelian varieties in every characteristic. Companion results prove rational Hodge for arbitrary products of projective complex K3 surfaces and algebraicity of the Kuga–Satake correspondence for every such surface.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":5,"year":1950,"note":"Algebraic cycles. No route identified.","papers":[{"title":"The rational Hodge conjecture for products of K3 surfaces","path":"preprints/The-rational-Hodge-conjecture-for-products-of-K3-surfaces-October-4-2026/hodge-conjecture-products-k3.pdf"},{"title":"Algebraicity of Kuga–Satake Correspondences for K3 Surfaces","path":"preprints/Algebraicity-of-Kuga-Satake-Correspondences-for-K3-Surfaces-October-3-2026/manuscript.pdf"},{"title":"The rational Hodge conjecture for CM abelian varieties","path":"preprints/The-rational-Hodge-conjecture-for-CM-abelian-varieties-September-30-2026/paper.pdf"},{"title":"Algebraic Kuga–Satake correspondences and Hodge conjectures on a K3 quadratic locus","path":"preprints/Algebraic-Kuga-Satake-correspondences-and-Hodge-conjectures-on-a-K3-quadratic-locus-September-30-2026/paper.pdf"},{"title":"Weil classes and Hodge classes on abelian powers","path":"preprints/Weil-classes-and-Hodge-classes-on-abelian-powers-September-30-2026/paper.pdf"},{"title":"Abelian covers, Gale correspondences, and the Hodge conjecture for powers","path":"preprints/Abelian-covers-Gale-correspondences-and-the-Hodge-conjecture-for-powers-September-30-2026/paper.pdf"},{"title":"Algebraicity of Weil classes on split abelian eightfolds","path":"preprints/Algebraicity-of-Weil-classes-on-split-abelian-eightfolds-September-18-2026/paper.pdf"},{"title":"A Conditional Reduction for Algebraic Kuga–Satake Correspondences","path":"preprints/A-Conditional-Reduction-for-Algebraic-Kuga-Satake-Correspondences-September-10-2026/paper.pdf"}]},{"id":"033","title":"Iitaka subadditivity, variation, and logarithmic additivity","desc":"Proves Campana&#x27;s orbifold Iitaka subadditivity conjecture for smooth Fujiki-class-$\\mathcal C$ manifolds with rational simple-normal-crossing boundaries. For projective fibrations $f:U\\to V$ of smooth complex quasi-projective varieties with connected fibers, general fiber <i>F<\/i>, and $\\bar\\kappa(V)\\ge0$, proves Popa&#x27;s inequality $\\bar\\kappa(U)\\ge\\kappa(F)+\\max\\{\\bar\\kappa(V),\\mathop{\\mathrm{Var}}\\nolimits (f)\\}$, where variation measures the whole geometric generic fiber.","subject":"Algebraic and complex geometry","lean":1,"applied":1,"difficulty":4,"year":1972,"note":"Birational classification. No route identified.","papers":[{"title":"Orbifold and logarithmic Iitaka subadditivity","path":"preprints/Orbifold-and-logarithmic-Iitaka-subadditivity-September-26-2026/paper.pdf"},{"title":"Logarithmic Kodaira dimension and whole-fiber variation","path":"preprints/Logarithmic-Kodaira-dimension-and-whole-fiber-variation-September-26-2026/paper.pdf"},{"title":"The reverse logarithmic Kodaira inequality and additivity","path":"preprints/The-reverse-logarithmic-Kodaira-inequality-and-additivity-September-26-2026/paper.pdf"},{"title":"Projective Hodge lines and ordinary Iitaka subadditivity","path":"preprints/Projective-Hodge-lines-and-ordinary-Iitaka-subadditivity-September-27-2026/paper.pdf"},{"title":"B-semiampleness for compact log-smooth Kähler fibrations","path":"preprints/B-semiampleness-for-compact-log-smooth-Kahler-fibrations-September-10-2026/paper.pdf"}]},{"id":"034","title":"Log abundance for compact Kähler spaces under logarithmic Iitaka subadditivity","desc":"Using logarithmic Iitaka subadditivity, proves log abundance in every dimension for normal compact Kähler log canonical pairs with effective rational boundary: an analytically nef ℚ-Cartier adjoint is semiample. It also proves projective log abundance over every algebraically closed field of characteristic zero and the effective Iitaka fibration conjecture for smooth projective varieties of nonnegative Kodaira dimension in that setting. A further result resolves the finite-rational-coefficient index conjecture for connected projective semi-log-canonical log Calabi–Yau pairs over such fields in each fixed dimension and for each fixed finite set of rational boundary coefficients, with a uniform index independent of the number of components.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":5,"year":null,"note":"Minimal model program. No route identified.","papers":[{"title":"Log abundance for compact Kähler spaces under logarithmic Iitaka subadditivity","path":"preprints/Log-abundance-for-compact-Kahler-spaces-under-logarithmic-Iitaka-subadditivity-October-4-2026/main.pdf"},{"title":"Uniform indices for semi-log-canonical log Calabi–Yau pairs","path":"preprints/Uniform-indices-for-semi-log-canonical-log-Calabi-Yau-pairs-October-5-2026/uniform-slc-index.pdf"},{"title":"Conditional good minimal models for compact Kähler fourfolds","path":"preprints/Conditional-good-minimal-models-for-compact-Kahler-fourfolds-October-5-2026/paper.pdf"},{"title":"Log abundance in characteristic zero","path":"preprints/Log-abundance-in-characteristic-zero-September-24-2026/paper.pdf"},{"title":"Minimal metrics and interior injectivity for nef adjoints","path":"preprints/Minimal-metrics-and-interior-injectivity-for-nef-adjoints-September-27-2026/paper.pdf"},{"title":"Fourfold nonvanishing by minimal metrics and moving jets","path":"preprints/Fourfold-nonvanishing-by-minimal-metrics-and-moving-jets-September-27-2026/paper.pdf"},{"title":"Lifting sections from the reduced support of an adjoint","path":"preprints/Lifting-sections-from-the-reduced-support-of-an-adjoint-September-27-2026/paper.pdf"},{"title":"Schnell fiber spaces and good canonical models","path":"preprints/Schnell-fiber-spaces-and-good-canonical-models-September-24-2026/paper.pdf"},{"title":"Uniform log Iitaka fibrations and bounded moduli denominators","path":"preprints/Uniform-log-Iitaka-fibrations-and-bounded-moduli-denominators-October-4-2026/uniform-log-iitaka.pdf"},{"title":"Uniform Pluricanonical Iitaka Fibrations","path":"preprints/Uniform-Pluricanonical-Iitaka-Fibrations-October-3-2026/paper.pdf"},{"title":"Relative denominators and effective systems for log Calabi-Yau fibrations","path":"preprints/Relative-denominators-and-effective-systems-for-log-Calabi-Yau-fibrations-September-27-2026/paper.pdf"},{"title":"Arithmetic Stein-degree bounds for log Calabi–Yau pairs","path":"preprints/Arithmetic-Stein-degree-bounds-for-log-Calabi-Yau-pairs-September-25-2026/paper.pdf"},{"title":"Uniform effective log Iitaka fibrations for fourfolds","path":"preprints/Uniform-effective-log-Iitaka-fibrations-for-fourfolds-September-26-2026/paper.pdf"},{"title":"Abundance after nonvanishing for compact Kähler fourfolds","path":"preprints/Abundance-after-nonvanishing-for-compact-Kahler-fourfolds-September-27-2026/paper.pdf"}]},{"id":"035","title":"Log-canonical threefold abundance in numerical dimension one","desc":"Proves log abundance for projective log canonical threefold pairs over algebraically closed fields of characteristic <i>p<\/i> &gt; 3 when the effective boundary is rational and the ℚ-Cartier adjoint is nef of numerical dimension one. The adjoint is semiample, without requiring the original variety to be terminal or ℚ-factorial.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Minimal model program in positive characteristic. No route identified.","papers":[{"title":"Log abundance in numerical dimension one for threefolds in positive characteristic","path":"preprints/Log-abundance-in-numerical-dimension-one-for-threefolds-in-positive-characteristic-October-5-2026/paper.pdf"},{"title":"Abundance in numerical dimension one for terminal threefolds in positive characteristic","path":"preprints/Abundance-in-numerical-dimension-one-for-terminal-threefolds-in-positive-characteristic-September-24-2026/paper.pdf"}]},{"id":"036","title":"Numerical semiampleness and generalized minimal models","desc":"Proves numerical semiampleness for nef adjoints $K_X+B+M$ with $K_X+B$ pseudo-effective and <i>M<\/i> nef rational, for projective klt rational pairs over algebraically closed characteristic-zero fields and smooth compact Kähler rational klt simple-normal-crossing pairs, using Bott–Chern cohomology in the latter case. Separately, projective generalized log canonical rational pairs over such fields admit minimal models for pseudo-effective adjoints and Mori fiber spaces otherwise, with nef b-data fixed.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Minimal model program. No route identified.","papers":[{"title":"Numerical semiampleness of nef adjoint classes on compact Kähler manifolds","path":"preprints/Numerical-semiampleness-of-nef-adjoint-classes-on-compact-Kahler-manifolds-October-4-2026/numerical-generalized-abundance.pdf"},{"title":"Numerical Semiampleness of Nef Adjoint Divisors","path":"preprints/Numerical-Semiampleness-of-Nef-Adjoint-Divisors-October-3-2026/paper.pdf"},{"title":"Minimal models and Mori fibre spaces for generalized log canonical Q-pairs","path":"preprints/Minimal-models-and-Mori-fibre-spaces-for-generalized-log-canonical-Q-pairs-September-24-2026/paper.pdf"},{"title":"Minimal models in numerical dimension one","path":"preprints/Minimal-models-in-numerical-dimension-one-September-24-2026/paper.pdf"}]},{"id":"037","title":"The ordinary-double-point volume gap","desc":"Proves the ordinary-double-point volume-gap conjecture: every singular complex algebraic klt germ of dimension <i>n<\/i> ≥ 2, with zero boundary, has normalized volume at most $2(n-1)^n$. Equality holds precisely for an analytic ordinary double point.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Singularity invariants. No route identified.","papers":[{"title":"The ordinary-double-point gap in every dimension","path":"preprints/The-ordinary-double-point-gap-in-every-dimension-September-24-2026/paper.pdf"},{"title":"The normalized-volume gap in dimension four","path":"preprints/The-normalized-volume-gap-in-dimension-four-September-24-2026/paper.pdf"}]},{"id":"038","title":"Fujita’s freeness conjecture","desc":"Proves Fujita&#x27;s freeness conjecture at its sharp bound in every dimension: for a smooth projective complex variety <i>X<\/i> of dimension <i>n<\/i> and an ample line bundle <i>L<\/i>, the adjoint $K_X+mL$ is globally generated for every integer $m\\ge n+1$.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":4,"year":1985,"note":"Positivity of line bundles. No route identified.","papers":[{"title":"Fujita&#x27;s freeness conjecture","path":"preprints/Fujitas-freeness-conjecture-September-23-2026/Fujitas-freeness-conjecture-September-23-2026.pdf"}]},{"id":"039","title":"Nagata’s conjecture and maximal Seshadri constants","desc":"Proves Nagata&#x27;s strict inequality $\\sum_i m_i\\lt d\\sqrt r$ for every nonzero effective plane curve of degree <i>d<\/i> through <i>r<\/i> ≥ 10 very general complex points, with arbitrary multiplicities <i>m<\/i><sub><i>i<\/i><\/sub>. It also proves maximal multipoint Seshadri constants $(L^n/r)^{1/n}$ for every smooth polarized projective variety of dimension <i>n<\/i> ≥ 2 and all sufficiently large <i>r<\/i>: at very general points over ℂ, and at the geometric generic tuple over any algebraically closed field of positive characteristic.","subject":"Algebraic and complex geometry","lean":2,"applied":1,"difficulty":5,"year":1959,"note":"Bounds the degree of plane curves through prescribed points with multiplicity. A weak link to multivariate interpolation.","papers":[{"title":"Nagata&#x27;s conjecture for plane curves","path":"preprints/Nagatas-Conjecture-for-Plane-Curves-September-23-2026/main.pdf"},{"title":"Maximal Seshadri constants on arbitrary polarized surfaces","path":"preprints/Maximal-Seshadri-Constants-on-Arbitrary-Polarized-Surfaces-September-23-2026/main.pdf"},{"title":"Maximal Multipoint Seshadri Constants in Higher Dimensions","path":"preprints/Maximal-Multipoint-Seshadri-Constants-in-Higher-Dimensions-October-5-2026/main.pdf"},{"title":"Maximal multipoint Seshadri constants in positive characteristic","path":"preprints/Maximal-multipoint-Seshadri-constants-in-positive-characteristic-October-5-2026/seshadri-positive-characteristic.pdf"}]},{"id":"040","title":"Bloch’s conjecture for complex surfaces","desc":"Proves Bloch&#x27;s conjecture: for every smooth connected projective complex surface <i>S<\/i> with $p_g(S)=0$, the Albanese map $\\mathrm{CH}_0(S)^0\\to\\mathrm{Alb}(S)(\\mathbb C)$ on integral degree-zero zero-cycles is an isomorphism. This combines the new $p_g=q=0$ theorem with the classical theorem of Bloch, Kas, and Lieberman.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":5,"year":1975,"note":"Algebraic cycles. No route identified.","papers":[{"title":"Bloch’s conjecture for surfaces with p_g=0","path":"preprints/Blochs-Conjecture-for-Surfaces-with-pg-equals-q-equals-0-September-24-2026/paper.pdf"}]},{"id":"041","title":"Hyperkähler SYZ and projective-space bases","desc":"Proves the strong hyperkähler SYZ conjecture: every holomorphic line bundle with nonzero nef isotropic first Chern class on a compact irreducible holomorphic symplectic Kähler manifold is semiample. It also proves that every projective Lagrangian fibration with normal projective base has projective space as its base, in every dimension and deformation type.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Hyperkähler geometry. No route identified.","papers":[{"title":"Projective-space bases of Lagrangian fibrations","path":"preprints/Projective-Space-Bases-of-Lagrangian-Fibrations-September-23-2026/main.pdf"},{"title":"The strong hyperkähler SYZ conjecture","path":"preprints/The-Strong-Hyperkahler-SYZ-Conjecture-September-23-2026/main.pdf"}]},{"id":"042","title":"Oka classification for minimal compact complex surfaces: Kodaira dimension zero and class VII","desc":"Proves that every complex K3 surface is Oka, including nonprojective surfaces. More generally, every connected minimal compact complex surface of Kodaira dimension zero is Oka; a connected minimal compact complex surface of class VII is Oka exactly when it is a Hopf or Enoki surface.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Complex surfaces. No route identified.","papers":[{"title":"Every complex K3 surface is Oka","path":"preprints/Every-complex-K3-surface-is-Oka-September-23-2026/paper.pdf"}]},{"id":"043","title":"<i>P<\/i> = <i>W<\/i> for fixed-determinant SL<sub><i>n<\/i><\/sub> moduli spaces","desc":"Proves $P_k=W_{2k}=W_{2k+1}$ on the full rational cohomology of smooth coprime fixed-determinant, trace-free Higgs moduli spaces and their character varieties for composite ranks over smooth projective complex curves of genus at least two. This includes variant cohomology and, together with the known prime-rank theorems, establishes the fixed-determinant <i>P<\/i> = <i>W<\/i> conjecture in every coprime rank.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":3,"year":2010,"note":"Cohomology of moduli spaces. No route identified.","papers":[{"title":"P=W in composite rank for fixed determinant","path":"preprints/P-equals-W-in-composite-rank-for-fixed-determinant-September-24-2026/P-equals-W-in-composite-rank-for-fixed-determinant-September-24-2026.pdf"}]},{"id":"044","title":"The equivariant cohomological Hikita conjecture","desc":"Proves the equivariant cohomological Hikita correspondence for every finite quiver, including loops and multiple arrows, with arbitrary dimension and framing vectors and commuting flavor torus. When every semistable point is stable and the gauge action is free, the equivariant cohomology of the Nakajima variety is canonically the coordinate ring of the scheme-theoretic cocharacter-fixed locus of its flavor-deformed Coulomb branch.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Geometric representation theory. No route identified.","papers":[{"title":"The equivariant cohomological Hikita conjecture for arbitrary quivers","path":"preprints/The-equivariant-cohomological-Hikita-conjecture-for-arbitrary-quivers-September-24-2026/main.pdf"}]},{"id":"046","title":"Shafarevich counterexamples in dimension two and with large fundamental group","desc":"Constructs a smooth projective complex fourfold with large fundamental group whose universal cover contains no positive-dimensional compact analytic subvariety but is neither Stein nor holomorphically convex. A separate smooth projective complex surface already disproves unrestricted Shafarevich holomorphic convexity in dimension two.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":4,"year":1972,"note":"Universal covers of projective varieties. No route identified.","papers":[{"title":"A projective fourfold with large fundamental group and non-Stein universal cover","path":"preprints/A-projective-fourfold-with-large-fundamental-group-and-non-Stein-universal-cover-October-5-2026/large-fundamental-group-non-stein.pdf"},{"title":"A surface counterexample to Shafarevich holomorphic convexity","path":"preprints/A-surface-counterexample-to-Shafarevich-holomorphic-convexity-September-23-2026/paper.pdf"}]},{"id":"047","title":"Zariski cancellation and affine fibrations over the complex numbers","desc":"Constructs an integral complex affine fourfold $X\\not\\cong\\mathbb A^4$ with $X\\times\\mathbb A^1\\cong\\mathbb A^5$, disproving affine-space cancellation over ℂ in dimension four. It also disproves the Dolgachev–Weisfeiler affine-fibration conjecture: smooth surjections $X\\to\\mathbb A^1$ and $\\mathbb A^5\\to\\mathbb A^2$ have every residue-field fiber isomorphic to affine three-space but are not Zariski-locally trivial.","subject":"Algebraic and complex geometry","lean":2,"applied":1,"difficulty":4,"year":1949,"note":"Affine algebraic geometry. No route identified.","papers":[{"title":"An explicit failure of complex affine-space cancellation","path":"preprints/An-explicit-failure-of-complex-affine-space-cancellation-September-23-2026/paper.pdf"}]},{"id":"048","title":"A characteristic-zero counterexample to Lipman–Zariski","desc":"Constructs a singular normal affine complex surface with free rank-two tangent sheaf, disproving the characteristic-zero Lipman–Zariski conjecture.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":4,"year":1965,"note":"Singularity theory. No route identified.","papers":[{"title":"A singular normal affine surface with free tangent sheaf","path":"preprints/A-singular-normal-affine-surface-with-free-tangent-sheaf-September-23-2026/paper.pdf"}]},{"id":"049","title":"A stable-coordinate counterexample in four variables","desc":"Constructs a polynomial in four complex variables that is not a coordinate but becomes one after adjoining a single variable, disproving the Stable Coordinate conjecture in four variables. Every fiber is affine three-space, yet none of its embeddings is rectifiable, also disproving the Abhyankar–Sathaye conjecture even when all fibers are affine spaces.","subject":"Algebraic and complex geometry","lean":2,"applied":1,"difficulty":3,"year":null,"note":"Polynomial automorphisms. No route identified.","papers":[{"title":"A stable coordinate that is not a coordinate in four variables","path":"preprints/A-stable-coordinate-that-is-not-a-coordinate-in-four-variables-October-5-2026/stable-coordinate-four-variables.pdf"},{"title":"An explicit noncoordinate polynomial with affine three-space zero fibre","path":"preprints/An-explicit-noncoordinate-polynomial-with-affine-three-space-zero-fibre-September-24-2026/paper.pdf"}]},{"id":"050","title":"A counterexample to Griffiths’ positivity conjecture","desc":"Constructs ample rank-two bundles on $\\mathbb P^1\\times\\mathbb P^1$ with no smooth Hermitian metric of strictly Griffiths-positive curvature, disproving Griffiths&#x27; positivity conjecture already on the quadric surface.","subject":"Algebraic and complex geometry","lean":2,"applied":1,"difficulty":4,"year":1969,"note":"Positivity of vector bundles. No route identified.","papers":[{"title":"Ample rank-two bundles on the quadric surface without Griffiths-positive metrics","path":"preprints/ample-rank-two-bundles-on-the-quadric-surface-without-griffiths-positive-metrics-September-24-2026/paper.pdf"}]},{"id":"051","title":"Kobayashi’s canonical-ampleness conjecture","desc":"Every compact connected Kähler manifold of positive complex dimension with no nonconstant entire curve has ample canonical bundle and is therefore projective. This proves Kobayashi&#x27;s canonical-ampleness conjecture in the smooth compact Kähler setting.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":4,"year":1970,"note":"Complex hyperbolicity. No route identified.","papers":[{"title":"Canonical ampleness of compact hyperbolic Kähler manifolds","path":"preprints/Canonical-ampleness-of-compact-hyperbolic-Kahler-manifolds-September-23-2026/canonical-ampleness.pdf"}]},{"id":"052","title":"Tangent splittings and product decompositions","desc":"A splitting of the tangent bundle of a compact Kähler manifold into two integrable holomorphic subbundles induces a compatible product decomposition of its universal cover, proving the two-summand form of Beauville&#x27;s splitting conjecture. On smooth rationally connected projective manifolds, both summands are automatically integrable, establishing Höring&#x27;s conjecture and the corresponding product decomposition.","subject":"Algebraic and complex geometry","lean":2,"applied":1,"difficulty":3,"year":2000,"note":"Kähler geometry. No route identified.","papers":[{"title":"Universal-cover splitting for compact Kähler manifolds","path":"preprints/Universal-cover-splitting-for-compact-Kahler-manifolds-September-23-2026/paper.pdf"},{"title":"Integrability of split tangent bundles on rationally connected manifolds","path":"preprints/Integrability-of-split-tangent-bundles-on-rationally-connected-manifolds-September-23-2026/main.pdf"}]},{"id":"053","title":"A counterexample to Pixton completeness in Chow","desc":"Constructs a tautological relation on a moduli space of stable pointed curves that vanishes in rational Chow, hence in rational cohomology, but lies outside Pixton&#x27;s original relation span. This disproves the Chow and rational-cohomological forms of his original completeness conjecture.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":2,"year":2012,"note":"Moduli of curves. No route identified.","papers":[{"title":"A high-arity counterexample to Pixton completeness in Chow","path":"preprints/A-high-arity-counterexample-to-Pixton-completeness-in-Chow-September-24-2026/paper.pdf"}]},{"id":"054","title":"Irrational cubic fourfolds with Hodge-theoretic and categorical K3 associations","desc":"For every sufficiently large admissible Hassett discriminant, a very general smooth complex cubic fourfold is irrational despite having both an untwisted geometric K3 category and an integral Hodge-theoretic K3 association. This disproves Kuznetsov&#x27;s rationality conjecture and the sufficiency of the associated-K3 criterion for rationality; the discriminant threshold is ineffective.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":5,"year":null,"note":"Rationality of cubic fourfolds. No route identified.","papers":[{"title":"Irrational cubic fourfolds with geometric K3 categories","path":"preprints/Irrational-cubic-fourfolds-with-geometric-K3-categories-September-24-2026/Irrational-cubic-fourfolds-with-geometric-K3-categories-September-24-2026.pdf"}]},{"id":"055","title":"Gepner symmetry and large-volume stability on threefolds","desc":"Proves Toda&#x27;s Gepner conjecture for every smooth complex quintic threefold, constructing a numerical Bridgeland stability condition with the prescribed phase shift 2/5. Also constructs numerical Bridgeland stability conditions at every sufficiently large volume on all smooth projective complex threefolds with trivial canonical bundle, with the exact ordinary and square-root-Todd central charges.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Stability conditions. No route identified.","papers":[{"title":"A Gepner stability condition on every smooth quintic threefold","path":"preprints/A-Gepner-stability-condition-on-every-smooth-quintic-threefold-September-24-2026/paper.pdf"},{"title":"Prescribed large-volume charges on threefolds with trivial canonical bundle","path":"preprints/Prescribed-large-volume-charges-on-threefolds-with-trivial-canonical-bundle-September-24-2026/paper.pdf"}]},{"id":"056","title":"Termination of projective and Kähler fourfold minimal model programs","desc":"Proves termination of every existing generalized log canonical flip sequence on globally Weil ℚ-factorial compact Kähler fourfolds, with rational boundary, fixed rational analytically nef b-data, and projective small flip diagrams with the prescribed ample signs. Also proves termination of arbitrary permitted minimal model programs for projective log canonical fourfolds with rational boundary in characteristic zero.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Minimal model program. No route identified.","papers":[{"title":"Termination of generalized log canonical flips on compact Kähler fourfolds","path":"preprints/Termination-of-generalized-log-canonical-flips-on-compact-Kahler-fourfolds-October-5-2026/termination-generalized-lc-kahler-fourfolds.pdf"},{"title":"Termination of generalized-canonical flips on compact Kähler fourfolds","path":"preprints/Termination-of-generalized-canonical-flips-on-compact-Kahler-fourfolds-October-5-2026/termination-generalized-terminal-flips-compact-kahler-fourfolds.pdf"},{"title":"Termination for projective log canonical fourfolds with rational boundary","path":"preprints/Termination-for-projective-log-canonical-fourfolds-with-rational-boundary-September-24-2026/paper.pdf"},{"title":"Finite ordinary minimal model programs on compact Kähler fourfolds","path":"preprints/Finite-ordinary-minimal-model-programs-on-compact-Kahler-fourfolds-October-5-2026/paper.pdf"},{"title":"Finite ordinary minimal model programs on compact Kähler fourfolds","path":"preprints/Finite-ordinary-minimal-model-programs-on-compact-Kahler-fourfolds-September-24-2026/paper.pdf"}]},{"id":"057","title":"Fundamental groups of special complex varieties and root orbifolds","desc":"Proves Campana&#x27;s abelianity conjecture: special compact Kähler manifolds have virtually abelian fundamental groups. Using this theorem, establishes the same conclusion for order-two root orbifolds of smooth projective complex fourfolds along one nonempty smooth connected divisor, when special in the stated differential-line sense. For smooth special complex quasi-projective varieties, proves that every finite-dimensional complex linear representation of the fundamental group has virtually nilpotent image of class at most two.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":3,"year":2004,"note":"Fundamental groups of Kähler manifolds. No route identified.","papers":[{"title":"The abelianity conjecture for special compact Kähler manifolds","path":"preprints/The-abelianity-conjecture-for-special-compact-Kahler-manifolds-September-23-2026/paper.pdf"},{"title":"Two-step monodromy of special quasi-projective varieties","path":"preprints/Two-step-monodromy-of-special-quasi-projective-varieties-September-24-2026/paper.pdf"},{"title":"A conditional abelianity theorem for special fourfold pairs with a half-weight divisor","path":"preprints/A-conditional-abelianity-theorem-for-special-fourfold-pairs-with-a-half-weight-divisor-October-5-2026/main.pdf"}]},{"id":"058","title":"Semialgebraic universal covers and bounded domains","desc":"Proves the Kollár–Pardon conjecture: the semialgebraic universal covers of connected normal projective complex varieties are exactly products $D\\times\\mathbb C^m\\times F$, with <i>D<\/i> bounded symmetric and <i>F<\/i> simply connected, normal, and projective. A universal cover is quasi-projective exactly when the bounded symmetric factor is absent. In particular, a smooth projective variety covered by ℂ<sup><i>n<\/i><\/sup> has a finite étale cover by an abelian variety.","subject":"Algebraic and complex geometry","lean":2,"applied":1,"difficulty":2,"year":null,"note":"Universal covers of projective varieties. No route identified.","papers":[{"title":"Semialgebraic universal covers of normal projective varieties","path":"preprints/Semialgebraic-universal-covers-of-normal-projective-varieties-September-24-2026/paper.pdf"},{"title":"Symmetry of semialgebraic bounded domains with compact quotient","path":"preprints/Symmetry-of-semialgebraic-bounded-domains-with-compact-quotient-September-24-2026/paper.pdf"}]},{"id":"059","title":"Counterexamples to Zariski’s multiplicity conjecture","desc":"Disproves Zariski&#x27;s multiplicity conjecture by constructing reduced holomorphic hypersurface germs that are ambiently homeomorphic but have different multiplicities. The examples include hypersurfaces in ℂ<sup>4<\/sup> with isolated critical points and multiplicities four and five.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":5,"year":1971,"note":"Singularity theory. No route identified.","papers":[{"title":"Ambiently homeomorphic isolated hypersurfaces of multiplicities two and three","path":"preprints/Ambiently-homeomorphic-isolated-hypersurfaces-of-multiplicities-two-and-three-September-24-2026/paper.pdf"},{"title":"Ambiently homeomorphic isolated hypersurface germs in ℂ⁴ with multiplicities four and five","path":"preprints/Ambiently-homeomorphic-isolated-hypersurface-germs-in-C4-with-multiplicities-four-and-five-September-27-2026/paper.pdf"}]},{"id":"060","title":"The Global Spherical Shell conjecture","desc":"Every connected minimal compact complex surface of class VII with $b_2\\gt 0$ contains a global spherical shell, proving the positive-<i>b<\/i><sub>2<\/sub> Global Spherical Shell conjecture. Such a shell is a holomorphically embedded neighborhood of the standard three-sphere in $\\mathbb C^2\\setminus\\{0\\}$ whose complement is connected.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":4,"year":1984,"note":"Complex surfaces. No route identified.","papers":[{"title":"Global Spherical Shells on Minimal Surfaces of Class VII","path":"preprints/Global-Spherical-Shells-on-Minimal-Surfaces-of-Class-VII-September-24-2026/paper.pdf"}]},{"id":"062","title":"Projective contact classification and the LeBrun–Salamon conjecture","desc":"Proves the LeBrun–Salamon conjecture: every closed connected positive quaternionic-Kähler manifold of real dimension at least eight is homothetic to a compact symmetric Wolf space. It also proves contact-Fano homogeneity and classifies smooth connected complex projective contact manifolds of complex dimension at least three: those with $b_2=1$ are adjoint varieties with their canonical contact structures, while those with $b_2\\ge2$ have underlying manifold $\\mathbb P(T^*Z)$ for a smooth projective variety <i>Z<\/i>.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":4,"year":1994,"note":"Quaternionic-Kähler geometry. No route identified.","papers":[{"title":"Contact Fano manifolds and the LeBrun–Salamon conjecture","path":"preprints/Contact-Fano-manifolds-and-the-LeBrun-Salamon-conjecture-September-23-2026/paper.pdf"}]},{"id":"063","title":"The generalized Mukai conjecture","desc":"Proves the generalized Mukai conjecture: every positive-dimensional smooth complex projective Fano manifold of dimension <i>n<\/i>, Picard number <i>ρ<\/i> and pseudoindex <i>ι<\/i> satisfies $\\rho(\\iota-1)\\le n$, with equality exactly for $(\\mathbb P^{\\iota-1})^\\rho$. Here the pseudoindex is the least anticanonical degree of a rational curve.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Fano manifolds. No route identified.","papers":[{"title":"The generalized Mukai conjecture","path":"preprints/The-Generalized-Mukai-Conjecture-September-24-2026/article.pdf"}]},{"id":"064","title":"Topological triviality of <i>μ<\/i>-constant surface singularities","desc":"Proves topological right-triviality for every holomorphic one-parameter family of isolated hypersurface singularities in ℂ<sup>3<\/sup> with constant Milnor number, resolving the surface case of the <i>μ<\/i>-constant problem. After shrinking the parameter disk and representatives, ambient homeomorphisms vary jointly continuously, fix the origin section and preserve the defining functions.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":4,"year":1976,"note":"Singularity theory. No route identified.","papers":[{"title":"Topological triviality of mu-constant families of surface singularities","path":"preprints/Topological-triviality-of-mu-constant-families-of-surface-singularities-September-24-2026/main.pdf"}]},{"id":"065","title":"Virasoro constraints for complete intersections and projective-bundle towers","desc":"Proves the full ordinary unreduced descendant Virasoro conjecture for smooth complete intersections in complex projective space, in every genus and curve class with arbitrary cohomology insertions. The constraints also pass from any smooth projective complex base satisfying them to the projectivization of every algebraic vector bundle of rank at least two, and hence to projective-bundle towers.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":4,"year":1997,"note":"Gromov-Witten theory. No route identified.","papers":[{"title":"Virasoro Constraints under Projectivization","path":"preprints/Virasoro-Constraints-under-Projectivization-October-5-2026/virasoro-constraints-under-projectivization.pdf"},{"title":"Virasoro Constraints for Projective Complete Intersections","path":"preprints/Virasoro-Constraints-for-Projective-Complete-Intersections-September-24-2026/article.pdf"}]},{"id":"066","title":"Bounded klt complements for Fano contractions","desc":"Proves the finite-rational-coefficient form of Shokurov’s bounded-klt-complement conjecture for <i>ϵ<\/i>-lc complex Fano-type pairs with nef anti-log-canonical divisor. For <i>ϵ<\/i>-lc Fano contractions over any algebraically closed characteristic-zero field, it gives klt complements near every base point, with index bounded only by dimension and positive rational <i>ϵ<\/i>.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Birational geometry. No route identified.","papers":[{"title":"Bounded klt complements for Fano contractions","path":"preprints/Bounded-klt-complements-for-Fano-contractions-September-25-2026/Bounded-klt-complements-for-Fano-contractions-September-25-2026.pdf"},{"title":"Uniform Cartier sections for Fano type contractions","path":"preprints/Uniform-Cartier-sections-for-Fano-type-contractions-September-25-2026/Uniform-Cartier-sections-for-Fano-type-contractions-September-25-2026.pdf"}]},{"id":"067","title":"The Campana–Peternell conjecture in dimension six","desc":"Proves the Campana–Peternell conjecture in complex dimension six: every smooth connected complex projective Fano sixfold with nef tangent bundle is rational homogeneous.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":3,"year":1991,"note":"Fano manifolds. No route identified.","papers":[{"title":"The Campana–Peternell conjecture in dimension six","path":"preprints/The-Campana-Peternell-conjecture-in-dimension-six-September-25-2026/main.pdf"}]},{"id":"068","title":"Anticanonical nonvanishing in every dimension","desc":"If <i>X<\/i> is a smooth connected complex projective variety and $-K_X$ admits a smooth Hermitian metric with nonnegative curvature, then $H^0(X,-mK_X)\\ne0$ for some <i>m<\/i> &gt; 0. Thus smooth semipositivity forces a nonzero section of a positive tensor power of the anticanonical bundle in every dimension.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Positivity in complex geometry. No route identified.","papers":[{"title":"Anticanonical nonvanishing from smooth semipositivity","path":"preprints/Anticanonical-nonvanishing-from-smooth-semipositivity-September-26-2026/main.pdf"},{"title":"Invariant anticanonical indices and conversion of twisted differentials","path":"preprints/Invariant-anticanonical-indices-and-conversion-of-twisted-differentials-September-26-2026/main.pdf"},{"title":"Bounded anticanonical metrics on klt pairs and torus quotients","path":"preprints/Bounded-anticanonical-metrics-on-klt-pairs-and-torus-quotients-September-26-2026/main.pdf"},{"title":"Cohomological transfer and equivariant anticanonical sections","path":"preprints/Cohomological-transfer-and-equivariant-anticanonical-sections-September-26-2026/main.pdf"},{"title":"Metric descent and rank-preserving contractions","path":"preprints/Metric-descent-and-rank-preserving-contractions-September-26-2026/main.pdf"},{"title":"Integrable metrics and effectivity with controlled boundary","path":"preprints/Integrable-metrics-and-effectivity-with-controlled-boundary-September-26-2026/main.pdf"},{"title":"Exact orders and invariant anticanonical linear systems","path":"preprints/Exact-orders-and-invariant-anticanonical-linear-systems-September-26-2026/main.pdf"}]},{"id":"069","title":"Global quantum geometric Langlands at irrational level","desc":"Proves the unramified de Rham quantum geometric Langlands equivalence for every connected simple complex algebraic group on every smooth projective connected complex curve, at every shifted level $c\\in\\mathbb C\\setminus\\mathbb Q$. It identifies the full derived categories of twisted <i>D<\/i>-modules for the group and its Langlands dual, retaining all global forms and connected components.","subject":"Algebraic and complex geometry","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Geometric Langlands. No route identified.","papers":[{"title":"Global quantum geometric Langlands at irrational level","path":"preprints/Global-quantum-geometric-Langlands-at-irrational-level-October-4-2026/quantum-langlands.pdf"}]},{"id":"071","title":"Koebe’s circle-domain conjecture","desc":"Resolves the existence part of Koebe&#x27;s circle-domain conjecture: every domain in the Riemann sphere is conformally equivalent to a domain whose complementary components are round disks or points. It also proves that circle domains with conformally removable boundary are rigid, meaning every conformal equivalence to another circle domain is Möbius, establishing this direction of the He–Schramm conjecture.","subject":"Real and complex analysis","lean":1,"applied":2,"difficulty":5,"year":1908,"note":"Circle-domain uniformization is the continuous model behind circle-packing methods for conformal maps of multiply connected regions. The theorem is existence only.","papers":[{"title":"Removable Boundaries and Rigidity of Circle Domains","path":"preprints/Removable-Boundaries-and-Rigidity-of-Circle-Domains-September-23-2026/paper.pdf"},{"title":"Koebe&#x27;s Circle-Domain Conjecture","path":"preprints/Koebes-Circle-Domain-Conjecture-September-23-2026/paper.pdf"}]},{"id":"072","title":"Brennan&#x27;s conjecture and the integral-means spectrum","desc":"Proves Brennan&#x27;s conjecture: for every conformal bijection <i>ϕ<\/i> from a simply connected plane domain onto the disk, $|\\phi&#x27;|^s$ is area-integrable for $4/3\\lt s\\lt 4$. The sharp universal integral-means identity is $B_{\\mathcal S}(t)=|t|-1$ for <i>t<\/i> ≤ −2. A strict bound $B_b(-1)\\lt 1/4$ for bounded univalent functions disproves Kraetzer&#x27;s prediction at that parameter.","subject":"Real and complex analysis","lean":2,"applied":1,"difficulty":4,"year":1978,"note":"Integrability of conformal maps. A weak link to boundary behaviour in planar growth models.","papers":[{"title":"Brennan&#x27;s conjecture and sharp inverse-square integral means","path":"preprints/Brennans-conjecture-and-sharp-inverse-square-integral-means-September-24-2026/paper.pdf"},{"title":"A strict inverse-first-power bound for univalent functions","path":"preprints/A-strict-inverse-first-power-bound-for-univalent-functions-September-24-2026/paper.pdf"}]},{"id":"073","title":"The Falconer distance conjecture","desc":"Resolves the Falconer distance conjecture in every dimension <i>d<\/i> ≥ 2: every compact set $E\\subset\\mathbb R^d$ with Hausdorff dimension greater than $d/2$ determines a set of Euclidean distances of positive Lebesgue measure.","subject":"Real and complex analysis","lean":2,"applied":1,"difficulty":4,"year":1985,"note":"Geometric measure theory. No route identified.","papers":[{"title":"The Falconer distance conjecture in all dimensions","path":"preprints/The-Falconer-distance-conjecture-in-all-dimensions-September-23-2026/paper.pdf"}]},{"id":"074","title":"Kakeya in three and four dimensions","desc":"Resolves the Kakeya maximal conjecture in three dimensions and the Hausdorff-dimension conjecture in four. In three dimensions, the radius-<i>δ<\/i> tube maximal operator maps $L^3(\\mathbb R^3)$ to $L^3(S^2)$ with norm $O_\\varepsilon(\\delta^{-\\varepsilon})$ for every <i>ε<\/i> &gt; 0. In four dimensions, every set containing a unit segment in every direction has Hausdorff dimension four.","subject":"Real and complex analysis","lean":0,"applied":2,"difficulty":5,"year":1971,"note":"Kakeya estimates feed Fourier restriction and dispersive wave bounds. The route to computation runs through that further theory.","papers":[{"title":"The Kakeya maximal conjecture in three dimensions","path":"preprints/The-Kakeya-maximal-conjecture-in-three-dimensions-September-23-2026/paper.pdf"},{"title":"Every four-dimensional Kakeya set has full Hausdorff dimension","path":"preprints/Every-four-dimensional-Kakeya-set-has-full-Hausdorff-dimension-September-24-2026/paper.pdf"}]},{"id":"075","title":"The $L\\log L$ Fourier-convergence conjecture","desc":"Proves that the ordinary symmetric Fourier partial sums of every complex-valued function in $L\\log L(\\mathbb T)$ converge almost everywhere along the full sequence. This resolves the classical sufficiency conjecture at the $L\\log L$ scale.","subject":"Real and complex analysis","lean":0,"applied":2,"difficulty":5,"year":1966,"note":"Pointwise convergence of Fourier series at the sharp integrability scale. It does not change how series are computed.","papers":[{"title":"Almost-everywhere Fourier convergence in L log L","path":"preprints/Almost-everywhere-Fourier-convergence-in-L-log-L-September-23-2026/paper.pdf"}]},{"id":"076","title":"Real ultraflat Littlewood polynomials and unbounded binary merit factors","desc":"Constructs polynomials with <i>N<\/i> consecutive coefficients in $\\{-1,1\\}$ whose modulus is $(1+o(1))\\sqrt N$ uniformly on the entire unit circle, for every sufficiently large integer length <i>N<\/i>. Thus real Littlewood polynomials are ultraflat, including at the real endpoints. Their binary merit factors tend to infinity, disproving Turyn&#x27;s bounded-merit-factor conjecture.","subject":"Real and complex analysis","lean":2,"applied":4,"difficulty":5,"year":1966,"note":"Binary sequences with a flat spectrum and high merit factor are what radar pulse compression and low peak-power signalling search for. The construction is explicit.","papers":[{"title":"Ultraflat real Littlewood polynomials","path":"preprints/Ultraflat-real-Littlewood-polynomials-October-5-2026/ultraflat-real-littlewood-polynomials.pdf"},{"title":"Nearly minimal maxima and positive minima of Littlewood polynomials","path":"preprints/Nearly-minimal-maxima-and-positive-minima-of-Littlewood-polynomials-October-5-2026/littlewood-lower-envelope.pdf"},{"title":"Asymptotically minimal maxima of real Littlewood polynomials","path":"preprints/Asymptotically-minimal-maxima-of-real-Littlewood-polynomials-September-23-2026/paper.pdf"}]},{"id":"077","title":"Fourier restriction for positively curved surfaces","desc":"Proves the diagonal Fourier extension conjecture for positively curved surfaces in three dimensions. For every compact smooth positively curved surface $\\Sigma\\subset\\mathbb R^3$, including surfaces with boundary, the extension operator is bounded from $L^p(\\Sigma)$ to $L^p(\\mathbb R^3)$ for every <i>p<\/i> &gt; 3.","subject":"Real and complex analysis","lean":0,"applied":2,"difficulty":5,"year":1967,"note":"Restriction estimates control dispersive and wave equations. The route to computation runs through that further theory.","papers":[{"title":"Elliptic capacity propagation and Fourier restriction to the sphere","path":"preprints/Elliptic-capacity-propagation-and-Fourier-restriction-to-the-sphere-September-24-2026/Elliptic-capacity-propagation-and-Fourier-restriction-to-the-sphere-September-24-2026.pdf"},{"title":"Diagonal Fourier extension for positively curved surfaces in three dimensions","path":"preprints/Diagonal-Fourier-extension-for-positively-curved-surfaces-in-three-dimensions-September-24-2026/Diagonal-Fourier-extension-for-positively-curved-surfaces-in-three-dimensions-September-24-2026.pdf"}]},{"id":"078","title":"The three-dimensional Bochner–Riesz conjecture","desc":"Resolves the three-dimensional Bochner–Riesz conjecture in its strict range: the Bochner–Riesz multipliers of order <i>δ<\/i> are bounded on $L^p(\\mathbb R^3)$ for every $1\\le p\\le\\infty$ whenever $\\delta\\gt \\max\\{3|1/p-1/2|-1/2,0\\}$.","subject":"Real and complex analysis","lean":0,"applied":2,"difficulty":5,"year":null,"note":"Summability of multidimensional Fourier series. An indirect link to spectral methods.","papers":[{"title":"Bochner–Riesz multipliers in three dimensions","path":"preprints/Bochner-Riesz-Multipliers-in-Three-Dimensions-September-24-2026/Bochner-Riesz-Multipliers-in-Three-Dimensions-September-24-2026.pdf"}]},{"id":"079","title":"Local smoothing in three dimensions","desc":"Resolves Sogge&#x27;s local smoothing conjecture for the Euclidean wave equation in three spatial dimensions. The estimate holds throughout the full strict range $2\\lt p\\lt \\infty$, with Sobolev regularity above $\\max\\{0,1-3/p\\}$. In particular, the critical <i>L<\/i><sup>3<\/sup> estimate holds with every positive Sobolev loss.","subject":"Real and complex analysis","lean":0,"applied":2,"difficulty":4,"year":1991,"note":"Regularity of wave-equation solutions. An indirect link to wave propagation analysis.","papers":[{"title":"Critical local smoothing for the three-dimensional wave equation","path":"preprints/Critical-local-smoothing-for-the-three-dimensional-wave-equation-September-24-2026/paper.pdf"}]},{"id":"080","title":"The exact Sobolev endpoint for Schrödinger convergence","desc":"Proves almost-everywhere convergence $e^{it\\Delta}f\\to f$ as $t\\downarrow0$ for every $f\\in H^{n/(2(n+1))}(\\mathbb R^n)$ and every dimension <i>n<\/i> ≥ 2. This attains the sharp Sobolev equality case of Carleson&#x27;s Schrödinger convergence problem, including the planar endpoint <i>H<\/i><sup>1/3<\/sup>.","subject":"Real and complex analysis","lean":0,"applied":1,"difficulty":3,"year":1980,"note":"Endpoint case of pointwise convergence for the Schrödinger equation. No route identified.","papers":[{"title":"Endpoint convergence for the planar Schrodinger equation","path":"preprints/Endpoint-convergence-for-the-planar-Schrodinger-equation-September-24-2026/paper.pdf"},{"title":"Endpoint pointwise convergence for the Schrodinger equation in higher dimensions","path":"preprints/Endpoint-pointwise-convergence-for-the-Schrodinger-equation-in-higher-dimensions-September-24-2026/paper.pdf"}]},{"id":"081","title":"Riesz transforms and rectifiability in higher codimension","desc":"Resolves the remaining higher-codimension Riesz-transform rectifiability problem: for <i>d<\/i> ≥ 4 and $2\\le n\\le d-2$, an <i>n<\/i>-Ahlfors–David regular Radon measure on ℝ<sup><i>d<\/i><\/sup> is uniformly <i>n<\/i>-rectifiable whenever its <i>n<\/i>-dimensional Riesz transform is uniformly <i>L<\/i><sup>2<\/sup>-bounded over all positive hard truncations. The rectifiability bounds depend only on dimension, regularity and operator bounds.","subject":"Real and complex analysis","lean":2,"applied":1,"difficulty":4,"year":1991,"note":"Geometric measure theory. No route identified.","papers":[{"title":"Riesz transforms and uniform rectifiability in higher codimension","path":"preprints/Riesz-transforms-and-uniform-rectifiability-in-higher-codimension-September-24-2026/paper.pdf"}]},{"id":"082","title":"Annular variation and dyadic absolute bounds for the triangular Hilbert transform","desc":"Proves maximal and annular <i>r<\/i>-variation bounds, for every <i>r<\/i> &gt; 2, from complex $L^3(\\mathbb R^2)\\times L^3(\\mathbb R^2)$ to $L^{3/2}(\\mathbb R^2)$. The maximal estimate controls both hard truncation endpoints and gives almost-everywhere and norm convergence. Pairing with a third input settles the triangular Hilbert transform estimate at the symmetric $L^3\\times L^3\\times L^3$ point.","subject":"Real and complex analysis","lean":2,"applied":1,"difficulty":4,"year":null,"note":"Multilinear harmonic analysis. No route identified.","papers":[{"title":"Annular variation of the triangular Hilbert transform at the symmetric point","path":"preprints/Annular-variation-of-the-triangular-Hilbert-transform-at-the-symmetric-point-October-5-2026/annular-variation.pdf"},{"title":"An L³ bound for the dyadic triangular Hilbert form","path":"preprints/An-L3-bound-for-the-dyadic-triangular-Hilbert-form-October-5-2026/dyadic-triangular-hilbert.pdf"},{"title":"The maximal triangular Hilbert transform at the symmetric point","path":"preprints/The-maximal-triangular-Hilbert-transform-at-the-symmetric-point-September-24-2026/paper.pdf"}]},{"id":"083","title":"Hilbert transforms along Lipschitz directions","desc":"Proves a uniform strong <i>L<\/i><sup>2<\/sup> bound for the planar Hilbert transform along any Lipschitz unit vector field, at integration lengths bounded by an absolute multiple of its reciprocal Lipschitz constant. The estimate is uniform over inner truncations and yields an <i>L<\/i><sup>2<\/sup>-bounded principal-value operator, establishing Stein&#x27;s weak-type conjecture at this short scale.","subject":"Real and complex analysis","lean":1,"applied":1,"difficulty":4,"year":null,"note":"Singular integrals along vector fields. No route identified.","papers":[{"title":"A uniform Hilbert transform estimate for Lipschitz directions","path":"preprints/A-uniform-Hilbert-transform-estimate-for-Lipschitz-directions-September-25-2026/main.pdf"}]},{"id":"084","title":"The geometric case of the Erdős similarity conjecture","desc":"For every fixed $q\\in(0,1)$, constructs compact subsets of $[0,1]$ with measure arbitrarily close to one containing no translated and nontrivially dilated copy of $\\{q^n:n\\ge1\\}$, with dilations of either sign. This resolves the geometric-progression case of the Erdős similarity conjecture for every ratio.","subject":"Real and complex analysis","lean":1,"applied":1,"difficulty":4,"year":1974,"note":"Measure theory. No route identified.","papers":[{"title":"The geometric case of the Erdős similarity conjecture","path":"preprints/The-geometric-case-of-the-Erdos-similarity-conjecture-October-5-2026/geometric-erdos-similarity.pdf"},{"title":"The dyadic case of the Erdős similarity conjecture","path":"preprints/The-dyadic-case-of-the-Erdos-similarity-conjecture-September-25-2026/paper.pdf"}]},{"id":"085","title":"Endpoint Sobolev regularity of centered disk averages","desc":"Resolves the planar centered-disk case of the Hajłasz–Onninen maximal-function regularity problem. For every real $f\\in W^{1,1}(\\mathbb R^2)$, the centered disk maximal function satisfies $\\|\\nabla Mf\\|_1\\le C\\|\\nabla f\\|_1$ with an absolute constant. It belongs locally to $W^{1,1}$ and has a globally integrable weak gradient.","subject":"Real and complex analysis","lean":2,"applied":1,"difficulty":3,"year":2004,"note":"Regularity of maximal functions. No route identified.","papers":[{"title":"An Endpoint Gradient Bound for the Centered Disk Maximal Operator","path":"preprints/An-Endpoint-Gradient-Bound-for-the-Centered-Disk-Maximal-Operator-September-26-2026/article.pdf"}]},{"id":"086","title":"An <i>L<\/i><sup>3<\/sup> bound for the trilinear Hilbert transform","desc":"Proves that the principal-value trilinear Hilbert transform with shifts $x-t$, $x-2t$, $x-3t$ is bounded from $L^3(\\mathbb R)^3$ to $L^1(\\mathbb R)$. This resolves the <i>L<\/i><sup>3<\/sup> exponent case of the standard conjecture for slopes 1, 2, 3.","subject":"Real and complex analysis","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Multilinear harmonic analysis. No route identified.","papers":[{"title":"An <i>L<\/i><sup>3<\/sup> bound for the trilinear Hilbert transform","path":"preprints/An-L3-bound-for-the-trilinear-Hilbert-transform-October-5-2026/paper.pdf"}]},{"id":"087","title":"The Mahler conjectures, functional inequalities and polar-product symplectic width","desc":"Resolves the symmetric and nonsymmetric geometric Mahler conjectures in every dimension, with Hanner polytopes and simplices as the respective volume-product minimizers and all equality cases classified. The corresponding sharp functional Mahler inequalities also hold. For <i>n<\/i> ≥ 2, every symmetric polar product $K\\times K^\\circ$ in dimension $2n$ has Gromov width 4.","subject":"Convex and metric geometry","lean":2,"applied":2,"difficulty":5,"year":1939,"note":"Volume-product bounds supply constants in the geometry of numbers and in lattice algorithms. The asymptotic form already known suffices for most uses.","papers":[{"title":"The symmetric Mahler conjecture and its equality cases","path":"preprints/The-symmetric-Mahler-conjecture-and-its-equality-cases-September-22-2026/paper.pdf"},{"title":"The Mahler Conjecture for General Convex Bodies","path":"preprints/The-Mahler-Conjecture-for-General-Convex-Bodies-September-22-2026/paper.pdf"},{"title":"Symplectic Balls in Symmetric Polar Products","path":"preprints/Symplectic-Balls-in-Symmetric-Polar-Products-September-22-2026/paper.pdf"}]},{"id":"088","title":"Sharp projection-body inequalities and a counterexample to simplex maximization","desc":"Proves Petty&#x27;s projection-volume conjecture in the remaining dimensions <i>n<\/i> ≥ 4: ellipsoids uniquely minimize projection-body volume at fixed body volume. Also establishes the full Lutwak–Petty projection inequalities. In contrast, products of simplices exceed Brannen&#x27;s proposed simplex maximum for normalized projection-body volume by an exponential factor in every sufficiently large dimension.","subject":"Convex and metric geometry","lean":2,"applied":1,"difficulty":4,"year":1971,"note":"Affine isoperimetric inequalities. No route identified.","papers":[{"title":"Petty’s projection-volume conjecture in dimensions at least four","path":"preprints/Pettys-projection-volume-conjecture-in-dimensions-at-least-four-September-24-2026/paper.pdf"},{"title":"A product counterexample to the simplex maximum for projection-body volume","path":"preprints/A-product-counterexample-to-the-simplex-maximum-for-projection-body-volume-September-24-2026/paper.pdf"}]},{"id":"089","title":"Bounded-distortion <i>L<\/i><sub>1<\/sub> embeddings of planar and bounded-treewidth graphs","desc":"Resolves the planar and bounded-treewidth cases of the Gupta–Newman–Rabinovich–Sinclair conjecture. Shortest-path metrics of finite connected graphs with arbitrary positive edge lengths embed into real <i>L<\/i><sub>1<\/sub> with universal distortion for planar graphs, and distortion depending only on treewidth for bounded-treewidth graphs. The corresponding multicommodity flow–cut gaps are uniformly bounded.","subject":"Convex and metric geometry","lean":2,"applied":4,"difficulty":4,"year":1999,"note":"Constant-distortion embedding of planar metrics into L1 gives a constant flow-cut gap for multicommodity flow and constant-factor sparsest cut on planar networks.","papers":[{"title":"Planar Graph Metrics Embed into L1 with Constant Distortion","path":"preprints/Planar-Graph-Metrics-Embed-into-L1-with-Constant-Distortion-September-23-2026/paper.pdf"},{"title":"L1 Embeddings of Graphs of Bounded Treewidth","path":"preprints/L1-Embeddings-of-Graphs-of-Bounded-Treewidth-September-23-2026/paper.pdf"}]},{"id":"090","title":"Triangular-lattice optimality, long-range Riesz and Coulomb energies, and spherical logarithmic energy","desc":"Proves that the triangular lattice minimizes the lower limit of energy per particle for every nonnegative completely monotone potential of squared distance among locally finite planar configurations of centered-disk density one. It also minimizes unit-background renormalized Riesz energies for $0\\lt s\\lt 2$ and Coulomb energy, resolving Sandier–Serfaty and the two-dimensional Brauchart–Hardin–Saff conjecture on the linear term of optimal spherical logarithmic energy.","subject":"Convex and metric geometry","lean":1,"applied":3,"difficulty":4,"year":2007,"note":"Ground states of planar particle systems. Supports the hexagonal choice in two-dimensional quantization, sampling and point-set design.","papers":[{"title":"An atomic certificate for triangular-lattice universal optimality","path":"preprints/An-atomic-certificate-for-triangular-lattice-universal-optimality-September-26-2026/paper.pdf"},{"title":"Universal optimality of the triangular lattice","path":"preprints/Universal-optimality-of-the-triangular-lattice-September-23-2026/paper.pdf"},{"title":"A sharp Fourier certificate for planar circle packing","path":"preprints/A-sharp-Fourier-certificate-for-planar-circle-packing-September-23-2026/paper.pdf"},{"title":"Triangular minimality for planar Coulomb renormalized energy","path":"preprints/Triangular-minimality-for-planar-Coulomb-renormalized-energy-September-23-2026/paper.pdf"}]},{"id":"091","title":"Logarithmic and <i>L<\/i><sub><i>p<\/i><\/sub> Brunn–Minkowski inequalities and the B-conjecture","desc":"Proves the logarithmic Brunn–Minkowski inequality for origin-symmetric convex bodies in every dimension, and the scalar-dilation B-conjecture for all even log-concave Radon measures. For Lebesgue volume it also proves the additive <i>L<\/i><sub><i>p<\/i><\/sub> Brunn–Minkowski inequality for full-dimensional origin-symmetric convex bodies throughout $0\\lt p\\lt 1$.","subject":"Convex and metric geometry","lean":2,"applied":2,"difficulty":3,"year":2012,"note":"Inequalities for log-concave measures. An indirect link to concentration bounds used in high-dimensional statistics.","papers":[{"title":"The logarithmic Brunn–Minkowski conjecture","path":"preprints/The-logarithmic-Brunn-Minkowski-conjecture-September-23-2026/paper.pdf"}]},{"id":"092","title":"The optimal order of convex-body covering density","desc":"Determines the optimal worst-case covering density as $\\Theta(n\\log n)$, for both lattice and unrestricted translative coverings. Every convex body in ℝ<sup><i>n<\/i><\/sup>, <i>n<\/i> ≥ 2, admits a lattice covering of density at most $Cn\\log n$; centrally symmetric examples in every sufficiently large dimension require at least $cn\\log n$ even without the lattice restriction, for absolute $c,C\\gt 0$.","subject":"Convex and metric geometry","lean":2,"applied":2,"difficulty":4,"year":1957,"note":"Covering density bounds bear on lattice quantizers and covering codes. The result is existential.","papers":[{"title":"A single-lattice covering bound of order n log n","path":"preprints/A-single-lattice-covering-bound-of-order-n-log-n-September-23-2026/paper.pdf"},{"title":"Translative covering densities of order n log n","path":"preprints/Translative-covering-densities-of-order-n-log-n-September-23-2026/paper.pdf"}]},{"id":"093","title":"Dimension-free logarithmic Sobolev inequality for subgaussian log-concave measures","desc":"Proves a dimension-free logarithmic Sobolev inequality for centered log-concave densities with uniformly subgaussian linear marginals, with constant bounded by a universal multiple of the squared linear subgaussian parameter.","subject":"Convex and metric geometry","lean":0,"applied":3,"difficulty":3,"year":null,"note":"The log-Sobolev constant sets mixing-time bounds for Langevin samplers. A dimension-free constant enters those bounds directly.","papers":[{"title":"A dimension-free logarithmic Sobolev inequality for subgaussian log-concave measures","path":"preprints/A-dimension-free-logarithmic-Sobolev-inequality-for-subgaussian-log-concave-measures-September-23-2026/paper.pdf"}]},{"id":"094","title":"Subpolynomial dimension reduction in <i>L<\/i><sub><i>p<\/i><\/sub>","desc":"For every fixed $1\\lt p\\lt \\infty$ and distortion <i>D<\/i> &gt; 1, every <i>n<\/i>-point subset of real <i>L<\/i><sub><i>p<\/i><\/sub> embeds into $\\ell_p^d$ with distortion at most <i>D<\/i> and dimension $d=n^{o(1)}$, answering Naor&#x27;s sublinear-dimension question for <i>p<\/i> ≠ 2. In contrast, exact embeddings require worst-case dimension $\\Theta(n^2)$ when <i>p<\/i> ≠ 2.","subject":"Convex and metric geometry","lean":2,"applied":3,"difficulty":3,"year":null,"note":"A Johnson-Lindenstrauss type reduction outside Euclidean space would serve sketching and nearest-neighbour search in other norms. The target dimension is subpolynomial, not logarithmic.","papers":[{"title":"Subpolynomial dimension reduction in Lp","path":"preprints/Subpolynomial-dimension-reduction-in-Lp-September-23-2026/paper.pdf"}]},{"id":"095","title":"Hyperbolicity cones without semidefinite lifts","desc":"Disproves the Projected Lax conjecture: some hyperbolicity cones are not spectrahedral shadows. The examples admit no exact finite affine semidefinite lift, regardless of the number of auxiliary variables or the real coefficients used. This also disproves the generalized Lax conjecture that every hyperbolicity cone is spectrahedral.","subject":"Convex and metric geometry","lean":2,"applied":4,"difficulty":4,"year":null,"note":"Hyperbolic programming is strictly more expressive than semidefinite programming. Solvers for hyperbolicity cones cannot be replaced by semidefinite reformulations.","papers":[{"title":"Hyperbolicity Cones Without Semidefinite Lifts","path":"preprints/Hyperbolicity-Cones-Without-Semidefinite-Lifts-October-5-2026/nonliftable-hyperbolicity.pdf"},{"title":"A nonspectrahedral hyperbolicity cone","path":"preprints/A-Nonspectrahedral-Hyperbolicity-Cone-September-24-2026/nonspectrahedral-hyperbolicity-cone.pdf"},{"title":"An Exact Semidefinite Lift of a Nonspectrahedral Hyperbolicity Cone","path":"preprints/An-Exact-Semidefinite-Lift-of-a-Nonspectrahedral-Hyperbolicity-Cone-October-5-2026/Exact-Semidefinite-Lift-of-a-Nonspectrahedral-Hyperbolicity-Cone.pdf"}]},{"id":"096","title":"The Gaussian propeller conjecture in every dimension","desc":"Proves that the sum of squared Gaussian first moments of any finite measurable partition is at most $9/(8\\pi)$. In dimension at least two, three planar sectors of angle $2\\pi/3$, extended orthogonally, attain the bound. Combined with the separate Unique Games theorem, this proves NP-hardness of improving the loss factor $(8\\pi/9)(1-1/k)$ for identity-target kernel clustering with fixed <i>k<\/i> ≥ 3 on rational centered positive semidefinite inputs.","subject":"Convex and metric geometry","lean":2,"applied":3,"difficulty":3,"year":2008,"note":"With the Unique Games theorem it gives the exact hardness threshold for kernel clustering problems.","papers":[{"title":"The Gaussian propeller bound in every dimension","path":"preprints/The-Gaussian-Propeller-Bound-in-Every-Dimension-September-24-2026/main.pdf"}]},{"id":"097","title":"The Euclidean Steinitz–Bergström bound","desc":"Proves that any finite sequence in the Euclidean unit ball of ℝ<sup><i>d<\/i><\/sup> admits signs keeping every partial sum within $C\\sqrt d$, independently of length. Consequently every zero-sum family can be reordered with the same bound on unsigned partial sums. A matching lower bound gives the optimal order $S_2(d)=\\Theta(\\sqrt d)$.","subject":"Convex and metric geometry","lean":2,"applied":3,"difficulty":4,"year":null,"note":"Prefix discrepancy bounds drive vector balancing, scheduling and online rounding arguments. The statement is existential.","papers":[{"title":"The Euclidean Steinitz–Bergström theorem","path":"preprints/The-Euclidean-Steinitz-Bergstrom-theorem-September-24-2026/The-Euclidean-Steinitz-Bergstrom-theorem-September-24-2026.pdf"}]},{"id":"098","title":"Compact counterexamples to bi-Lipschitz dimension reduction","desc":"Every infinite-dimensional real Banach space contains a compact doubling set that admits no bi-Lipschitz embedding into any finite-dimensional normed space. The doubling constant is universal. This answers the Lang–Plaut problem negatively, even for compact subsets of Hilbert space.","subject":"Convex and metric geometry","lean":2,"applied":2,"difficulty":3,"year":2001,"note":"A limit on dimension reduction for doubling data sets.","papers":[{"title":"A doubling Hilbert subset with no finite-dimensional bi-Lipschitz embedding","path":"preprints/A-doubling-Hilbert-subset-with-no-finite-dimensional-bi-Lipschitz-embedding-September-25-2026/main.pdf"}]},{"id":"099","title":"The sharp exponential scale of edit-distance distortion","desc":"Determines the least distortion of embedding edit distance on words of length at most <i>d<\/i> into real <i>ℓ<\/i><sub>1<\/sub>: it is $\\exp(\\Theta(\\sqrt{\\log d\\,\\log\\log d}))$. Insertions, deletions and substitutions have unit cost. The constants are uniform over all finite alphabets with at least two symbols, even when the alphabet grows with <i>d<\/i>; binary words already force the lower bound.","subject":"Convex and metric geometry","lean":1,"applied":3,"difficulty":3,"year":null,"note":"Fixes the limit of embedding-based sketching for edit distance.","papers":[{"title":"Edit Distance in l1: Matching Bounds up to Constants in the Exponent","path":"preprints/Edit-Distance-in-l1-Matching-Bounds-up-to-Constants-in-the-Exponent-September-27-2026/paper.pdf"},{"title":"Finite-Circle Obstructions, Binary Codes, and Histogram Embeddings for Edit Distance","path":"preprints/Finite-Circle-Obstructions-Binary-Codes-and-Histogram-Embeddings-for-Edit-Distance-September-27-2026/paper.pdf"},{"title":"Tree Constructions for the l1 Distortion of Binary Edit Distance","path":"preprints/Tree-Constructions-for-the-l1-Distortion-of-Binary-Edit-Distance-September-27-2026/paper.pdf"}]},{"id":"100","title":"Cylinder coverings below the half-area bound","desc":"Covers the entire closed regular tetrahedron by finitely many cylinders with compact triangular perpendicular bases whose total area is less than half its smallest orthogonal projection area. This disproves Bang&#x27;s half-area cylinder-covering bound and the stronger directionwise normalized conjecture in dimension three.","subject":"Convex and metric geometry","lean":1,"applied":1,"difficulty":3,"year":1951,"note":"Covering problems in convex geometry. No route identified.","papers":[{"title":"Finite angular cylinder covers below the half-area bound","path":"preprints/Finite-angular-cylinder-covers-below-the-half-area-bound-September-27-2026/main.pdf"},{"title":"Finite cylinder approximation of ruled sets","path":"preprints/Finite-cylinder-approximation-of-ruled-sets-September-27-2026/main.pdf"},{"title":"Slope-field perturbations of the two-cylinder covering","path":"preprints/Slope-field-perturbations-of-the-two-cylinder-covering-September-27-2026/main.pdf"},{"title":"Finite triangular approximation of radial sweeps","path":"preprints/Finite-triangular-approximation-of-radial-sweeps-September-27-2026/main.pdf"}]},{"id":"101","title":"The sharp simplex conjecture for isotropic constants","desc":"Proves that simplices uniquely maximize the isotropic constant among convex bodies in every dimension, resolving the strong isotropic constant conjecture. Also establishes the sharp entropy lower bound for log-concave probability densities, with equality precisely for invertible affine images of products of one-sided exponential laws.","subject":"Convex and metric geometry","lean":0,"applied":2,"difficulty":4,"year":null,"note":"The isotropic constant enters complexity bounds for volume computation and sampling from convex bodies. The sharp value changes constants only.","papers":[{"title":"A sharp entropy bound and the simplex inequality for isotropic constants","path":"preprints/A-sharp-entropy-bound-and-the-simplex-inequality-for-isotropic-constants-October-5-2026/isotropic-simplex.pdf"}]},{"id":"102","title":"The Unique Games Conjecture and optimal approximation thresholds","desc":"Proves Khot&#x27;s Unique Games Conjecture. Independent direct reductions also establish NP-hardness, on unweighted graphs, of approximation beyond the Goemans–Williamson ratio for Max-Cut, below factor two for Vertex Cover, and within any fixed constant factor for Min-UnCut and directed feedback vertex set. These direct proofs use established PCP and Label Cover hardness results.","subject":"Theoretical computer science","lean":2,"applied":5,"difficulty":5,"year":2002,"note":"Fixes the approximation threshold of Max-Cut, Vertex Cover and every constraint satisfaction problem at the ratio of the basic semidefinite relaxation. Algorithm designers learn where to stop.","papers":[{"title":"The Unique Games Theorem","path":"preprints/The-Unique-Games-Theorem-September-23-2026/paper.pdf"},{"title":"A Direct Proof of Optimal Max-Cut Hardness","path":"preprints/A-Direct-Proof-of-Optimal-Max-Cut-Hardness-September-23-2026/paper.pdf"},{"title":"The Factor-Two Hardness Threshold for Vertex Cover","path":"preprints/The-Factor-Two-Hardness-Threshold-for-Vertex-Cover-September-23-2026/paper.pdf"},{"title":"Constant-factor hardness of Min-UnCut","path":"preprints/Constant-factor-hardness-of-Min-UnCut-September-23-2026/paper.pdf"},{"title":"Constant-factor hardness of directed feedback vertex set","path":"preprints/Constant-factor-hardness-of-directed-feedback-vertex-set-September-23-2026/paper.pdf"}]},{"id":"103","title":"Exact derandomization of logarithmic space: $\\mathsf L=\\mathsf{RL}=\\mathsf{BPL}$","desc":"Proves $\\mathsf L=\\mathsf{RL}=\\mathsf{BPL}$, resolving derandomization for bounded-error logarithmic-space computation. An effective compiler converts each randomized polynomial-time logarithmic-space machine deciding a language with one-sided or two-sided error into a deterministic logarithmic-space decider with explicit polynomial running-time bounds.","subject":"Theoretical computer science","lean":0,"applied":4,"difficulty":5,"year":1979,"note":"Every randomized logarithmic-space algorithm has a deterministic equivalent in the same space, with an explicit compiler.","papers":[{"title":"Exact derandomization of logarithmic space: L = RL = BPL","path":"preprints/Exact-Derandomization-of-Logarithmic-Space-L-equals-RL-equals-BPL-September-23-2026/paper.pdf"}]},{"id":"104","title":"Quasipolynomial algorithms for mean-payoff, stochastic and parity games","desc":"Gives deterministic algorithms using $2^{O((\\log(L+2))^2)}$ bit operations, for complete binary input length <i>L<\/i>, for ordinary mean-payoff games and two separate extensions. They compute exact values and optimal positional strategies in ordinary games, the nonnegative expectation-of-liminf value set in turn-based stochastic games, and the winning set for nonnegative liminf mean payoff conjoined with parity. Signed rewards, rational chance probabilities, and parity priorities are unrestricted and binary-encoded.","subject":"Theoretical computer science","lean":2,"applied":4,"difficulty":4,"year":1992,"note":"Mean-payoff, parity and stochastic games are the core of reactive synthesis and model checking. A deterministic quasipolynomial bound covers all three.","papers":[{"title":"Turn-Based Stochastic Mean-Payoff Games in Deterministic Quasipolynomial Time","path":"preprints/Turn-Based-Stochastic-Mean-Payoff-Games-in-Deterministic-Quasipolynomial-Time-October-5-2026/stochastic-mean-payoff-games.pdf"},{"title":"Mean-payoff parity games in quasipolynomial time","path":"preprints/Mean-payoff-parity-games-in-quasipolynomial-time-October-5-2026/mean-payoff-parity.pdf"},{"title":"Deterministic quasipolynomial-time mean-payoff games","path":"preprints/Deterministic-quasipolynomial-time-mean-payoff-games-September-25-2026/paper.pdf"},{"title":"Randomized quasipolynomial-time mean-payoff games","path":"preprints/Randomized-quasipolynomial-time-mean-payoff-games-September-25-2026/paper.pdf"}]},{"id":"105","title":"Perfect completeness for 2-to-1 games","desc":"Proves Khot&#x27;s 2-to-1 Games Conjecture with perfect completeness: for every fixed rational $\\delta\\in(0,1)$, it is NP-hard to distinguish satisfiable games from games whose optimum is at most <i>δ<\/i>, on explicit unweighted instances. The alphabet depends only on <i>δ<\/i>, and every right-hand label has exactly two preimages under each constraint map.","subject":"Theoretical computer science","lean":2,"applied":3,"difficulty":4,"year":2002,"note":"Hardness of approximation with perfect completeness. Strengthens inapproximability results for colouring and related problems.","papers":[{"title":"Perfect completeness for 2-to-1 games","path":"preprints/Perfect-completeness-for-2-to-1-games-September-23-2026/paper.pdf"}]},{"id":"106","title":"Hardness of coloring three-colorable graphs","desc":"It is NP-hard to color a three-colorable graph using any fixed number <i>c<\/i> ≥ 3 of colors. More strongly, for every fixed $0\\lt \\delta\\lt 1/3$, a deterministic polynomial-time reduction from 3SAT produces simple unweighted graphs that are three-colorable in the satisfiable case and have no independent set of size $\\delta n$ otherwise, where <i>n<\/i> is the number of vertices.","subject":"Theoretical computer science","lean":2,"applied":3,"difficulty":5,"year":1976,"note":"No polynomial algorithm colours a three-colourable graph with any fixed number of colours unless P = NP. Closes the search for one.","papers":[{"title":"Hardness of finding large independent sets in three-colorable graphs","path":"preprints/Hardness-of-finding-large-independent-sets-in-three-colorable-graphs-September-24-2026/Hardness-of-finding-large-independent-sets-in-three-colorable-graphs-September-24-2026.pdf"}]},{"id":"107","title":"Matrix multiplication with exponent at most 9/4","desc":"Proves $\\omega\\le9/4$ over ℂ, giving $O_\\varepsilon(n^{9/4+\\varepsilon})$ arithmetic operations for square matrix multiplication. In characteristic zero, some inner dimension <i>n<\/i><sup><i>a<\/i><\/sup> with <i>a<\/i> &gt; 0.465 permits $n^{2+o(1)}$ rectangular multiplication. Further square bounds give <i>ω<\/i> &lt; 2.258 outside finitely many positive characteristics and <i>ω<\/i> &lt; 2.371054886006746 over every fixed field.","subject":"Theoretical computer science","lean":2,"applied":4,"difficulty":5,"year":1969,"note":"Lowers the exponent from about 2.37. The consequence reaches every algorithm reduced to matrix multiplication, although such methods carry large constants.","papers":[{"title":"An Upper Bound of 9/4 for the Matrix Multiplication Exponent","path":"preprints/Matrix-Multiplication-Nine-Fourths-October-2-2026/paper.pdf"},{"title":"Complex Matrix Multiplication Below 2.258 and Rectangular Bounds","path":"preprints/Complex-Matrix-Multiplication-Below-2.258-and-Rectangular-Bounds-September-24-2026/Complex-Matrix-Multiplication-Below-2.258-and-Rectangular-Bounds-September-24-2026.pdf"},{"title":"Staggered extraction for exact matrix multiplication over every field","path":"preprints/Staggered-extraction-for-exact-matrix-multiplication-over-every-field-September-24-2026/Staggered-extraction-for-exact-matrix-multiplication-over-every-field-September-24-2026.pdf"}]},{"id":"108","title":"A cubic permanent–determinant lower bound","desc":"Proves an $\\Omega(n^3)$ lower bound for the border determinantal complexity of the $n\\times n$ permanent over ℂ. Even coefficientwise limits of determinants of affine-linear matrices require matrix size at least $cn^3$, for an absolute <i>c<\/i> &gt; 0 and all sufficiently large <i>n<\/i>; the same bound therefore holds for exact representations.","subject":"Theoretical computer science","lean":1,"applied":2,"difficulty":4,"year":1979,"note":"Algebraic complexity lower bound. Evidence on the cost of computing the permanent.","papers":[{"title":"A cubic lower bound for border determinantal complexity of the permanent","path":"preprints/A-cubic-lower-bound-for-border-determinantal-complexity-of-the-permanent-September-24-2026/A-cubic-lower-bound-for-border-determinantal-complexity-of-the-permanent-September-24-2026.pdf"}]},{"id":"109","title":"Integer multiplication below $n\\log n$","desc":"Multiplies two <i>n<\/i>-bit integers exactly at every input length in deterministic worst-case time $O(n(\\log n)^{1-\\kappa})$, with $\\kappa=2^{-182}$, on one fixed finite-alphabet Turing machine with finitely many one-dimensional tapes. This disproves the Schönhage–Strassen $n\\log n$ optimality conjecture in the ordinary multitape bit model.","subject":"Theoretical computer science","lean":0,"applied":2,"difficulty":5,"year":1971,"note":"Shows n log n is not a barrier. The saving is a factor of (log n) to the power 2^-182, which has no computational use.","papers":[{"title":"Integer multiplication below n log n","path":"preprints/Integer-multiplication-below-n-log-n-September-23-2026/paper.pdf"}]},{"id":"110","title":"Optimal-order randomized <i>k<\/i>-server on arbitrary metrics","desc":"Establishes a randomized competitive ratio $O(\\log^2(k+1))$ for <i>k<\/i>-server on every metric space, matching the worst-case lower-bound order. One policy serves every finite oblivious request sequence, including on infinite unbounded metrics. On finite rational metrics, a uniform implementation has polynomial preprocessing and per-request bit cost in the input length and $\\log(t+1)$ at request <i>t<\/i>, with a finite instance-dependent additive movement constant.","subject":"Theoretical computer science","lean":1,"applied":3,"difficulty":4,"year":1990,"note":"Online resource allocation and caching. Settles the randomized competitive ratio at order log squared k.","papers":[{"title":"Squared-logarithmic randomized k-server on arbitrary metrics","path":"preprints/Squared-logarithmic-randomized-k-server-on-arbitrary-metrics-September-24-2026/Squared-logarithmic-randomized-k-server-on-arbitrary-metrics-September-24-2026.pdf"},{"title":"Uniform computation of the squared-logarithmic k-server bound","path":"preprints/Uniform-computation-of-the-squared-logarithmic-k-server-bound-September-24-2026/Uniform-computation-of-the-squared-logarithmic-k-server-bound-September-24-2026.pdf"}]},{"id":"111","title":"One-sample matroid prophet inequalities against an almighty adversary","desc":"For every finite matroid known in advance, gives a distribution-independent online rule using one independent sample per element and earning a universal constant fraction of the expected offline optimum. Values are independent and nonnegative, with finite expected optimum. The guarantee holds even when the arrival-order adversary sees all samples, values, and the rule&#x27;s entire random seed; no polynomial-time implementation is asserted.","subject":"Theoretical computer science","lean":1,"applied":2,"difficulty":3,"year":null,"note":"Online selection without knowledge of the distributions. The constant is 2^-310 and no polynomial-time rule is given.","papers":[{"title":"One Sample Suffices for Matroid Prophet Inequalities against an Almighty Adversary","path":"preprints/One-Sample-Suffices-for-Matroid-Prophet-Inequalities-against-an-Almighty-Adversary-September-23-2026/final.pdf"}]},{"id":"112","title":"Beyond the square-root exponent for depth-three circuits","desc":"Constructs a single language in deterministic polynomial time whose <i>n<\/i>-bit membership function requires $2^{\\omega(\\sqrt n)}$ total gates in unbounded-fan-in OR–AND–OR circuits, at every sufficiently large input length. This crosses the square-root-exponent threshold for explicit depth-three Boolean circuit lower bounds.","subject":"Theoretical computer science","lean":2,"applied":1,"difficulty":4,"year":1986,"note":"Circuit lower bounds. No route to algorithms identified.","papers":[{"title":"Beyond the Square-Root Exponent for Depth-Three Boolean Circuits","path":"preprints/Beyond-the-Square-Root-Exponent-for-Depth-Three-Boolean-Circuits-September-23-2026/main.pdf"}]},{"id":"113","title":"Approximate counting and entropy of perfect matchings","desc":"Gives a fully polynomial randomized approximation scheme for counting perfect matchings in arbitrary finite simple graphs, with exact detection of zero counts. Also proves the perfect-matching entropy conjecture of Anari, Oveis Gharan, and Vinzant, bounding the maximum entropy of a matching law at every feasible edge-marginal vector in a loopless labelled multigraph, including boundary points.","subject":"Theoretical computer science","lean":2,"applied":4,"difficulty":5,"year":1986,"note":"Counting perfect matchings in general graphs is the monomer-dimer partition function. An approximation scheme has been sought since the bipartite case.","papers":[{"title":"A Fully Polynomial Randomized Approximation Scheme for Perfect Matchings in General Graphs","path":"preprints/A-Fully-Polynomial-Randomized-Approximation-Scheme-for-Perfect-Matchings-in-General-Graphs-September-23-2026/main.pdf"},{"title":"Entropy and Face Dimension of the Perfect-Matching Polytope","path":"preprints/Entropy-and-Face-Dimension-of-the-Perfect-Matching-Polytope-September-23-2026/main.pdf"}]},{"id":"114","title":"Approximate counting of common integer polymatroid bases","desc":"Gives a fully polynomial randomized approximation scheme for counting common integer bases of two integral polymatroids of equal total rank, supplied by exact rank-value oracles. Capacities are binary-encoded, each integer vector counts once, and oracle calls and bit operations outside the oracles are polynomial on every execution. For matroids presented by independence oracles, the results also cover common independent sets of prescribed, unrestricted, or maximum cardinality, even when the ranks differ.","subject":"Theoretical computer science","lean":2,"applied":3,"difficulty":3,"year":null,"note":"Approximate counting for a wide class of combinatorial structures, including common bases of two matroids.","papers":[{"title":"An FPRAS for Common Integer Polymatroid Bases with Binary Capacities","path":"preprints/An-FPRAS-for-Common-Integer-Polymatroid-Bases-with-Binary-Capacities-October-5-2026/polymatroid-fpras.pdf"},{"title":"Approximate counting of common bases of two matroids","path":"preprints/Approximate-counting-of-common-bases-of-two-matroids-September-23-2026/main.pdf"}]},{"id":"115","title":"Sampling and counting contingency tables with arbitrary margins","desc":"For nonnegative integer matrices with prescribed row and column sums, gives exact uniform sampling in expected polynomial bit time and almost-uniform sampling in worst-case polynomial bit time. The dimensions and binary-encoded margins are unrestricted. Also gives a fully polynomial randomized approximation scheme for counting such tables with arbitrary individual cell bounds, including structural zeros, with polynomial cost on every execution.","subject":"Theoretical computer science","lean":1,"applied":5,"difficulty":4,"year":1985,"note":"Exact conditional tests on contingency tables need uniform samples with fixed margins. Statisticians have used heuristics; this is a polynomial sampler for all margins.","papers":[{"title":"Exact Uniform Sampling of Contingency Tables with Arbitrary Margins","path":"preprints/Exact-Uniform-Sampling-of-Contingency-Tables-with-Arbitrary-Margins-September-24-2026/main.pdf"},{"title":"An FPRAS for Cell-Bounded Contingency Tables","path":"preprints/An-FPRAS-for-Cell-Bounded-Contingency-Tables-September-24-2026/main.pdf"}]},{"id":"116","title":"Uniform black-box noncommutative identity testing across characteristics","desc":"For each characteristic, constructs in deterministic polynomial bit time a polynomial-dimensional matrix tuple detecting every nonzero division-free noncommutative formula of bounded size over any field of that characteristic. Rational formulas over ℚ also admit polynomial-size hitting lists whenever they have a defined rational-matrix evaluation.","subject":"Theoretical computer science","lean":2,"applied":2,"difficulty":3,"year":null,"note":"Derandomized identity testing for noncommutative formulas. A link to symbolic computation.","papers":[{"title":"Uniform Matrix Hitting Points in Every Positive Characteristic","path":"preprints/Uniform-Matrix-Hitting-Points-in-Every-Positive-Characteristic-October-4-2026/uniform-matrix-hitting-points-positive-characteristic.pdf"},{"title":"One Rational Matrix Hitting Point for Noncommutative Formulas","path":"preprints/One-Rational-Matrix-Hitting-Point-for-Noncommutative-Formulas-September-24-2026/One-Rational-Matrix-Hitting-Point-for-Noncommutative-Formulas-September-24-2026.pdf"},{"title":"Polynomial Hitting Lists for Noncommutative Rational Formulas","path":"preprints/Polynomial-Hitting-Lists-for-Noncommutative-Rational-Formulas-September-24-2026/Polynomial-Hitting-Lists-for-Noncommutative-Rational-Formulas-September-24-2026.pdf"}]},{"id":"117","title":"Uniform sparsest cut: hardness and semidefinite gaps","desc":"Proves that approximating Uniform Sparsest Cut within any fixed constant factor is NP-hard, even with nonnegative rational capacities and unit demands. The Goemans–Linial semidefinite relaxation also has integrality gaps of order at least $\\sqrt{\\log n}/(\\log\\log n)^3$, approaching the square-root-logarithmic upper bound.","subject":"Theoretical computer science","lean":2,"applied":3,"difficulty":4,"year":null,"note":"No constant-factor approximation for a standard graph-partitioning objective unless P = NP.","papers":[{"title":"Constant-factor hardness of uniform sparsest cut","path":"preprints/Constant-factor-hardness-of-uniform-sparsest-cut-September-24-2026/Constant-factor-hardness-of-uniform-sparsest-cut-September-24-2026.pdf"},{"title":"Near-square-root logarithmic integrality gaps for uniform sparsest cut","path":"preprints/Near-square-root-logarithmic-integrality-gaps-for-uniform-sparsest-cut-September-24-2026/Near-square-root-logarithmic-integrality-gaps-for-uniform-sparsest-cut-September-24-2026.pdf"}]},{"id":"118","title":"Bin packing and unbounded configuration-LP gaps","desc":"Disproves the modified integer round-up conjecture of Scheithauer and Terno: the integral bin-packing optimum can exceed its configuration linear-programming value by an arbitrarily large additive constant. Approximating the optimum within any fixed additive constant is also NP-hard, even when every item exceeds 1/6 and each bin holds at most five items.","subject":"Theoretical computer science","lean":2,"applied":4,"difficulty":4,"year":1997,"note":"Cutting-stock solvers lean on the linear-programming bound being within one or two of the optimum. The gap is unbounded in general and additive approximation is hard.","papers":[{"title":"Additive hardness and unbounded configuration gaps in bin packing","path":"preprints/Additive-hardness-and-unbounded-configuration-gaps-in-bin-packing-September-24-2026/Additive-hardness-and-unbounded-configuration-gaps-in-bin-packing-September-24-2026.pdf"}]},{"id":"119","title":"The Courtade–Kumar and Hellinger conjectures","desc":"Proves the Courtade–Kumar conjecture: among Boolean functions of independent uniform bits, a single coordinate retains the most mutual information after independent bit-flip noise. A stronger theorem treats randomized binary summaries at fixed initial information. The Hellinger conjecture is also proved for every Boolean output bias and noise correlation.","subject":"Theoretical computer science","lean":2,"applied":3,"difficulty":3,"year":2014,"note":"Information retained by a Boolean summary of noisy data. Feeds bounds in information theory and learning.","papers":[{"title":"Sharp binary-information contraction on the discrete cube","path":"preprints/Sharp-binary-information-contraction-on-the-discrete-cube-September-24-2026/main.pdf"},{"title":"Hellinger contraction with arbitrary Boolean output bias","path":"preprints/Hellinger-contraction-with-arbitrary-Boolean-output-bias-September-24-2026/main.pdf"}]},{"id":"120","title":"Almost-linear-time exact matching and prescribed-degree factors in general graphs","desc":"Gives a randomized algorithm finding an exact maximum-cardinality matching in any simple undirected graph in $(n+m)^{1+o(1)}$ word time, with success probability at least 2/3. The time bound holds on every computation path. The same guarantees apply to finding a spanning subgraph with prescribed admissible vertex degrees, or deciding that none exists.","subject":"Theoretical computer science","lean":0,"applied":5,"difficulty":5,"year":1980,"note":"Maximum matching is a standard subroutine. Almost-linear time replaces the square-root barrier that has stood for general graphs.","papers":[{"title":"Almost-Linear-Time Maximum-Cardinality Matching in General Graphs","path":"preprints/Almost-Linear-Time-Maximum-Cardinality-Matching-in-Sparse-General-Graphs-September-24-2026/main.pdf"}]},{"id":"121","title":"Almost-linear approximation of edit distance","desc":"For every fixed rational $\\varepsilon\\in(0,1)$, gives a randomized $(1+\\varepsilon)$ approximation to unit-cost edit distance in worst-case expected time $N^{1+o(1)}$, with success probability at least 2/3. The strings have total length <i>N<\/i> and polynomially bounded integer symbols. This is an asymptotic guarantee at fixed accuracy.","subject":"Theoretical computer science","lean":1,"applied":5,"difficulty":4,"year":null,"note":"Sequence comparison at genomic scale. Exact edit distance is quadratic under standard hypotheses; this approximates within any fixed factor in almost-linear time.","papers":[{"title":"An Almost-Linear Approximation Scheme for Edit Distance","path":"preprints/An-Almost-Linear-Approximation-Scheme-for-Edit-Distance-September-24-2026/paper.pdf"}]},{"id":"122","title":"Quantitative trace-reconstruction bounds with a uniform decoder","desc":"At every fixed deletion probability in $(0,1)$, reconstructing an arbitrary length-<i>n<\/i> binary string requires $n^{\\Omega(\\log\\log n)}$ independent traces, ruling out polynomial-sample reconstruction. A uniform decoder achieves quasipolynomial sample and running-time bounds for known fixed rational retention probabilities. When the deletion probability is at most $n^{-\\varepsilon}$ for fixed <i>ε<\/i> &gt; 0, both bounds become polynomial in the input and parameter encoding.","subject":"Theoretical computer science","lean":1,"applied":3,"difficulty":3,"year":2004,"note":"Reading data back from DNA storage is a trace reconstruction problem. Polynomially many reads do not suffice in the worst case.","papers":[{"title":"Uniform quasipolynomial-time trace reconstruction","path":"preprints/Uniform-quasipolynomial-time-trace-reconstruction-October-5-2026/uniform-trace-reconstruction.pdf"},{"title":"A latest-anchor induction with spectrally compact masks for worst-case trace reconstruction","path":"preprints/A-latest-anchor-induction-with-spectrally-compact-masks-for-worst-case-trace-reconstruction-October-5-2026/paper.pdf"},{"title":"Quantitative lower bounds for trace reconstruction","path":"preprints/quantitative-lower-bounds-for-trace-reconstruction-September-24-2026/paper.pdf"}]},{"id":"124","title":"Polynomial-time scheduling on three identical machines","desc":"Resolves the three-processor unit-job scheduling problem of Garey and Johnson: a deterministic polynomial-time algorithm minimizes makespan for nonpreemptive unit-length jobs with arbitrary precedence constraints on three identical parallel machines. For an explicitly given precedence graph, it decides deadline feasibility exactly and constructs a feasible schedule.","subject":"Theoretical computer science","lean":1,"applied":3,"difficulty":5,"year":1979,"note":"One of the original open scheduling problems of Garey and Johnson. The model is narrow: unit jobs, precedence constraints, three machines.","papers":[{"title":"A Polynomial-Time Algorithm for Three-Machine Unit-Job Scheduling","path":"preprints/A-polynomial-time-algorithm-for-three-machine-unit-job-scheduling-September-24-2026/paper.pdf"}]},{"id":"125","title":"The metric <i>k<\/i>-median approximation threshold and recovery","desc":"Gives a deterministic polynomial-time $(1+2/e+\\varepsilon)$-approximation for finite rational metric <i>k<\/i>-median with specified candidate facilities, for every fixed <i>ε<\/i> &gt; 0. Assuming $P\\ne NP$, the optimal infimum approximation factor is $1+2/e$.","subject":"Theoretical computer science","lean":2,"applied":4,"difficulty":4,"year":2002,"note":"Tight approximation factor for a standard clustering objective.","papers":[{"title":"Single-exponential recovery and bounded-price strictness for metric k-median","path":"preprints/Single-Exponential-Recovery-and-Bounded-Price-Strictness-for-Metric-k-Median-September-24-2026/paper.pdf"},{"title":"The approximation threshold for metric k-median","path":"preprints/The-Approximation-Threshold-for-Metric-k-Median-September-24-2026/main.pdf"}]},{"id":"126","title":"Exponential semidefinite complexity of perfect matching","desc":"Proves that every exact semidefinite lift of the perfect matching polytope has exponential size, answering Rothvoss&#x27;s polynomial-size lift question negatively. The bound holds even for the positive semidefinite rank of its odd-cut slack matrix after any fixed shift $0\\lt \\rho\\lt 1$, allowing arbitrary real positive semidefinite factors.","subject":"Theoretical computer science","lean":1,"applied":3,"difficulty":3,"year":2014,"note":"No compact semidefinite formulation of matching exists. A limit on what convex relaxation can do.","papers":[{"title":"Exponential PSD rank of positively shifted matching matrices","path":"preprints/Exponential-PSD-rank-of-positively-shifted-matching-matrices-October-5-2026/shifted-matching-psd.pdf"}]},{"id":"127","title":"Average sensitivity of polynomial threshold functions","desc":"Proves that a degree-at-most-<i>d<\/i> polynomial threshold function on the uniform <i>n<\/i>-dimensional Boolean cube has average sensitivity at most $8d\\sqrt n$, uniformly for $1\\le d\\le n$. Average sensitivity counts expected output changes under single-bit flips. This establishes the asymptotic Gotsman–Linial conjecture, allowing polynomial zeros with $\\mathop{\\mathrm{sign}}\\nolimits (0)=1$.","subject":"Theoretical computer science","lean":2,"applied":3,"difficulty":4,"year":1994,"note":"Controls noise sensitivity and learnability of polynomial threshold classifiers.","papers":[{"title":"Average sensitivity of polynomial threshold functions","path":"preprints/Average-Sensitivity-of-Polynomial-Threshold-Functions-September-25-2026/main.pdf"}]},{"id":"128","title":"A factor-two approximation for shortest common superstring","desc":"Gives a deterministic polynomial-time algorithm constructing a common superstring of length at most twice the optimum for every finite family of explicitly represented strings. The running time is polynomial in the full encoded input length, including symbol labels.","subject":"Theoretical computer science","lean":2,"applied":3,"difficulty":4,"year":1991,"note":"String assembly and compression primitive. Improves the best known factor from about 2.47 to 2.","papers":[{"title":"A Polynomial-Time 2-Approximation for Shortest Common Superstring","path":"preprints/A-Polynomial-Time-2-Approximation-for-Shortest-Common-Superstring-September-24-2026/paper.pdf"}]},{"id":"129","title":"Exponential state costs for two-way automata","desc":"Proves exponential lower bounds both for complementing two-way nondeterministic finite automata and for simulating one-way nondeterministic automata by two-way deterministic ones. The latter resolves the Sakoda–Sipser state-succinctness conjecture over growing finite alphabets; both results rule out polynomial state bounds independent of alphabet size.","subject":"Theoretical computer science","lean":2,"applied":1,"difficulty":5,"year":1978,"note":"State complexity of automata. No route to practice identified.","papers":[{"title":"An exponential state lower bound for two-way nondeterministic complementation","path":"preprints/An-exponential-state-lower-bound-for-two-way-nondeterministic-complementation-September-25-2026/paper.pdf"},{"title":"An exponential two-way deterministic state lower bound for one-way liveness","path":"preprints/An-exponential-two-way-deterministic-state-lower-bound-for-one-way-liveness-September-25-2026/main.pdf"}]},{"id":"130","title":"Exact Fourier transforms below $n\\log n$","desc":"Gives a deterministic length-<i>n<\/i> discrete Fourier transform algorithm using $O(n(\\log n)^{1-\\delta})$ operations for every <i>n<\/i>, with explicit $\\delta=10^{-13}$. The model uses exact complex arithmetic, unrestricted coefficients and a supplied root of unity, and counts scalar preparation and logarithmic-word indexing.","subject":"Theoretical computer science","lean":2,"applied":2,"difficulty":5,"year":1965,"note":"Shows n log n is not a barrier for the Fourier transform. The saving exponent is 10^-13, which has no numerical use.","papers":[{"title":"An explicit power saving for the exact discrete Fourier transform","path":"preprints/An-explicit-power-saving-for-the-exact-discrete-Fourier-transform-September-25-2026/main.pdf"},{"title":"Finite tensor savings and exact Fourier circuits","path":"preprints/Finite-tensor-savings-and-exact-Fourier-circuits-September-25-2026/main.pdf"}]},{"id":"131","title":"Rapid mixing of graph switches for every degree sequence","desc":"Resolves the simple-undirected Kannan–Tetali–Vempala conjecture: the lazy edge-switch chain mixes in $O(n^8)$ time for every graphical labeled degree sequence. The same degree-constrained graphs can also be sampled exactly uniformly by an almost-surely terminating algorithm with expected polynomial bit running time.","subject":"Theoretical computer science","lean":1,"applied":4,"difficulty":4,"year":1999,"note":"The switch chain is the standard way to sample null-model networks with fixed degrees. The proof covers every degree sequence, with a bound of order n^8.","papers":[{"title":"Polynomial mixing of the switch chain for every graphical degree sequence","path":"preprints/Polynomial-Mixing-of-the-Switch-Chain-for-Every-Graphical-Degree-Sequence-September-25-2026/main.pdf"}]},{"id":"132","title":"A superquadratic separation of sensitivity and block sensitivity","desc":"Constructs total Boolean functions with block sensitivity $\\mathop{\\mathrm{bs}}\\nolimits (f)\\ge s(f)^\\alpha$ for a fixed <i>α<\/i> &gt; 2, disproving the quadratic strengthening of the Sensitivity Conjecture. Here $s(f)$ counts influential individual-bit flips, while block sensitivity allows disjoint groups of bits to change together.","subject":"Theoretical computer science","lean":2,"applied":1,"difficulty":3,"year":1992,"note":"Boolean function complexity measures. No route identified.","papers":[{"title":"A superquadratic separation between sensitivity and block sensitivity","path":"preprints/A-superquadratic-separation-between-sensitivity-and-block-sensitivity-September-25-2026/paper.pdf"}]},{"id":"133","title":"The computational complexity of Weisfeiler–Leman refinement","desc":"Proves unconditional $n^{\\Omega(k)}$ deterministic time lower bounds for joint and separate <i>k<\/i>-dimensional Weisfeiler–Leman equivalence, for sufficiently large fixed <i>k<\/i> in the specified sequential adjacency-matrix models. With dimension as input, joint equivalence is EXPTIME-complete even on subcubic graphs; deciding whether refinement identifies a graph is also EXPTIME-complete.","subject":"Theoretical computer science","lean":1,"applied":2,"difficulty":3,"year":null,"note":"Lower bounds for the colour-refinement procedure behind graph isomorphism heuristics and the expressive power of graph neural networks.","papers":[{"title":"Parity lifts and bounded-treewidth witnesses for Weisfeiler–Leman equivalence","path":"preprints/Parity-lifts-and-bounded-treewidth-witnesses-for-Weisfeiler-Leman-equivalence-September-25-2026/paper.pdf"},{"title":"The complexity of identifying a graph by Weisfeiler–Leman refinement","path":"preprints/The-complexity-of-identifying-a-graph-by-Weisfeiler-Leman-refinement-September-25-2026/paper.pdf"},{"title":"Unconditional time lower bounds for Weisfeiler–Leman equivalence","path":"preprints/Unconditional-time-lower-bounds-for-Weisfeiler-Leman-equivalence-September-25-2026/paper.pdf"},{"title":"Variable-dimension Weisfeiler–Leman equivalence on general and subcubic graphs","path":"preprints/Variable-dimension-Weisfeiler-Leman-equivalence-on-general-and-subcubic-graphs-September-25-2026/paper.pdf"}]},{"id":"134","title":"Generalized star height at most three","desc":"Every regular language over a finite alphabet has a generalized regular expression with at most three nested Kleene stars, allowing union, concatenation and complement over the same alphabet. This establishes an absolute bound independent of automaton size, resolving the uniform-boundedness version of the generalized star-height problem.","subject":"Theoretical computer science","lean":1,"applied":1,"difficulty":5,"year":null,"note":"Regular expressions with complement. No route to practice identified.","papers":[{"title":"Finite Monoid Computations and a Uniform Generalized Star-Height Bound","path":"preprints/Finite-Monoid-Computations-and-a-Uniform-Generalized-Star-Height-Bound-September-25-2026/Finite-Monoid-Computations-and-a-Uniform-Generalized-Star-Height-Bound-September-25-2026.pdf"},{"title":"Generalized Star Height at Most Four","path":"preprints/Generalized-Star-Height-at-Most-Four-September-25-2026/Generalized-Star-Height-at-Most-Four-September-25-2026.pdf"},{"title":"Generalized Star Height at Most Three","path":"preprints/Generalized-Star-Height-at-Most-Three-September-25-2026/article.pdf"}]},{"id":"135","title":"Homogeneous depth-five lower bounds for iterated matrix multiplication","desc":"Over every characteristic-zero field, the $(1,1)$ entry of a product of <i>n<\/i> independent $n\\times n$ variable matrices requires $n^{\\Theta(\\sqrt n)}$ gates in homogeneous depth-five sum–product circuits. This sharp bound allows shared gates and bottom linear forms involving all variables.","subject":"Theoretical computer science","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Algebraic circuit lower bounds. No route identified.","papers":[{"title":"Homogeneous depth-five lower bounds for iterated matrix multiplication","path":"preprints/Homogeneous-depth-five-lower-bounds-for-iterated-matrix-multiplication-September-25-2026/Homogeneous-depth-five-lower-bounds-for-iterated-matrix-multiplication-September-25-2026.pdf"}]},{"id":"136","title":"A quasilinear PCP theorem for PPAD","desc":"Resolves the quasilinear PCP-for-PPAD conjecture. An End-of-Line instance of length <i>N<\/i> reduces to numerical circuit constraints of total length $N(\\log N)^{O(1)}$ such that any polynomially encoded rational assignment satisfying all but a fixed fraction to fixed accuracy yields an endpoint solution. Such assignments always exist, giving robust local verification with only quasilinear size overhead.","subject":"Theoretical computer science","lean":0,"applied":2,"difficulty":3,"year":2016,"note":"Hardness of approximate equilibrium computation.","papers":[{"title":"The PCP-for-PPAD conjecture: a quasilinear reduction","path":"preprints/The-PCP-for-PPAD-conjecture-a-quasilinear-reduction-September-25-2026/paper.pdf"}]},{"id":"137","title":"One-tape time simulation in two-fifths-power space","desc":"Determines the halting and finite-control outcome of a fixed deterministic one-writable-tape machine up to time <i>T<\/i> using $O(T^{2/5}\\log^C(T+2))$ space, improving the square-root exponent. Heads move at most one cell per step; finitely many read-only input heads are allowed. Initial contents are independent of <i>T<\/i>, and contents and input symbols have polylogarithmic-space access. Simulation time is unrestricted.","subject":"Theoretical computer science","lean":0,"applied":1,"difficulty":4,"year":1968,"note":"Time-space simulation of Turing machines. No route identified.","papers":[{"title":"Simulating One-Tape Time in Two-Fifths-Power Space","path":"preprints/Simulating-One-Tape-Time-in-Two-Fifths-Power-Space-September-25-2026/article.pdf"}]},{"id":"138","title":"Subset Sum in $O(2^{0.49n})$ time","desc":"Gives a uniform randomized classical algorithm for worst-case Subset Sum in ordinary $O(2^{0.49n})$ word-RAM time on polynomial-bit inputs, where <i>n<\/i> counts the integers. The time bound holds on every execution and success probability is at least 2/3 on every input. Inputs may repeat positive integers; words have $O(n+b)$ bits for maximum input bit length <i>b<\/i>.","subject":"Theoretical computer science","lean":0,"applied":3,"difficulty":5,"year":1974,"note":"Breaks the meet-in-the-middle bound for Subset Sum, with consequences for knapsack-type cryptanalysis.","papers":[{"title":"Subset Sum in Time $O(2^{0.49n})$","path":"preprints/Subset-Sum-in-Time-2-power-0-49n-October-4-2026/subset-sum.pdf"},{"title":"A Low-Space Algorithm for Worst-Case Subset Sum","path":"preprints/A-Low-Space-Algorithm-for-Worst-Case-Subset-Sum-September-26-2026/paper.pdf"}]},{"id":"139","title":"Subpolynomial query complexity for log-concave sampling","desc":"For <i>C<\/i><sup>2<\/sup> potentials with a supplied minimizer and $I\\preceq\\nabla^2V\\preceq2I$, proves that sampling within total variation 1/10 requires only $C_\\varepsilon d^\\varepsilon$ exact value-and-gradient queries for every fixed <i>ε<\/i> &gt; 0. The bound holds on every run, with unrestricted computation between queries. A logarithmic lower bound also holds, so the optimal power-law exponent in this oracle model is zero.","subject":"Theoretical computer science","lean":2,"applied":4,"difficulty":3,"year":null,"note":"Query complexity of sampling for Bayesian computation. Assumes a known minimizer, condition number two and unlimited computation between queries.","papers":[{"title":"Subpolynomial query complexity for well-conditioned log-concave sampling","path":"preprints/Subpolynomial-query-complexity-for-well-conditioned-log-concave-sampling-September-26-2026/article.pdf"}]},{"id":"140","title":"Memory–sample lower bounds for noiseless Gaussian regression","desc":"For fixed <i>A<\/i> &gt; 0, a one-pass learner with $Ad^2$ persistent bits needs $\\Omega_A(d\\log(1/\\epsilon))$ noiseless Gaussian samples to recover a unit vector to angular error $0\\lt \\epsilon\\le1/10$ with probability 2/3, uniformly in accuracy for large <i>d<\/i>. Computation and randomized updates are unrestricted, but output uses only the terminal state, stopping index and fresh randomness.","subject":"Theoretical computer science","lean":2,"applied":3,"difficulty":3,"year":2019,"note":"A memory budget below d squared bits forces more samples in streaming regression.","papers":[{"title":"Memory and precision in noiseless Gaussian regression","path":"preprints/Memory-and-precision-in-noiseless-Gaussian-regression-September-27-2026/paper.pdf"},{"title":"Posterior replicas and conditional information in Gaussian regression","path":"preprints/Posterior-replicas-and-conditional-information-in-Gaussian-regression-September-27-2026/paper.pdf"},{"title":"Localization costs and information growth for exact Gaussian observations","path":"preprints/Localization-costs-and-information-growth-for-exact-Gaussian-observations-September-27-2026/paper.pdf"},{"title":"Projection moments, positive cap domination, and Riesz estimates on the sphere","path":"preprints/Projection-moments-positive-cap-domination-and-Riesz-estimates-on-the-sphere-September-27-2026/paper.pdf"},{"title":"Replacing Gaussian observations in memory-constrained inference","path":"preprints/Replacing-Gaussian-observations-in-memory-constrained-inference-September-27-2026/paper.pdf"},{"title":"Subsphere methods for memory-sample lower bounds in noiseless Gaussian regression","path":"preprints/Subsphere-methods-for-memory-sample-lower-bounds-in-noiseless-Gaussian-regression-September-27-2026/paper.pdf"}]},{"id":"141","title":"Existential–universal real sentences in the counting hierarchy","desc":"Proves that the existential theory of the reals lies in the counting hierarchy. More generally, truth of existential–universal real sentences can be decided at one fixed level of that hierarchy, even when their integer polynomials are specified by arithmetic circuits.","subject":"Theoretical computer science","lean":0,"applied":2,"difficulty":3,"year":1988,"note":"Places the existential theory of the reals, the home of many geometric and robotics decision problems, lower in the complexity hierarchy.","papers":[{"title":"Existential–universal real sentences in the counting hierarchy","path":"preprints/Existential-universal-real-sentences-in-the-counting-hierarchy-October-4-2026/etr-counting-hierarchy.pdf"}]},{"id":"142","title":"Deterministic polynomial factorization over prime fields","desc":"Gives a uniform deterministic algorithm that completely factors every nonzero dense degree-<i>n<\/i> polynomial over a prime field 𝔽<sub><i>p<\/i><\/sub>, including multiplicities, in bit complexity polynomial in $(n+1)\\log p$. The prime is supplied in binary. No randomness, integer-factorization or primitive-root oracle, or GRH assumption is required.","subject":"Theoretical computer science","lean":0,"applied":3,"difficulty":5,"year":1967,"note":"Removes randomness from polynomial factoring over finite fields without the Riemann hypothesis. Practice already uses fast randomized methods.","papers":[{"title":"Deterministic Polynomial Factorization over Prime Fields","path":"preprints/Deterministic-Polynomial-Factorization-over-Prime-Fields-October-4-2026/Deterministic-Polynomial-Factorization-over-Prime-Fields.pdf"}]},{"id":"143","title":"Hilbert&#x27;s sixteenth problem: uniform bounds for limit cycles","desc":"Resolves the uniform boundedness assertion in Hilbert&#x27;s sixteenth problem: the number of isolated periodic orbits of a real planar polynomial vector field is bounded by a finite constant depending only on its degree. For classical quintic Liénard systems, the exact maximum is two limit cycles.","subject":"Dynamical systems and ergodic theory","lean":2,"applied":2,"difficulty":5,"year":1900,"note":"Limit cycles of polynomial vector fields model oscillators. A uniform bound exists; the result is qualitative.","papers":[{"title":"Uniform bounds for planar polynomial limit cycles","path":"preprints/uniform-bounds-for-planar-polynomial-limit-cycles-September-24-2026/uniform-bounds-for-planar-polynomial-limit-cycles-September-24-2026.pdf"},{"title":"Two limit cycles for quintic Liénard systems","path":"preprints/two-limit-cycles-for-quintic-lienard-systems-September-24-2026/two-limit-cycles-for-quintic-lienard-systems-September-24-2026.pdf"}]},{"id":"144","title":"Banach’s simple Lebesgue-spectrum problem","desc":"Resolves the probability-preserving form of Banach&#x27;s simple Lebesgue-spectrum problem within smooth dynamics. A smooth volume-preserving diffeomorphism of the standard-volume three-torus has simple Lebesgue spectrum on its entire complex mean-zero <i>L<\/i><sup>2<\/sup> space: the bilateral iterates of one real observable form an orthonormal basis of that space.","subject":"Dynamical systems and ergodic theory","lean":1,"applied":1,"difficulty":5,"year":null,"note":"Spectral theory of dynamical systems. No route identified.","papers":[{"title":"A smooth three-torus diffeomorphism with simple Lebesgue spectrum","path":"preprints/A-smooth-three-torus-diffeomorphism-with-simple-Lebesgue-spectrum-September-23-2026/paper.pdf"}]},{"id":"145","title":"Rokhlin’s multiple-mixing problem","desc":"Proves that every invertible mixing probability-preserving transformation is mixing of all finite orders, resolving Rokhlin&#x27;s multiple-mixing problem for a single transformation. Correlations among any finite collection of measurable sets converge to the product of their measures whenever all pairwise time separations diverge.","subject":"Dynamical systems and ergodic theory","lean":1,"applied":1,"difficulty":5,"year":1949,"note":"Ergodic theory. No route identified.","papers":[{"title":"Rokhlin&#x27;s multiple-mixing problem for one transformation","path":"preprints/Rokhlins-multiple-mixing-problem-for-one-transformation-September-23-2026/paper.pdf"}]},{"id":"146","title":"Positive metric entropy for the standard map","desc":"Proves that the standard sine map on the two-dimensional torus has positive metric entropy with respect to area for every sufficiently large positive parameter. This establishes Sinai&#x27;s positive-parameter-measure conjecture for the original family, with the stronger conclusion of a full parameter tail.","subject":"Dynamical systems and ergodic theory","lean":1,"applied":2,"difficulty":5,"year":1994,"note":"The standard map is the model for chaos in accelerators and plasma confinement. The theorem confirms a chaotic region of positive area at large parameter.","papers":[{"title":"Positive Metric Entropy for the Standard Map at Large Parameters","path":"preprints/Positive-Metric-Entropy-for-the-Standard-Map-at-Large-Parameters-September-23-2026/paper.pdf"}]},{"id":"147","title":"The near-boundary Birkhoff conjecture","desc":"Resolves the near-boundary Birkhoff conjecture for smooth strictly convex planar billiards of positive curvature. Such a billiard is an ellipse whenever a full grazing annulus is continuously foliated by individually invariant essential curves. A continuous physical collar of smooth closed convex caustics also suffices.","subject":"Dynamical systems and ergodic theory","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Integrable billiards. No route identified.","papers":[{"title":"Continuous Phase Foliations Create Analytic Caustic Collars","path":"preprints/Continuous-Phase-Foliations-Create-Analytic-Caustic-Collars-September-24-2026/paper.pdf"},{"title":"Rigidity of Smooth Billiards with a Continuous Caustic Collar","path":"preprints/Rigidity-of-Smooth-Billiards-with-a-Continuous-Caustic-Collar-September-24-2026/paper.pdf"}]},{"id":"148","title":"The entropy-rate dimension formula for self-similar measures","desc":"For every self-similar measure on the line generated by finitely many contracting similarities, proves $\\dim_{\\mathrm H}\\mu=\\min\\{1,h_{\\mathrm{RW}}/\\chi\\}$, where $h_{\\mathrm{RW}}$ is the entropy rate of random composed maps and <i>χ<\/i> the average logarithmic contraction. This resolves the entropy-rate dimension conjecture without a separation assumption, allowing exact overlaps and unequal contraction ratios.","subject":"Dynamical systems and ergodic theory","lean":2,"applied":1,"difficulty":4,"year":null,"note":"Fractal measures. No route identified.","papers":[{"title":"The entropy-rate dimension formula for self-similar measures on the line","path":"preprints/The-entropy-rate-dimension-formula-for-self-similar-measures-on-the-line-September-24-2026/main.pdf"}]},{"id":"149","title":"Classwise permanence for weakly reversible mass-action systems","desc":"Proves the permanence conjecture for every finite weakly reversible mass-action system with fixed positive rate constants. Every positive stoichiometric compatibility class, even an unbounded one, has a common compact convex forward-invariant absorbing set. All positive trajectories in that class therefore eventually share positive lower and finite upper concentration bounds.","subject":"Dynamical systems and ergodic theory","lean":1,"applied":4,"difficulty":4,"year":1974,"note":"Mass-action networks model chemistry and systems biology. Weakly reversible networks can neither go extinct nor blow up, whatever the rate constants.","papers":[{"title":"Uniform Permanence in Weakly Reversible Mass-Action Systems","path":"preprints/Uniform-Permanence-in-Weakly-Reversible-Mass-Action-Systems-October-5-2026/permanence.pdf"},{"title":"Boundedness and persistence of weakly reversible mass-action systems","path":"preprints/Boundedness-and-persistence-of-weakly-reversible-mass-action-systems-September-25-2026/paper.pdf"}]},{"id":"150","title":"Weak mixing of triangular billiards with an irrational angle","desc":"Proves that the billiard flow in every nondegenerate Euclidean triangle with at least one angle irrational relative to <i>π<\/i> is weakly mixing for normalized area times uniform direction. This strengthens ergodicity on the entire irrational-angle class, with no genericity or Diophantine restrictions.","subject":"Dynamical systems and ergodic theory","lean":1,"applied":1,"difficulty":4,"year":null,"note":"Polygonal billiards. No route identified.","papers":[{"title":"Weak mixing of triangular billiards with an irrational angle","path":"preprints/Weak-mixing-of-triangular-billiards-with-an-irrational-angle-October-5-2026/weak-mixing-triangular-billiards.pdf"},{"title":"Ergodicity of triangular billiards with an irrational angle","path":"preprints/Ergodicity-of-triangular-billiards-with-an-irrational-angle-September-25-2026/Ergodicity-of-triangular-billiards-with-an-irrational-angle-September-25-2026.pdf"}]},{"id":"151","title":"A <i>C<\/i><sup>1<\/sup> counterexample to the entropy conjecture","desc":"Constructs a noninvertible <i>C<\/i><sup>1<\/sup> self-map of a compact smooth manifold with zero topological entropy but eigenvalue 2 on second homology. This disproves the homological entropy lower bound for general <i>C<\/i><sup>1<\/sup> self-maps: homological growth need not force positive orbit complexity.","subject":"Dynamical systems and ergodic theory","lean":1,"applied":1,"difficulty":4,"year":1974,"note":"Topological entropy. No route identified.","papers":[{"title":"A C^1 Counterexample to the Entropy Conjecture","path":"preprints/A-C1-Counterexample-to-the-Entropy-Conjecture-September-25-2026/article.pdf"}]},{"id":"152","title":"Zero entropy does not guarantee a smooth positive-volume model","desc":"Constructs a zero-entropy ergodic invertible transformation of a standard nonatomic probability space that is not measurably conjugate to any <i>C<\/i><sup>∞<\/sup> diffeomorphism preserving a strictly positive smooth probability density on a compact finite-dimensional manifold. One example rules out every finite dimension.","subject":"Dynamical systems and ergodic theory","lean":1,"applied":1,"difficulty":4,"year":null,"note":"Smooth realization in ergodic theory. No route identified.","papers":[{"title":"A zero-entropy system without a smooth positive-volume model","path":"preprints/A-finite-entropy-system-without-a-smooth-positive-volume-model-September-25-2026/paper.pdf"}]},{"id":"153","title":"Arithmetic classification and non-Pisot singularity for Bernoulli convolutions","desc":"Classifies singular and absolutely continuous unbiased Bernoulli convolutions for every $\\lambda\\in(0,1)$ by an infinite, one-sided approximation condition using explicit finite sets of algebraic units. It also proves singularity at reciprocals of every quartic Salem number in $(1,2)$, giving examples beyond reciprocal Pisot parameters.","subject":"Dynamical systems and ergodic theory","lean":0,"applied":1,"difficulty":5,"year":1939,"note":"Bernoulli convolutions. A weak link to digital expansions.","papers":[{"title":"Arithmetic classification and non-Pisot singularity for Bernoulli convolutions","path":"preprints/Arithmetic-classification-and-non-Pisot-singularity-for-Bernoulli-convolutions-October-3-2026/paper.pdf"}]},{"id":"154","title":"Pointwise multiple ergodic averages for mixing transformations","desc":"Proves almost-everywhere convergence of consecutive multiple ergodic averages of every finite length for invertible mixing probability-preserving transformations. For each fixed tuple of bounded functions, the limit is the product of their integrals, along all positive averaging lengths. No mixing rate or standardness assumption on the probability space is required.","subject":"Dynamical systems and ergodic theory","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Ergodic theory. No route identified.","papers":[{"title":"Pointwise Multiple Ergodic Averages for Mixing Transformations","path":"preprints/Pointwise-Multiple-Ergodic-Averages-for-Mixing-Transformations-October-4-2026/multiple-ergodic-averages.pdf"},{"title":"Pointwise convergence of fourfold ergodic averages for mixing transformations","path":"preprints/Pointwise-convergence-of-fourfold-ergodic-averages-for-mixing-transformations-October-4-2026/fourfold-ergodic-averages.pdf"},{"title":"Triple ergodic averages with distinct integer slopes","path":"preprints/Triple-ergodic-averages-with-distinct-integer-slopes-October-4-2026/triple-ergodic-distinct-slopes.pdf"},{"title":"Pointwise convergence of triple ergodic averages for mixing transformations","path":"preprints/Pointwise-convergence-of-triple-ergodic-averages-for-mixing-transformations-October-4-2026/pointwise-triple-ergodic-averages-mixing-transformations.pdf"}]},{"id":"155","title":"A counterexample to periodic tiling in dimension three","desc":"Constructs a finite translational tile in ℤ<sup>3<\/sup> that tiles space but admits no fully periodic tiling, disproving the periodic tiling conjecture in the smallest possible lattice dimension. Its unit-cube thickening gives the same counterexample in ℝ<sup>3<\/sup>, even with arbitrary real translation vectors.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":3,"year":1996,"note":"Tilings. A weak link to aperiodic order.","papers":[{"title":"A translational tile with no fully periodic tiling in dimension three","path":"preprints/A-translational-tile-with-no-fully-periodic-tiling-in-dimension-three-September-23-2026/paper.pdf"}]},{"id":"156","title":"Borsuk&#x27;s conjecture fails in dimension nine","desc":"Constructs a compact subset of ℝ<sup>9<\/sup> that cannot be covered by ten sets of strictly smaller diameter, disproving Borsuk&#x27;s covering assertion already in dimension nine. The example consists of rank-one orthogonal projectors onto lines in ℝ<sup>4<\/sup>, with the Frobenius metric.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":4,"year":1933,"note":"Combinatorial geometry. No route identified.","papers":[{"title":"A nine-dimensional counterexample to Borsuk&#x27;s covering assertion","path":"preprints/A-nine-dimensional-counterexample-to-Borsuks-covering-assertion-September-23-2026/paper.pdf"}]},{"id":"157","title":"Graph coloring, clique minors, and Colin de Verdière invariants","desc":"Disproves Hadwiger&#x27;s conjecture even for fractional coloring: arbitrarily large finite simple graphs with independence number at most two satisfy $\\chi_f(G)\\gt h(G)$, where $h(G)$ is the largest clique-minor order. Also disproves the fractional Colin de Verdière chromatic bound $\\chi_f(G)\\le\\mu(G)+1$. In the positive direction, every finite nonempty graph satisfies $\\chi_{\\mathrm{list}}(G)\\le C h(G)$ for a universal constant <i>C<\/i>.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":5,"year":1943,"note":"Graph colouring theory. No route identified.","papers":[{"title":"A counterexample to Hadwiger&#x27;s conjecture","path":"preprints/A-counterexample-to-Hadwigers-conjecture-September-23-2026/paper.pdf"},{"title":"A counterexample to the Colin de Verdière chromatic conjecture","path":"preprints/A-counterexample-to-the-Colin-de-Verdiere-chromatic-conjecture-September-23-2026/paper.pdf"},{"title":"A linear list-coloring bound in terms of the Hadwiger number","path":"preprints/A-linear-list-coloring-bound-in-terms-of-the-Hadwiger-number-September-23-2026/paper.pdf"}]},{"id":"158","title":"The Euclidean plane cannot be colored with five colors","desc":"Proves that every five-coloring of the Euclidean plane has a monochromatic pair at distance one, with no restriction on the color classes. This advances the Hadwiger–Nelson problem: together with the classical seven-coloring, only six and seven remain possible chromatic numbers of the plane.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":5,"year":1950,"note":"Combinatorial geometry. No route identified.","papers":[{"title":"The Euclidean plane is not five-colorable","path":"preprints/The-Euclidean-plane-is-not-five-colorable-September-23-2026/paper.pdf"}]},{"id":"159","title":"Erdős’s reciprocal-sum conjecture and quasipolynomial Szemerédi bounds","desc":"Proves Erdős&#x27;s conjecture that every set of positive integers with divergent reciprocal sum contains arithmetic progressions of every finite length. Quantitatively, for each fixed <i>k<\/i> ≥ 3, every subset of $\\{1,\\ldots,N\\}$ with no nonconstant <i>k<\/i>-term progression has size at most $C_kN\\exp[-c_k(\\log N)^{\\varepsilon_k}]$, with positive constants depending only on <i>k<\/i>.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":5,"year":null,"note":"Additive combinatorics. No route identified.","papers":[{"title":"Quasipolynomial Bounds for Arithmetic Progressions","path":"preprints/Quasipolynomial-Bounds-for-Arithmetic-Progressions-September-23-2026/paper.pdf"}]},{"id":"160","title":"Superexponential van der Waerden numbers","desc":"Resolves Erdős&#x27;s superexponential-growth question for van der Waerden numbers. If $W_r(k)$ is the least interval length forcing a monochromatic <i>k<\/i>-term progression in every <i>r<\/i>-coloring, then $W_r(k)\\gt k^{ck\\lfloor\\log_2 r\\rfloor}$ for an absolute <i>c<\/i> &gt; 0, all <i>r<\/i> ≥ 2 and sufficiently large <i>k<\/i>, uniformly in <i>r<\/i>. In particular, $W_r(k)^{1/k}\\to\\infty$ for each fixed <i>r<\/i>.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":3,"year":null,"note":"Ramsey theory. No route identified.","papers":[{"title":"Quantitative Superexponential Bounds for van der Waerden Numbers","path":"preprints/Quantitative-Superexponential-Bounds-for-van-der-Waerden-Numbers-September-23-2026/paper.pdf"}]},{"id":"161","title":"Counterexamples to Sidorenko’s conjecture and the forcing conjecture","desc":"Disproves Sidorenko&#x27;s conjecture with a connected bipartite pattern on 35 vertices and 66 edges that occurs less frequently than in a random graph of the same edge density. The same pattern disproves the forcing conjecture of Skokan and Thoma: matching its density and the edge density of a constant graphon need not force quasirandomness.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":4,"year":1993,"note":"Subgraph density inequalities. No route identified.","papers":[{"title":"A counterexample to Sidorenko&#x27;s conjecture","path":"preprints/A-counterexample-to-Sidorenkos-conjecture-September-23-2026/paper.pdf"}]},{"id":"162","title":"Counterexamples to Ryser’s covering conjecture","desc":"Disproves Ryser&#x27;s covering conjecture by constructing intersecting $(q+1)$-partite, $(q+1)$-uniform hypergraphs with covering number $q+1$, rather than the predicted bound <i>q<\/i>, for every sufficiently large prime <i>q<\/i>. A separate construction over extension fields also disproves Gyárfás&#x27;s monochromatic tree-cover conjecture.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":4,"year":1971,"note":"Hypergraph covering. No route identified.","papers":[{"title":"Balanced counterexamples to Ryser&#x27;s conjecture at prime orders","path":"preprints/Balanced-Counterexamples-to-Rysers-Conjecture-at-Prime-Orders-September-27-2026/paper.pdf"},{"title":"A counterexample to Ryser&#x27;s covering conjecture","path":"preprints/A-Counterexample-to-Rysers-Covering-Conjecture-September-23-2026/paper.pdf"}]},{"id":"164","title":"Hindman’s finite sums and products conjecture","desc":"Proves Hindman&#x27;s finite sums and products conjecture: every finite coloring of the positive integers contains sets of any prescribed finite size whose nonempty subset sums and nonempty subset products all have one common color.","subject":"Combinatorics","lean":0,"applied":1,"difficulty":4,"year":1979,"note":"Ramsey theory. No route identified.","papers":[{"title":"Monochromatic finite sums and products in the positive integers","path":"preprints/Monochromatic-finite-sums-and-products-in-the-positive-integers-September-23-2026/paper.pdf"}]},{"id":"165","title":"The Harary–Hill and Zarankiewicz crossing-number formulas","desc":"Resolves the Harary–Hill conjecture and Turán&#x27;s brickyard problem in the Zarankiewicz formulation, determining the crossing numbers of every complete and complete bipartite graph. The result proves the optimality of the classical drawings among all plane drawings with continuous edge arcs.","subject":"Combinatorics","lean":2,"applied":2,"difficulty":5,"year":1944,"note":"Crossing numbers bound circuit layout area and measure drawing quality. Exact values for complete graphs are benchmarks.","papers":[{"title":"The crossing number of complete graphs","path":"preprints/The-crossing-number-of-complete-graphs-September-23-2026/paper.pdf"},{"title":"The crossing number of complete bipartite graphs","path":"preprints/The-crossing-number-of-complete-bipartite-graphs-September-23-2026/paper.pdf"}]},{"id":"166","title":"The higher-dimensional Erdős distinct-distances conjecture","desc":"For every fixed <i>d<\/i> ≥ 3, any <i>n<\/i> ≥ 2 distinct points in ℝ<sup><i>d<\/i><\/sup> determine at least $c_dn^{2/d}$ distinct distances, with $c_d\\gt 0$ depending only on dimension. This matches the integer-grid order and resolves the higher-dimensional Erdős distinct-distances conjecture with a constant-factor bound.","subject":"Combinatorics","lean":0,"applied":1,"difficulty":5,"year":1946,"note":"Combinatorial geometry. No route identified.","papers":[{"title":"The higher-dimensional Erdős distinct-distances conjecture","path":"preprints/The-higher-dimensional-Erdos-distinct-distances-conjecture-September-23-2026/paper.pdf"}]},{"id":"167","title":"Planar distinct distances and unit-distance bounds","desc":"Proves the weak pinned Erdős distance conjecture: for every fixed <i>ε<\/i> &gt; 0, all but $o(n)$ points of any <i>n<\/i>-point planar set determine at least $n^{1-\\varepsilon}$ distinct nonzero distances. A complementary theorem bounds the number of unit-distance pairs by $O(n^{4/3-\\delta})$ for an absolute <i>δ<\/i> &gt; 0.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":5,"year":1946,"note":"Combinatorial geometry. No route identified.","papers":[{"title":"The weak pinned planar distance theorem","path":"preprints/The-weak-pinned-planar-distance-theorem-September-23-2026/paper.pdf"},{"title":"A power saving for planar unit distances","path":"preprints/A-power-saving-for-planar-unit-distances-September-23-2026/paper.pdf"}]},{"id":"168","title":"Combinatorial invariance of Kazhdan–Lusztig polynomials","desc":"Resolves the full combinatorial invariance conjecture: isomorphic Bruhat intervals in arbitrary Coxeter systems have identical equal-parameter Kazhdan–Lusztig polynomials. Thus the abstract order of the interval determines the polynomial, even across different Coxeter systems.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":4,"year":null,"note":"Kazhdan-Lusztig theory. No route identified.","papers":[{"title":"Combinatorial invariance of Kazhdan–Lusztig polynomials","path":"preprints/Combinatorial-Invariance-of-Kazhdan-Lusztig-Polynomials-September-24-2026/paper.pdf"}]},{"id":"169","title":"Shareshian–Wachs elementary positivity","desc":"Resolves the elementary-positivity part of the Shareshian–Wachs conjecture: the chromatic quasisymmetric function of every natural unit interval graph has elementary-basis coefficients in $\\mathbb N[q]$. The coefficients count explicitly described permutations, giving a combinatorial explanation of positivity.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":3,"year":2012,"note":"Symmetric functions. No route identified.","papers":[{"title":"Elementary positivity of chromatic quasisymmetric functions","path":"preprints/Elementary-Positivity-of-Chromatic-Quasisymmetric-Functions-September-24-2026/paper.pdf"}]},{"id":"170","title":"Sharp logarithmic exponents for off-diagonal Ramsey numbers","desc":"For every fixed integer <i>s<\/i> ≥ 5, proves $r(s,t)=t^{s-1}/(\\log t)^{s-2+o(1)}$ as $t\\to\\infty$, determining the logarithmic exponent and matching the classical upper bound at that scale. Here $r(s,t)$ is the least number of vertices forcing an <i>s<\/i>-clique or a <i>t<\/i>-vertex independent set.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":4,"year":null,"note":"Ramsey theory. No route identified.","papers":[{"title":"The sharp logarithmic exponent of r(5,t)","path":"preprints/The-Sharp-Logarithmic-Exponent-of-r-5-t-September-24-2026/paper.pdf"},{"title":"Sharp logarithmic exponents for fixed off-diagonal Ramsey numbers","path":"preprints/Sharp-Logarithmic-Exponents-for-Fixed-Off-Diagonal-Ramsey-Numbers-September-24-2026/paper.pdf"}]},{"id":"171","title":"The hypercube Ramsey conjecture","desc":"Resolves the Burr–Erdős hypercube Ramsey conjecture: the two-color Ramsey number of the <i>n<\/i>-dimensional cube is $\\Theta(2^n)$. Thus every red-blue coloring of a complete graph on a universal constant times the cube&#x27;s number of vertices contains a monochromatic copy of the cube.","subject":"Combinatorics","lean":0,"applied":1,"difficulty":4,"year":1975,"note":"Ramsey theory. No route identified.","papers":[{"title":"The hypercube Ramsey number has linear order","path":"preprints/The-hypercube-Ramsey-number-has-linear-order-September-23-2026/paper.pdf"}]},{"id":"172","title":"Classification of finite Euclidean Ramsey configurations","desc":"Classifies finite point configurations that occur monochromatically, at their original scale, in every finite coloring of sufficiently high-dimensional Euclidean space. The characterization is an algebraic condition over the coordinate field. It also disproves the Leader–Russell–Walters conjecture that every such configuration is a subset of a finite transitive set.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":4,"year":1973,"note":"Ramsey theory. No route identified.","papers":[{"title":"A classification of finite Euclidean Ramsey configurations","path":"preprints/A-classification-of-finite-Euclidean-Ramsey-configurations-September-23-2026/paper.pdf"}]},{"id":"173","title":"Seymour’s second-neighborhood conjecture","desc":"Proves Seymour&#x27;s second-neighborhood conjecture: every nonempty finite oriented graph has a vertex with at least as many vertices at directed distance exactly two as at directed distance one. Oriented graphs may be arbitrary apart from the exclusion of loops and oppositely directed edge pairs.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":4,"year":1990,"note":"Directed graphs. No route identified.","papers":[{"title":"A proof of Seymour’s second-neighborhood conjecture","path":"preprints/A-proof-of-Seymours-second-neighborhood-conjecture-September-23-2026/paper.pdf"}]},{"id":"174","title":"Deterministic construction of strong thin spanning trees","desc":"Resolves the strong thin-tree conjecture constructively. Every finite loopless <i>k<\/i>-edge-connected multigraph on at least two vertices has a spanning tree containing at most a universal $C/k$ fraction of the edges of every cut. Such a tree can be found deterministically in polynomial time, even with binary-encoded parallel-edge multiplicities.","subject":"Combinatorics","lean":2,"applied":4,"difficulty":4,"year":2004,"note":"Thin spanning trees give constant-factor approximation for the asymmetric travelling salesman problem. The construction is deterministic and polynomial.","papers":[{"title":"The strong thin tree conjecture","path":"preprints/The-strong-thin-tree-conjecture-September-23-2026/paper.pdf"},{"title":"A polynomial-time construction of strong thin trees","path":"preprints/A-polynomial-time-construction-of-strong-thin-trees-September-23-2026/paper.pdf"}]},{"id":"175","title":"Talagrand’s expectation thresholds, discrete convexity, and graph decompositions","desc":"Proves that integral and fractional expectation thresholds differ by at most a universal factor, and resolves Talagrand&#x27;s discrete-convexity conjecture. An application proves the Ascoli–He–Park–Talagrand graph-decomposition conjecture: every graph&#x27;s edges split into a universally bounded number of fixed pieces, each with containment threshold at most a universal constant times the original graph&#x27;s integral expectation threshold. The pieces&#x27; embeddings need not agree on shared vertices.","subject":"Combinatorics","lean":2,"applied":2,"difficulty":3,"year":2010,"note":"Thresholds in random structures. An indirect link to the analysis of random instances.","papers":[{"title":"Graph Decompositions at the Integral Expectation Threshold","path":"preprints/Graph-Decompositions-at-the-Integral-Expectation-Threshold-October-5-2026/graph-threshold-decompositions.pdf"},{"title":"Integral and fractional expectation thresholds are equivalent","path":"preprints/Integral-and-fractional-expectation-thresholds-are-equivalent-September-23-2026/paper.pdf"},{"title":"Talagrand’s discrete-convexity conjecture","path":"preprints/Talagrands-discrete-convexity-conjecture-September-23-2026/paper.pdf"}]},{"id":"176","title":"The second Kahn–Kalai conjecture with an edge-count bound","desc":"Proves the second Kahn–Kalai conjecture: for every finite simple graph <i>H<\/i> with <i>h<\/i> ≥ 1 edges and at most <i>n<\/i> vertices, its appearance threshold in $G(n,p)$ is at most $C p_{\\mathrm E}(n,H)(1+\\log_2 h)$, with universal <i>C<\/i>. Here $p_{\\mathrm E}$ is the least density at which every subgraph of <i>H<\/i> has expected copy count at least 1/2.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":3,"year":2006,"note":"Thresholds in random graphs. No route identified.","papers":[{"title":"The second Kahn–Kalai conjecture","path":"preprints/The-second-Kahn-Kalai-conjecture-September-24-2026/paper.pdf"}]},{"id":"177","title":"Bounded-degree coboundary expanders","desc":"Constructs arbitrarily large finite <i>d<\/i>-dimensional simplicial complexes, for every <i>d<\/i> ≥ 3, with uniformly bounded vertex degrees and uniform 𝔽<sub>2<\/sub> coboundary expansion in every degree below <i>d<\/i>. Together with the known graph and two-dimensional cases, this establishes the existence of such expanders in every positive dimension.","subject":"Combinatorics","lean":1,"applied":3,"difficulty":3,"year":null,"note":"Coboundary expanders are ingredients of locally testable codes and quantum low-density parity-check codes.","papers":[{"title":"Bounded-degree coboundary expanders in every dimension","path":"preprints/Bounded-degree-coboundary-expanders-in-every-dimension-September-24-2026/paper.pdf"}]},{"id":"178","title":"Deterministic nonbipartite Ramanujan graphs in every fixed degree","desc":"For every fixed <i>d<\/i> ≥ 3, constructs a simple <i>d<\/i>-regular nonbipartite Ramanujan graph on every sufficiently large even number <i>n<\/i> of vertices, with every nonconstant adjacency eigenvalue strictly between $-2\\sqrt{d-1}$ and $2\\sqrt{d-1}$. A deterministic algorithm outputs the full adjacency list in polynomial bit time, with exponent depending on <i>d<\/i>.","subject":"Combinatorics","lean":0,"applied":4,"difficulty":5,"year":1988,"note":"Explicit optimal expanders of every degree and size serve error-correcting codes, derandomization and network design.","papers":[{"title":"Deterministic nonbipartite Ramanujan graphs in every fixed degree","path":"preprints/Deterministic-nonbipartite-Ramanujan-graphs-in-every-fixed-degree-September-23-2026/paper.pdf"}]},{"id":"179","title":"The circulant Hadamard and Barker-sequence conjectures","desc":"Proves that real circulant Hadamard matrices exist exactly in orders 1 and 4, resolving the circulant Hadamard conjecture. Together with classical Barker-sequence results, this shows that binary sequences whose nontrivial aperiodic autocorrelations have magnitude at most 1 exist at lengths <i>n<\/i> &gt; 1 exactly when $n\\in\\{2,3,4,5,7,11,13\\}$.","subject":"Combinatorics","lean":2,"applied":3,"difficulty":5,"year":1963,"note":"No Barker sequence exists beyond length 13. Radar and synchronization design has assumed this.","papers":[{"title":"The circulant Hadamard conjecture","path":"preprints/The-circulant-Hadamard-conjecture-September-23-2026/paper.pdf"}]},{"id":"180","title":"Barnette’s Hamiltonian-cycle conjecture","desc":"Proves that every finite simple cubic bipartite planar 3-vertex-connected graph has a Hamiltonian cycle, resolving Barnette&#x27;s conjecture. Equivalently, every three-edge path in a finite simple cubic 3-vertex-connected bipartite Pfaffian graph lies in a Hamiltonian cycle.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":5,"year":1969,"note":"Hamiltonian cycles. No route identified.","papers":[{"title":"Paired states and Hamiltonian cycles in cubic bipartite planar graphs","path":"preprints/Paired-states-and-Hamiltonian-cycles-in-cubic-bipartite-planar-graphs-September-24-2026/paper.pdf"}]},{"id":"181","title":"The Erdős–Gallai cycle-decomposition conjecture","desc":"Proves that the edges of every finite simple undirected graph on <i>n<\/i> vertices can be partitioned into at most $Cn$ simple cycles and single edges, for an absolute constant <i>C<\/i>. This resolves the Erdős–Gallai cycle-decomposition conjecture, bounding the number of pieces linearly even for dense graphs.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":5,"year":1966,"note":"Graph decompositions. No route identified.","papers":[{"title":"A linear cycle-and-edge decomposition of every graph","path":"preprints/A-linear-cycle-and-edge-decomposition-of-every-graph-September-24-2026/main.pdf"}]},{"id":"182","title":"Power savings for intersective polynomial differences and prime arguments","desc":"For every fixed intersective integer polynomial <i>h<\/i> of degree <i>k<\/i> ≥ 2 with positive leading coefficient, proves that a subset of $\\{1,\\ldots,N\\}$ avoiding nonzero values $h(1),h(2),\\ldots$ as differences has size $O_h(N^{1-c_k})$, with $c_k\\gt 0$ depending only on degree. Here intersective means having a root modulo every modulus. For prime arguments, a power saving also holds when <i>h<\/i> has a unit root modulo every modulus, with exponent allowed to depend on <i>h<\/i>.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Additive combinatorics. No route identified.","papers":[{"title":"A power saving for intersective polynomial differences with an exponent depending only on the degree","path":"preprints/A-power-saving-for-intersective-polynomial-differences-with-an-exponent-depending-only-on-the-degree-October-5-2026/power-saving-intersective-polynomial-differences.pdf"},{"title":"A Power Saving for Polynomial Differences at Prime Arguments","path":"preprints/A-Power-Saving-for-Polynomial-Differences-at-Prime-Arguments-October-5-2026/prime-argument-polynomial-differences.pdf"},{"title":"A power saving for square-difference-free sets","path":"preprints/A-power-saving-for-square-difference-free-sets-September-24-2026/paper.pdf"}]},{"id":"183","title":"Power savings for planar halving lines and <i>k<\/i>-sets","desc":"Improves the planar halving-line bound to $O(n^{4/3-\\varepsilon})$ for sets with no three collinear and an absolute <i>ε<\/i> &gt; 0. More generally, an <i>n<\/i>-point set with no three collinear has $O(n(k+1)^{1/3-\\varepsilon_0})$ strictly separable <i>k<\/i>-subsets for $1\\le k\\le n/2$, with an absolute $\\varepsilon_0\\gt 0$. The constants and positive exponents are nonquantitative.","subject":"Combinatorics","lean":1,"applied":2,"difficulty":4,"year":1971,"note":"The number of k-sets bounds the complexity of levels in arrangements, which geometric algorithms use.","papers":[{"title":"A power saving for planar halving lines","path":"preprints/A-power-saving-for-planar-halving-lines-September-25-2026/main.pdf"}]},{"id":"184","title":"Correspondence coloring with a fixed forbidden subgraph","desc":"Proves the Alon–Krivelevich–Sudakov coloring conjecture in correspondence-coloring form: graphs avoiding any fixed subgraph <i>F<\/i> need $O_F(\\Delta/\\log\\Delta)$ colors when their maximum degree Δ is sufficiently large. Also proves the Ajtai–Erdős–Komlós–Szemerédi independence conjecture: for fixed <i>r<\/i> ≥ 4, every <i>n<\/i>-vertex <i>K<\/i><sub><i>r<\/i><\/sub>-free graph of average degree <i>d<\/i> ≥ 2 has an independent set of size $\\Omega_r(n\\log d/d)$.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":3,"year":1999,"note":"Graph colouring. No route identified.","papers":[{"title":"Correspondence coloring graphs with a forbidden clique","path":"preprints/Correspondence-Coloring-Graphs-with-a-Forbidden-Clique-October-5-2026/correspondence-coloring-forbidden-clique.pdf"},{"title":"A logarithmic independence bound for clique-free graphs","path":"preprints/A-Logarithmic-Independence-Bound-for-Clique-Free-Graphs-September-25-2026/paper.pdf"}]},{"id":"185","title":"Counterexamples to infinite matroid intersection and packing/covering","desc":"Disproves the unrestricted infinite matroid intersection and packing/covering conjectures in ZFC, using two self-dual partitional matroids on a countably infinite ground set. The same examples answer Joó’s partitional-matroid question negatively. They are neither finitary nor cofinitary, so Nash-Williams’ original finitary conjecture remains outside the result.","subject":"Combinatorics","lean":2,"applied":1,"difficulty":3,"year":null,"note":"Infinite matroids. No route identified.","papers":[{"title":"A Counterexample to the Infinite Matroid Packing/Covering Conjecture","path":"preprints/A-Counterexample-to-the-Infinite-Matroid-Packing-Covering-Conjecture-September-24-2026/paper.pdf"}]},{"id":"186","title":"Uniform influence and sharp thresholds for graph and hypergraph properties","desc":"Proves the Friedgut–Kalai threshold-width conjectures for graphs and fixed-uniformity hypergraphs. For fixed $0\\lt \\varepsilon\\lt 1/2$, every nontrivial increasing relabeling-invariant property crosses from probability <i>ε<\/i> to $1-\\varepsilon$ within width $O((\\log n)^{-2})$ for graphs and $O_r((\\log n)^{-r/(r-1)})$ for <i>r<\/i>-uniform hypergraphs, <i>r<\/i> ≥ 3. The hypergraph influence bound also applies to nonmonotone properties.","subject":"Combinatorics","lean":1,"applied":2,"difficulty":3,"year":1996,"note":"Sharpness of phase transitions in random graphs. An indirect link to the analysis of random instances.","papers":[{"title":"A uniform influence bound for hypergraph properties","path":"preprints/A-uniform-influence-bound-for-hypergraph-properties-October-5-2026/hypergraph-influences.pdf"},{"title":"A Sharp Threshold Bound for Monotone Graph Properties","path":"preprints/A-Sharp-Threshold-Bound-for-Monotone-Graph-Properties-September-25-2026/paper.pdf"}]},{"id":"187","title":"Snaky in 21 Maker moves","desc":"Settles the Snaky achievement problem: Maker can force the six-cell Snaky shape within 21 of its own moves on the initially empty infinite square board. Maker moves first, each player claims one free cell per turn, and translations, rotations and reflections count as wins.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Positional games. No route identified.","papers":[{"title":"Snaky in 21 Maker moves","path":"preprints/Snaky-in-21-Maker-moves-September-25-2026/article.pdf"}]},{"id":"188","title":"The sharp terminal leave in random triangle removal","desc":"Starting from the complete graph on <i>n<\/i> vertices, repeatedly delete a uniformly chosen remaining triangle. The terminal edge count is asymptotic to $n^{3/2}/(2\\sqrt2)$, with mean-square convergence after normalization by <i>n<\/i><sup>3/2<\/sup>. This proves the triangle case of the Joos–Kühn sharp-constant conjecture.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":4,"year":null,"note":"Random graph processes. No route identified.","papers":[{"title":"The sharp terminal leave in random triangle removal","path":"preprints/The-Sharp-Terminal-Leave-in-Random-Triangle-Removal-September-25-2026/The-Sharp-Terminal-Leave-in-Random-Triangle-Removal-September-25-2026.pdf"}]},{"id":"189","title":"Cycle–clique Ramsey numbers","desc":"Proves the Erdős–Faudree–Rousseau–Schelp conjecture: $R(C_m,K_n)=(m-1)(n-1)+1$ for every $m\\ge n\\ge3$, except $R(C_3,K_3)=6$. This is the exact threshold forcing a red <i>m<\/i>-cycle or a blue <i>n<\/i>-clique in every red–blue coloring of a complete graph.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":4,"year":1978,"note":"Ramsey theory. No route identified.","papers":[{"title":"Cycle--clique Ramsey numbers","path":"preprints/Cycle-clique-Ramsey-numbers-September-25-2026/Cycle-clique-Ramsey-numbers-September-25-2026.pdf"}]},{"id":"190","title":"Polynomial removal fails for ordered binary matrices","desc":"Disproves polynomial ordered binary matrix removal with one fixed $66\\times66$ zero–one pattern. Matrices can require many binary-entry changes to become pattern-free while their copy density is smaller than every proposed polynomial bound in that distance. Copies preserve row and column orders and match both zeros and ones.","subject":"Combinatorics","lean":2,"applied":2,"difficulty":2,"year":null,"note":"A limit on the sample complexity of testing ordered matrices for a forbidden pattern.","papers":[{"title":"Polynomial removal fails for ordered binary matrices","path":"preprints/Polynomial-removal-fails-for-ordered-binary-matrices-September-25-2026/paper.pdf"}]},{"id":"191","title":"A power improvement in the Heilbronn triangle lower bound","desc":"For every sufficiently large <i>n<\/i>, constructs <i>n<\/i> points in the unit square such that every triangle has area at least $n^{-2+c}$ for one absolute <i>c<\/i> &gt; 0. This disproves the conjectured almost-<i>n<\/i><sup>−2<\/sup> upper bound in Heilbronn&#x27;s triangle problem, which asks how large the smallest determined triangle can be.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":4,"year":null,"note":"Combinatorial geometry. A weak link to point sets for numerical integration.","papers":[{"title":"A power improvement in the Heilbronn triangle lower bound","path":"preprints/A-power-improvement-in-the-Heilbronn-triangle-lower-bound-September-25-2026/main.pdf"}]},{"id":"192","title":"Boolean functions violate the square-root degree bound by arbitrary factors","desc":"Disproves the proposed square-root bound relating a Boolean function&#x27;s linear Fourier coefficients to its polynomial degree. For every <i>C<\/i> &gt; 0, there is a sign-valued Boolean function <i>f<\/i> with $\\sum_i\\widehat f(\\{i\\})\\gt C\\sqrt{\\deg(f)}$. Thus its total signed correlation with individual input bits can exceed the proposed bound by an arbitrary factor.","subject":"Combinatorics","lean":1,"applied":1,"difficulty":2,"year":null,"note":"Analysis of Boolean functions. No route identified.","papers":[{"title":"Unbounded Violations of the Square-Root Degree Bound","path":"preprints/Unbounded-Violations-of-the-Square-Root-Degree-Bound-September-26-2026/Unbounded-Violations-of-the-Square-Root-Degree-Bound-September-26-2026.pdf"}]},{"id":"193","title":"Serre’s intersection-multiplicity conjecture","desc":"Proves strict positivity of Serre&#x27;s intersection multiplicity $\\chi^R(M,N)$ for nonzero finitely generated modules over any regular local ring, provided $M\\otimes_R N$ has finite length and $\\dim M+\\dim N=\\dim R$. This resolves the positivity conjecture, including ramified mixed characteristic.","subject":"Algebra","lean":0,"applied":1,"difficulty":5,"year":1957,"note":"Commutative algebra. No route identified.","papers":[{"title":"Positivity of Serre&#x27;s Intersection Multiplicity","path":"preprints/Positivity-of-Serres-Intersection-Multiplicity-September-23-2026/paper.pdf"}]},{"id":"194","title":"Lech’s multiplicity conjecture","desc":"Proves $e(R)\\le e(S)$ for every flat local homomorphism of nonzero Noetherian local rings, where <i>e<\/i> is Hilbert–Samuel multiplicity. This resolves Lech&#x27;s conjecture in every dimension and characteristic.","subject":"Algebra","lean":1,"applied":1,"difficulty":5,"year":1960,"note":"Commutative algebra. No route identified.","papers":[{"title":"Lech&#x27;s multiplicity conjecture","path":"preprints/Lechs-multiplicity-conjecture-September-23-2026/paper.pdf"}]},{"id":"195","title":"A counterexample to the small Cohen–Macaulay module conjecture","desc":"Constructs a three-dimensional complete Noetherian normal local domain over ℂ with no nonzero finitely generated maximal Cohen–Macaulay module. A three-dimensional local domain essentially of finite type over ℂ has the same property, disproving the domain form of the small Cohen–Macaulay module conjecture.","subject":"Algebra","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Commutative algebra. No route identified.","papers":[{"title":"A Complete Local Domain without a Small Cohen–Macaulay Module","path":"preprints/A-Complete-Local-Domain-Without-a-Small-Cohen-Macaulay-Module-September-23-2026/paper.pdf"}]},{"id":"196","title":"A counterexample to Kaplansky’s zero-divisor conjecture","desc":"Constructs a finitely presented torsion-free group <i>G<\/i> whose group algebra $\\mathbb F_2[G]$ has nonzero zero divisors, disproving Kaplansky&#x27;s zero-divisor conjecture. The group has a finite two-dimensional classifying space.","subject":"Algebra","lean":2,"applied":1,"difficulty":5,"year":null,"note":"Group rings. No route identified.","papers":[{"title":"A Torsion-Free Group Algebra with Zero Divisors","path":"preprints/A-Torsion-Free-Group-Algebra-with-Zero-Divisors-September-23-2026/paper.pdf"}]},{"id":"197","title":"A torsion-free group algebra that is not directly finite","desc":"Constructs a finitely presented torsion-free nonsofic group whose group algebra over 𝔽<sub>2<\/sub> is not directly finite, disproving Kaplansky&#x27;s conjecture even without torsion. Companion examples give injective nonsurjective cellular automata on all configurations, refuting Gottschalk&#x27;s surjunctivity conjecture. Another counterexample is an integral group-ring matrix, invertible over the rational group ring, with Fuglede–Kadison determinant strictly between zero and one, disproving the unrestricted Determinant Conjecture.","subject":"Algebra","lean":2,"applied":1,"difficulty":5,"year":1969,"note":"Group rings. No route identified.","papers":[{"title":"A Torsion-Free Group Algebra That Is Not Directly Finite","path":"preprints/A-Torsion-Free-Group-Algebra-That-Is-Not-Directly-Finite-October-4-2026/direct-finiteness.pdf"},{"title":"A Counterexample to Kaplansky&#x27;s Direct-Finiteness Conjecture in Characteristic Two","path":"preprints/A-Counterexample-to-Kaplanskys-Direct-Finiteness-Conjecture-in-Characteristic-Two-September-23-2026/paper.pdf"},{"title":"A Counterexample to the Group-Ring Determinant Conjecture","path":"preprints/A-Counterexample-to-the-Group-Ring-Determinant-Conjecture-September-23-2026/paper.pdf"},{"title":"A Counterexample to Kaplansky&#x27;s Direct-Finiteness Conjecture in Odd Characteristic","path":"preprints/A-Counterexample-to-Kaplanskys-Direct-Finiteness-Conjecture-in-Odd-Characteristic-September-26-2026/paper.pdf"}]},{"id":"198","title":"A counterexample to finitistic-dimension finiteness","desc":"Constructs a finite-dimensional complex algebra whose finite-dimensional modules have unbounded finite projective dimensions. This disproves the little finitistic-dimension conjecture.","subject":"Algebra","lean":2,"applied":1,"difficulty":5,"year":1960,"note":"Representation theory of algebras. No route identified.","papers":[{"title":"An algebra of infinite little finitistic dimension","path":"preprints/An-algebra-of-infinite-little-finitistic-dimension-September-23-2026/paper.pdf"}]},{"id":"199","title":"Counterexamples to Auslander–Reiten, Tachikawa and related homological conjectures","desc":"Constructs finite-dimensional algebras over a characteristic-two rational-function field that disprove the Auslander–Reiten and Gorenstein-projective conjectures, and Tachikawa&#x27;s second conjecture. An associated endomorphism algebra also disproves the classical, generalized and strong Nakayama conjectures, the Auslander–Gorenstein conjecture, and the Wakamatsu tilting conjecture. The counterexamples persist under every extension of the base field.","subject":"Algebra","lean":2,"applied":1,"difficulty":4,"year":1975,"note":"Homological algebra. No route identified.","papers":[{"title":"An explicit counterexample to the Auslander-Reiten conjecture","path":"preprints/An-explicit-counterexample-to-the-Auslander-Reiten-conjecture-September-23-2026/paper.pdf"},{"title":"A counterexample to Tachikawa&#x27;s second conjecture","path":"preprints/A-counterexample-to-Tachikawas-second-conjecture-September-23-2026/paper.pdf"}]},{"id":"200","title":"Eisenbud–Green–Harris and lex-plus-powers","desc":"Proves the Eisenbud–Green–Harris and lex-plus-powers conjectures over every characteristic-zero field. Any homogeneous ideal containing a regular sequence, of arbitrary length and degrees at least two, admits a lex-plus-powers ideal with the same Hilbert function and no smaller graded Betti numbers.","subject":"Algebra","lean":0,"applied":1,"difficulty":4,"year":1993,"note":"Hilbert functions of ideals. A weak link to bounds in computational algebra.","papers":[{"title":"The Artinian Lex-Plus-Powers Betti Theorem","path":"preprints/The-Artinian-Lex-Plus-Powers-Betti-Theorem-September-23-2026/paper.pdf"},{"title":"Commuting Division-Coefficient Forms and the Artinian Eisenbud--Green--Harris Conjecture","path":"preprints/Commuting-Division-Coefficient-Forms-and-the-Artinian-Eisenbud-Green-Harris-Conjecture-September-23-2026/paper.pdf"}]},{"id":"201","title":"A counterexample to Kurosh’s division-ring problem","desc":"Constructs a countable characteristic-zero division ring that is algebraic over its center and generated by two elements over that center, but has infinite dimension over it. This answers Kurosh&#x27;s division-ring problem on local finiteness negatively.","subject":"Algebra","lean":0,"applied":1,"difficulty":5,"year":1941,"note":"Division rings. No route identified.","papers":[{"title":"A Counterexample to Kurosh’s Division-Ring Problem","path":"preprints/A-Counterexample-to-Kuroshs-Division-Ring-Problem-September-23-2026/paper.pdf"}]},{"id":"202","title":"The blockwise Alperin weight conjecture","desc":"Proves the numerical blockwise Alperin weight conjecture for every prime and every finite group: the number of irreducible Brauer characters in a block equals the number of conjugacy classes of its weights.","subject":"Algebra","lean":0,"applied":1,"difficulty":5,"year":1987,"note":"Modular representation theory. No route identified.","papers":[{"title":"The Blockwise Alperin Weight Conjecture","path":"preprints/The-Blockwise-Alperin-Weight-Conjecture-September-23-2026/paper.pdf"}]},{"id":"203","title":"Donovan&#x27;s conjecture over fields and complete mixed-characteristic DVRs","desc":"Proves Donovan&#x27;s conjecture: over each fixed algebraically closed field of characteristic <i>p<\/i>, blocks of finite groups with bounded defect-group order have only finitely many Morita-equivalence classes, for every prime <i>p<\/i>. Also proves the integral form over each fixed complete mixed-characteristic discrete valuation ring with algebraically closed residue field.","subject":"Algebra","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Modular representation theory. No route identified.","papers":[{"title":"Donovan&#x27;s Conjecture over Algebraically Closed Fields","path":"preprints/Donovans-Conjecture-over-Algebraic-Closures-of-Prime-Fields-September-24-2026/main.pdf"},{"title":"Integral Donovan Finiteness over Witt Vectors","path":"preprints/Integral-Donovan-Finiteness-over-Witt-Vectors-September-25-2026/main.pdf"}]},{"id":"204","title":"Tensor saturation for even spin groups","desc":"Proves saturation factor one for $\\mathop{\\mathrm{Spin}}\\nolimits (2n)$, <i>n<\/i> ≥ 2: for three dominant integral weights whose sum lies in the root lattice, an invariant at any common positive integral dilation already gives an invariant at the original weights. This resolves the type-<i>D<\/i> part of the simply-laced saturation conjecture.","subject":"Algebra","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Tensor product multiplicities. No route identified.","papers":[{"title":"Tensor saturation for even spin groups","path":"preprints/Tensor-Saturation-for-Even-Spin-Groups-September-24-2026/Tensor-Saturation-for-Even-Spin-Groups-September-24-2026.pdf"}]},{"id":"205","title":"Saxl’s conjecture and universal tensor squares","desc":"Proves Saxl&#x27;s conjecture: the tensor square of every staircase representation contains every irreducible complex representation of the corresponding symmetric group. More generally, every <i>S<\/i><sub><i>n<\/i><\/sub> with $n\\notin\\{2,4,9\\}$ has an irreducible representation whose tensor square contains all irreducibles.","subject":"Algebra","lean":2,"applied":1,"difficulty":3,"year":2012,"note":"Representations of symmetric groups. No route identified.","papers":[{"title":"Universal Tensor Squares for Symmetric Groups","path":"preprints/Universal-Tensor-Squares-for-Symmetric-Groups-September-24-2026/main.pdf"},{"title":"A Cyclic Polytabloid Proof of Saxl&#x27;s Conjecture","path":"preprints/A-Cyclic-Polytabloid-Proof-of-Saxls-Conjecture-September-24-2026/paper.pdf"}]},{"id":"206","title":"Finite lattice representation and undecidability","desc":"Some finite lattices are not congruence lattices of any finite algebra, answering the finite lattice representation problem negatively. Moreover, no algorithm decides whether a finite lattice has such a representation, or whether it is a full subgroup interval of a finite group.","subject":"Algebra","lean":1,"applied":1,"difficulty":5,"year":1963,"note":"Universal algebra. No route identified.","papers":[{"title":"Finite congruence lattices: characterization and undecidability","path":"preprints/Finite-Congruence-Lattices-Characterization-and-Undecidability-September-24-2026/paper.pdf"},{"title":"A negative solution to the finite lattice representation problem","path":"preprints/A-Negative-Solution-to-the-Finite-Lattice-Representation-Problem-September-24-2026/paper.pdf"}]},{"id":"207","title":"The ℓ¹-Bass conjecture for all discrete groups","desc":"Proves the <i>ℓ<\/i><sup>1<\/sup>-Bass conjecture for every discrete group: Hattori–Stallings traces of idempotent matrices over $\\ell^1(G)$ are supported on finitely many finite-order conjugacy classes. The algebraic companion proves the integral Bass trace conjecture and Kaplansky&#x27;s idempotent conjecture for torsion-free groups over every commutative unital characteristic-zero domain.","subject":"Algebra","lean":2,"applied":1,"difficulty":4,"year":1976,"note":"K-theory of group algebras. No route identified.","papers":[{"title":"The ℓ¹-Bass Conjecture for Discrete Groups","path":"preprints/The-l1-Bass-Conjecture-for-Discrete-Groups-October-5-2026/l1-bass-conjecture.pdf"},{"title":"The Bass trace conjecture and the characteristic-zero Kaplansky idempotent conjecture","path":"preprints/The-Bass-trace-conjecture-for-complex-group-rings-September-24-2026/The-Bass-trace-conjecture-for-complex-group-rings-September-24-2026.pdf"}]},{"id":"208","title":"Finite symmetric tensor categories and the Verlinde tower","desc":"Proves that every finite symmetric tensor category over an algebraically closed field <i>k<\/i> of characteristic <i>p<\/i> &gt; 0 admits a <i>k<\/i>-linear exact faithful strong symmetric monoidal fiber functor to a higher Verlinde category $\\mathrm{Ver}_{p^n}$. The level may depend on the category, and the theorem includes characteristic two, resolving the finite case of the Benson–Etingof–Ostrik conjecture.","subject":"Algebra","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Tensor categories. No route identified.","papers":[{"title":"Fiber functors for finite symmetric tensor categories in positive characteristic","path":"preprints/Fiber-functors-for-finite-symmetric-tensor-categories-in-positive-characteristic-September-24-2026/paper.pdf"}]},{"id":"209","title":"Integral counterexamples to Gersten’s conjecture","desc":"Disproves unrestricted integral Gersten injectivity in degrees 3 and 5. Two explicit two-dimensional ramified regular local rings of mixed characteristic $(0,5)$ have nonzero integral <i>K<\/i>-theory classes that vanish over their fraction fields.","subject":"Algebra","lean":0,"applied":1,"difficulty":4,"year":1973,"note":"Algebraic K-theory. No route identified.","papers":[{"title":"An integral counterexample to Gersten&#x27;s conjecture","path":"preprints/An-Integral-Counterexample-to-Gerstens-Conjecture-September-25-2026/An-Integral-Counterexample-to-Gerstens-Conjecture-September-25-2026.pdf"},{"title":"An integral degree-three Gersten counterexample","path":"preprints/An-Integral-Degree-Three-Gersten-Counterexample-September-26-2026/paper.pdf"}]},{"id":"210","title":"Foulkes&#x27; conjecture for sixth powers and quadratic stabilization","desc":"Proves the sixth case of Foulkes’ conjecture: $\\mathop{\\mathrm{Sym}}\\nolimits ^6(\\mathop{\\mathrm{Sym}}\\nolimits ^bV)$ embeds equivariantly in $\\mathop{\\mathrm{Sym}}\\nolimits ^b(\\mathop{\\mathrm{Sym}}\\nolimits ^6V)$ for every <i>b<\/i> ≥ 6 and finite-dimensional complex <i>V<\/i>. More generally, the canonical multiplication map $\\mathop{\\mathrm{Sym}}\\nolimits ^b(\\mathop{\\mathrm{Sym}}\\nolimits ^aV)\\to\\mathop{\\mathrm{Sym}}\\nolimits ^a(\\mathop{\\mathrm{Sym}}\\nolimits ^bV)$ is surjective for <i>a<\/i> ≥ 2 and $b\\ge a(a-1)$, giving dimension-independent quadratic stabilization.","subject":"Algebra","lean":2,"applied":1,"difficulty":3,"year":1950,"note":"Plethysm coefficients. A weak link to geometric complexity theory.","papers":[{"title":"Foulkes&#x27; conjecture for the sixth symmetric power","path":"preprints/Foulkes-Conjecture-for-the-Sixth-Symmetric-Power-September-25-2026/main.pdf"},{"title":"Quadratic stabilization of the canonical Foulkes--Howe map","path":"preprints/Quadratic-Stabilization-of-the-Canonical-Foulkes-Howe-Map-September-25-2026/paper.pdf"}]},{"id":"211","title":"The geometric phase diagram, diffusion, and spectra of random planar maps","desc":"Critical Fortuin–Kasteleyn planar maps converge to Liouville quantum gravity spheres for $0\\lt q\\le4$ and to the Brownian continuum random tree for <i>q<\/i> &gt; 4, establishing the surface-to-tree geometric transition. For FK–Ising and spanning-tree-weighted maps, stationary random walks converge to Liouville Brownian motion on the limiting sphere. The FK–Ising spectral result also gives convergence of eigenvalues and heat traces, using the stated Brownian/LQG inputs.","subject":"Probability and statistical mechanics","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Random planar maps. No route identified.","papers":[{"title":"Random Walks on Critical FK–Ising Maps and Liouville Brownian Motion","path":"preprints/Random-Walks-on-Critical-FK-Ising-Maps-and-Liouville-Brownian-Motion-October-5-2026/fk-ising-walk-limit.pdf"},{"title":"Spectral convergence for critical FK–Ising planar maps","path":"preprints/Spectral-convergence-for-critical-FK-Ising-planar-maps-October-5-2026/spectral-convergence-critical-fk-ising-planar-maps.pdf"},{"title":"A Linear Clock for Random Walk on Tree-Weighted Planar Maps","path":"preprints/A-Linear-Clock-for-Random-Walk-on-Tree-Weighted-Planar-Maps-October-5-2026/linear-clock-random-walk-tree-weighted-planar-maps.pdf"},{"title":"Canonical conformal limits of subcritical FK planar maps","path":"preprints/Canonical-conformal-limits-of-subcritical-FK-planar-maps-September-24-2026/main.pdf"},{"title":"The critical Liouville quantum sphere and geometric limits of FK maps at q=4","path":"preprints/The-critical-Liouville-quantum-sphere-and-geometric-limits-of-FK-maps-at-q-equals-4-September-24-2026/main.pdf"},{"title":"Metric-measure limits of subcritical FK and spanning-tree planar maps","path":"preprints/Metric-measure-limits-of-subcritical-FK-and-spanning-tree-planar-maps-September-24-2026/main.pdf"},{"title":"Brownian continuum random tree limits of finite Fortuin–Kasteleyn maps above four","path":"preprints/Brownian-continuum-random-tree-limits-of-finite-Fortuin-Kasteleyn-maps-above-four-September-24-2026/main.pdf"}]},{"id":"212","title":"Planar first-passage geometry and the absence of bigeodesics","desc":"Proves that planar first-passage percolation has no doubly infinite geodesic for iid nonnegative nonatomic edge weights when the minimum of four weights has finite second moment. For exponential weights, the limit shape is strictly convex with <i>C<\/i><sup>1<\/sup> boundary. Differentiability also holds for every Gamma law with positive shape and rate.","subject":"Probability and statistical mechanics","lean":2,"applied":1,"difficulty":4,"year":null,"note":"First-passage percolation models growth and shortest paths in random media. The result is structural.","papers":[{"title":"No bigeodesics in planar first-passage percolation","path":"preprints/No-bigeodesics-in-planar-first-passage-percolation-September-24-2026/main.pdf"},{"title":"Strict convexity and differentiability of the planar exponential first-passage limit shape","path":"preprints/Strict-convexity-and-differentiability-of-the-planar-exponential-first-passage-limit-shape-September-24-2026/main.pdf"}]},{"id":"213","title":"Critical percolation on every quasi-transitive graph","desc":"Resolves the Benjamini–Schramm criticality conjecture for bond percolation on every infinite connected locally finite quasi-transitive graph with $p_c\\lt 1$: at the critical probability, there is almost surely no infinite cluster. The family also establishes this conclusion for both nearest-neighbor bond and site percolation on ℤ<sup>3<\/sup>.","subject":"Probability and statistical mechanics","lean":2,"applied":2,"difficulty":5,"year":1996,"note":"Continuity of the percolation transition, including the cubic lattice. Physical modelling assumes it.","papers":[{"title":"Critical bond and site percolation on the cubic lattice","path":"preprints/Critical-bond-and-site-percolation-on-the-cubic-lattice-September-24-2026/paper.pdf"},{"title":"No percolation at criticality on quasi-transitive graphs","path":"preprints/No-percolation-at-criticality-on-quasi-transitive-graphs-September-24-2026/paper.pdf"}]},{"id":"214","title":"The Benjamini–Schramm nonuniqueness conjecture","desc":"Proves $p_c\\lt p_u$ for Bernoulli bond percolation on every infinite connected locally finite nonamenable quasi-transitive graph, resolving the Benjamini–Schramm nonuniqueness conjecture. Thus there is a nonempty range of probabilities with infinitely many infinite clusters. A stronger operator bound also establishes the critical triangle condition.","subject":"Probability and statistical mechanics","lean":1,"applied":1,"difficulty":4,"year":1996,"note":"Percolation on nonamenable graphs. No route identified.","papers":[{"title":"Nonuniqueness of percolation on nonamenable quasi-transitive graphs","path":"preprints/Nonuniqueness-of-percolation-on-nonamenable-quasi-transitive-graphs-September-24-2026/paper.pdf"}]},{"id":"215","title":"Canonical $O(3)$ continuum limit and exact $O(4)$ mass asymptotics","desc":"Constructs the canonical continuum limit of the two-dimensional nearest-neighbor $O(3)$ model: a non-Gaussian local relativistic theory with a unique vacuum and a positive mass gap. For the square-lattice $O(4)$ model, determines the exact leading asymptotic of the full transfer gap, $m_{\\mathrm{lat}}(\\beta)\\sim32e^{\\pi/4-1/2}\\sqrt\\beta\\,e^{-\\pi\\beta}$. The family also proves exponential spin-correlation decay for two-dimensional nearest-neighbor $O(n)$ models with <i>n<\/i> ≥ 3 at every positive temperature.","subject":"Probability and statistical mechanics","lean":2,"applied":2,"difficulty":5,"year":1975,"note":"Constructs a two-dimensional field theory with a mass gap. Mathematical physics; no computational consequence.","papers":[{"title":"The canonical massive continuum limit of the two-dimensional O(3) model","path":"preprints/The-canonical-massive-continuum-limit-of-the-two-dimensional-O3-model-October-4-2026/massive-continuum-o3.pdf"},{"title":"An Isolated Particle Pole for the Two-Dimensional O(3) Spin Field","path":"preprints/An-Isolated-Particle-Pole-for-the-Two-Dimensional-O3-Spin-Field-October-4-2026/o3-particle-pole.pdf"},{"title":"Exact mass asymptotics for the two-dimensional O(4) lattice model","path":"preprints/Exact-mass-asymptotics-for-the-two-dimensional-O4-lattice-model-October-5-2026/exact-mass-o4.pdf"},{"title":"Sharp mass bounds for the two-dimensional O(4) model","path":"preprints/Sharp-mass-bounds-for-the-two-dimensional-O4-model-September-23-2026/paper.pdf"},{"title":"Exponential decay in two-dimensional classical O(n) models","path":"preprints/Exponential-decay-in-two-dimensional-classical-On-models-September-23-2026/paper.pdf"}]},{"id":"216","title":"Critical and near-critical XY scaling and BKT universality","desc":"For the square-lattice nearest-neighbor cosine XY model, proves critical axis correlations $C_{\\beta_c}(r)\\sim Ar^{-1/4}(\\log r)^{1/8}$ and the Berezinskii–Kosterlitz–Thouless essential singularity $\\sqrt{\\beta_c-\\beta}\\log\\xi(\\beta)\\to B$, with $A,B\\gt 0$ after the free-box thermodynamic limit. For finite square-symmetric interactions containing nearest neighbors, discrete Gaussian heights converge to Gaussian fields throughout the rough phase, including its threshold, along geometric torus sizes. Critical center-magnetization and spin-field conclusions retain their stated height, renormalization, and field-input assumptions.","subject":"Probability and statistical mechanics","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Critical behaviour of the XY model. No route identified.","papers":[{"title":"The critical logarithmic correction for the planar XY model","path":"preprints/The-critical-logarithmic-correction-for-the-planar-XY-model-October-5-2026/paper.pdf"},{"title":"Critical Center Magnetization in the Planar XY Model","path":"preprints/Critical-Center-Magnetization-in-the-Planar-XY-Model-October-5-2026/paper.pdf"},{"title":"The Critical Spin Field of the Planar XY Model","path":"preprints/The-Critical-Spin-Field-of-the-Planar-XY-Model-October-5-2026/paper.pdf"},{"title":"Essential Singularity of the Correlation Length in the Planar XY Model","path":"preprints/Essential-Singularity-of-the-Correlation-Length-in-the-Planar-XY-Model-October-5-2026/paper.pdf"},{"title":"The critical correlation exponent of the planar XY model","path":"preprints/The-critical-correlation-exponent-of-the-planar-XY-model-September-24-2026/paper.pdf"},{"title":"BKT universality for height and planar spin fields","path":"preprints/BKT-universality-for-height-and-planar-spin-fields-September-24-2026/paper.pdf"}]},{"id":"217","title":"The low-temperature Sherrington–Kirkpatrick fluctuation law","desc":"For every fixed inverse temperature <i>β<\/i> &gt; 1, determines the fluctuation scale and limiting law of the zero-field Gaussian Sherrington–Kirkpatrick log partition function. Its variance is asymptotic to $c_\\beta n^{1/3}$, with $c_\\beta\\gt 0$, confirming the predicted <i>n<\/i><sup>1/6<\/sup> standard-deviation scale. Exact centering and standardization give full-sequence convergence to a uniquely characterized nondegenerate law.","subject":"Probability and statistical mechanics","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Spin glass fluctuations. No route identified.","papers":[{"title":"The low-temperature Sherrington–Kirkpatrick free-energy limiting law","path":"preprints/The-low-temperature-Sherrington-Kirkpatrick-free-energy-limiting-law-September-24-2026/The-low-temperature-Sherrington-Kirkpatrick-free-energy-limiting-law-September-24-2026.pdf"},{"title":"The low-temperature Sherrington–Kirkpatrick fluctuation scale","path":"preprints/The-low-temperature-Sherrington-Kirkpatrick-fluctuation-scale-September-24-2026/The-low-temperature-Sherrington-Kirkpatrick-fluctuation-scale-September-24-2026.pdf"}]},{"id":"218","title":"Conformal universality for weakly interacting and random-bond Ising models","desc":"Weak finite-range square-symmetric even multispin perturbations of the square-lattice Ising model preserve critical bulk spin and energy limits; weak square-symmetric contour interactions also yield chordal SLE<sub>3<\/sub> interface limits. With sufficiently weak iid bond disorder of any fixed bounded nondegenerate mean-zero law, critical spin interfaces converge to the same law in probability over environments.","subject":"Probability and statistical mechanics","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Universality for Ising models. No route identified.","papers":[{"title":"Quenched SLE₃ limits for general weak random-bond Ising models","path":"preprints/Quenched-SLE3-limits-for-general-weak-random-bond-Ising-models-October-5-2026/general-weak-random-bond-ising.pdf"},{"title":"Quenched SLE₃ Universality for the Weak Random-Bond Ising Model","path":"preprints/Quenched-SLE3-Universality-for-the-Weak-Random-Bond-Ising-Model-October-5-2026/quenched-sle3-weak-random-bond-ising.pdf"},{"title":"Logarithmic Relative Fluctuations in the Weakly Disordered Planar Ising Model","path":"preprints/Logarithmic-Relative-Fluctuations-in-the-Weakly-Disordered-Planar-Ising-Model-October-5-2026/critical-relative-second-moment-weak-random-bond-ising.pdf"},{"title":"Conformal universality of bulk Ising correlations under weak interactions","path":"preprints/Conformal-universality-of-bulk-Ising-correlations-under-weak-interactions-September-23-2026/paper.pdf"},{"title":"SLE3 universality for weak finite-range Ising interactions","path":"preprints/SLE3-universality-for-weak-finite-range-Ising-interactions-September-23-2026/paper.pdf"},{"title":"Buffered comparison and stopping-band resolution in critical Ising","path":"preprints/Buffered-comparison-and-stopping-band-resolution-in-critical-Ising-September-23-2026/paper.pdf"}]},{"id":"219","title":"GOE bulk universality for regular graphs with weak Anderson disorder","desc":"For every fixed degree <i>d<\/i> ≥ 3, the bulk adjacency-eigenvalue point process of a uniform simple random <i>d<\/i>-regular graph converges to the Gaussian orthogonal ensemble law, including for cubic graphs. The same fixed-energy universality persists under sufficiently weak fixed iid uniform diagonal disorder, throughout compact bands strictly inside the clean spectral edges.","subject":"Probability and statistical mechanics","lean":0,"applied":2,"difficulty":4,"year":null,"note":"Eigenvalue statistics of sparse random graphs, which spectral methods for networks rely on.","papers":[{"title":"Fixed-energy universality for weak Anderson disorder on random regular graphs","path":"preprints/Fixed-energy-universality-for-weak-Anderson-disorder-on-random-regular-graphs-October-5-2026/fixed-energy-universality-weak-anderson-disorder-random-regular-graphs.pdf"},{"title":"GOE bulk universality for fixed-degree random regular graphs","path":"preprints/GOE-bulk-universality-for-fixed-degree-random-regular-graphs-September-23-2026/paper.pdf"}]},{"id":"220","title":"Directional zero–one laws beyond iid environments and iid ballisticity","desc":"On ℤ<sup><i>d<\/i><\/sup>, <i>d<\/i> ≥ 3, directional escape has probability zero or one for iid strictly elliptic nearest-neighbor environments, and for stationary ergodic finite-range-dependent environments under uniform ellipticity. In iid uniformly elliptic environments with <i>d<\/i> ≥ 2, almost-sure directional transience implies a deterministic limiting velocity with positive projection in that direction, resolving the ballisticity conjecture.","subject":"Probability and statistical mechanics","lean":2,"applied":1,"difficulty":4,"year":1981,"note":"Random walks in random environments. No route identified.","papers":[{"title":"A directional zero–one law for finite-range-dependent random environments","path":"preprints/A-directional-zero-one-law-for-finite-range-dependent-random-environments-October-5-2026/directional-zero-one-finite-range.pdf"},{"title":"A directional zero–one law under strict ellipticity","path":"preprints/A-directional-zero-one-law-under-strict-ellipticity-September-23-2026/paper.pdf"},{"title":"Directional transience implies ballisticity","path":"preprints/Directional-transience-implies-ballisticity-September-23-2026/paper.pdf"}]},{"id":"221","title":"The Mézard–Parisi formula for diluted spin glasses","desc":"Proves the Mézard–Parisi hierarchical cavity formula for Poisson-diluted even-arity Ising models satisfying the Panchenko–Talagrand factorization and positivity assumptions, with only first-moment integrability. The limiting free energy equals the infimum over finite-depth hierarchical trial laws. This includes the Viana–Bray model, symmetric diluted even-spin models, and weighted soft even-<i>K<\/i> satisfiability.","subject":"Probability and statistical mechanics","lean":1,"applied":3,"difficulty":4,"year":2001,"note":"Diluted spin glass formulas are the source of predicted thresholds for random constraint satisfaction and of performance predictions for sparse-graph codes.","papers":[{"title":"The Mézard–Parisi formula for diluted spin glasses","path":"preprints/The-Mezard-Parisi-formula-for-diluted-spin-glasses-September-23-2026/paper.pdf"}]},{"id":"222","title":"Perceptron free energies and microscopic jamming exponents","desc":"Determines finite-temperature variational free energies for Gaussian Ising perceptrons with bounded Borel log-potentials and Gaussian spherical perceptrons with bounded continuous potentials, at every positive pattern density. A spherical extension treats bi-orthogonally invariant disorder with compact limiting singular-value distributions and no outliers. At margin −1, the quadratic-penalty spherical model has a sharp feasibility threshold and limiting gap and force laws, with system size, zero temperature, and critical density taken in that order.","subject":"Probability and statistical mechanics","lean":1,"applied":3,"difficulty":3,"year":1988,"note":"Perceptron capacity is the storage problem for a single-layer network. The jamming exponents concern the same constraint satisfaction transition.","papers":[{"title":"The free energy of the Ising random perceptron","path":"preprints/The-free-energy-of-the-Ising-random-perceptron-September-24-2026/The-free-energy-of-the-Ising-random-perceptron-September-24-2026.pdf"},{"title":"Microscopic jamming in the negative spherical perceptron","path":"preprints/Microscopic-jamming-in-the-negative-spherical-perceptron-September-24-2026/Microscopic-jamming-in-the-negative-spherical-perceptron-September-24-2026.pdf"},{"title":"The spherical perceptron with bi-orthogonally invariant disorder","path":"preprints/The-spherical-perceptron-with-bi-orthogonally-invariant-disorder-September-24-2026/The-spherical-perceptron-with-bi-orthogonally-invariant-disorder-September-24-2026.pdf"},{"title":"The free energy of the spherical random perceptron","path":"preprints/The-free-energy-of-the-spherical-random-perceptron-September-24-2026/The-free-energy-of-the-spherical-random-perceptron-September-24-2026.pdf"}]},{"id":"223","title":"Random-cluster interfaces: critical, disordered, thermal, and natural-time scaling","desc":"Proves chordal SLE<sub><i>κ<\/i><\/sub> limits for critical square-lattice random-cluster interfaces for $0\\lt q\\le4$, with $\\kappa=4\\pi/\\arccos(-\\sqrt q/2)$: bounded Jordan domains are allowed for <i>q<\/i> ≥ 1, and smooth Jordan domains for <i>q<\/i> &lt; 1, under the stated marked-boundary approximations. For $1\\le q\\le4$, complete nested plane loops converge to CLE<sub><i>κ<\/i><\/sub>.","subject":"Probability and statistical mechanics","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Scaling limits of lattice interfaces. No route identified.","papers":[{"title":"Square-lattice FK interfaces and nested loops for 1 &lt;= q &lt; 4","path":"preprints/Square-lattice-FK-interfaces-and-nested-loops-for-1-leq-q-lt-4-September-23-2026/paper.pdf"},{"title":"Self-dual random-cluster interfaces below one","path":"preprints/Self-dual-random-cluster-interfaces-below-one-September-23-2026/paper.pdf"},{"title":"Quenched SLE Universality for Weakly Disordered FK–Ising Interfaces","path":"preprints/Quenched-SLE-Universality-for-Weakly-Disordered-FK-Ising-Interfaces-October-5-2026/quenched-fk-ising.pdf"},{"title":"Thermal FK–Ising interfaces and massive SLE","path":"preprints/Thermal-FK-Ising-interfaces-and-massive-SLE-October-5-2026/paper.pdf"},{"title":"Natural Occupation Measures for Critical Square-Lattice FK Interfaces","path":"preprints/Natural-Occupation-Measures-for-Critical-Square-Lattice-FK-Interfaces-October-5-2026/natural-occupation-measures-critical-square-lattice-fk-interfaces.pdf"},{"title":"Conformal Limits of Critical Square-Lattice Random-Cluster Interfaces","path":"preprints/Conformal-Limits-of-Critical-Square-Lattice-Random-Cluster-Interfaces-October-5-2026/paper.pdf"}]},{"id":"224","title":"Critical and quenched near-critical universality for Poisson–Voronoi percolation","desc":"Proves Cardy&#x27;s formula for annealed critical Poisson–Voronoi crossing probabilities in every bounded Jordan quadrilateral. With each model normalized by its own expected unit-square pivotal count, the conditional joint near-critical crossing-threshold laws for rational polygonal quads converge in environment probability to the triangular-lattice reference law. This establishes quenched near-critical universality for crossing thresholds.","subject":"Probability and statistical mechanics","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Percolation scaling limits. No route identified.","papers":[{"title":"From critical crossings to quenched near-critical universality in Voronoi percolation","path":"preprints/From-critical-crossings-to-quenched-near-critical-universality-in-Voronoi-percolation-October-5-2026/critical-crossings-quenched-near-critical-universality-voronoi-percolation.pdf"},{"title":"A Pivotal Amplitude for Voronoi Percolation from Cardy&#x27;s Formula","path":"preprints/A-Pivotal-Amplitude-for-Voronoi-Percolation-from-Cardys-Formula-October-5-2026/voronoi-pivotal-amplitude.pdf"},{"title":"Cardy’s formula for critical Poisson–Voronoi percolation","path":"preprints/Cardys-formula-for-critical-Poisson-Voronoi-percolation-September-23-2026/paper.pdf"}]},{"id":"225","title":"Gaussian free field limits throughout the balanced six-vertex regime","desc":"The balanced square-lattice six-vertex height field with $a=b=1$ and $0\\lt c\\le2$ converges to a Gaussian free field, including at the endpoint <i>c<\/i> = 2. The plane state is defined by balanced-torus limits. For unit height increments and Green kernel $-(2\\pi)^{-1}\\log|x-y|$, the exact variance multiplier is $1/\\arcsin(c/2)$.","subject":"Probability and statistical mechanics","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Six-vertex model. No route identified.","papers":[{"title":"The Gaussian free field limit of the balanced six-vertex model with variance multiplier 1/arcsin(c/2)","path":"preprints/The-Gaussian-free-field-limit-of-the-balanced-six-vertex-model-with-variance-multiplier-1-over-arcsin-c-over-2-September-23-2026/The-Gaussian-free-field-limit-of-the-balanced-six-vertex-model-with-variance-multiplier-1-over-arcsin-c-over-2-September-23-2026.pdf"}]},{"id":"226","title":"The double-dimer loop ensemble converges to CLE<sub>4<\/sub>","desc":"Resolves the half-plane Temperleyan form of the double-dimer scaling-limit conjecture: the complete loop ensemble formed by two independent dimer coverings of the Temperleyan square lattice converges to nested CLE<sub>4<\/sub>. Convergence matches every macroscopic loop as an unparametrized curve, upgrading convergence of loop observables to convergence of the loops themselves.","subject":"Probability and statistical mechanics","lean":0,"applied":1,"difficulty":3,"year":2011,"note":"Dimer models. No route identified.","papers":[{"title":"The curve scaling limit of half-plane double dimers","path":"preprints/The-curve-scaling-limit-of-half-plane-double-dimers-September-23-2026/paper.pdf"}]},{"id":"227","title":"Critical SK autocorrelation processes and dynamics across the temperature transition","desc":"For zero-field Gaussian SK heat-bath dynamics with rate-one updates per spin, proves worst-start cutoff on the $\\log n$ scale for fixed $0\\le\\beta\\lt 1$, mixing time $n^{2/3+o(1)}$ at <i>β<\/i> = 1, and stretched-exponential mixing from a Gibbs-sampled fixed starting configuration for <i>β<\/i> &gt; 1, in probability over disorder. At criticality, rescaled stationary and quench autocorrelation processes have universal random limits for Gaussian and Rademacher disorder; the quench limit relaxes to the stationary limit.","subject":"Probability and statistical mechanics","lean":2,"applied":3,"difficulty":3,"year":null,"note":"Heat-bath dynamics on the Sherrington-Kirkpatrick model is a sampling algorithm. The theorem gives its running time at high, critical and low temperature.","papers":[{"title":"Universality of critical quench autocorrelations in the Sherrington–Kirkpatrick model","path":"preprints/Universality-of-critical-quench-autocorrelations-in-the-Sherrington-Kirkpatrick-model-October-5-2026/main.pdf"},{"title":"Functional universality of critical SK autocorrelations","path":"preprints/Functional-universality-of-critical-SK-autocorrelations-October-5-2026/critical-sk-autocorrelations.pdf"},{"title":"A spectral gap throughout the high-temperature Sherrington–Kirkpatrick phase","path":"preprints/A-spectral-gap-throughout-the-high-temperature-Sherrington-Kirkpatrick-phase-September-24-2026/main.pdf"},{"title":"Cutoff throughout the high-temperature Sherrington–Kirkpatrick phase","path":"preprints/Cutoff-throughout-the-high-temperature-Sherrington-Kirkpatrick-phase-September-24-2026/paper.pdf"},{"title":"Critical slowing down in the Sherrington–Kirkpatrick model","path":"preprints/Critical-slowing-down-in-the-Sherrington-Kirkpatrick-model-September-24-2026/paper.pdf"},{"title":"Stretched-exponential barriers for typical SK initial states","path":"preprints/Stretched-exponential-barriers-for-typical-SK-initial-states-September-24-2026/paper.pdf"},{"title":"A typical-start upper bound for low-temperature SK Glauber dynamics","path":"preprints/A-typical-start-upper-bound-for-low-temperature-SK-Glauber-dynamics-September-24-2026/paper.pdf"},{"title":"Critical mixing in the Sherrington–Kirkpatrick model","path":"preprints/Critical-mixing-in-the-Sherrington-Kirkpatrick-model-September-25-2026/paper.pdf"}]},{"id":"228","title":"Continuum phase transitions for radial pair potentials","desc":"Constructs stable distance-dependent pair interactions for three-dimensional classical particles with a first-order phase transition: the canonical free energy has a derivative jump at one inverse temperature throughout an open density interval. One potential has a divergent repulsive core; another is bounded and continuous with an integrable power-law tail, realizing the type of transition sought in Simon&#x27;s continuum problem.","subject":"Probability and statistical mechanics","lean":2,"applied":2,"difficulty":4,"year":null,"note":"Existence of a first-order phase transition for particles in the continuum. Physical modelling assumes it.","papers":[{"title":"A continuum temperature singularity for a radial pair potential","path":"preprints/A-continuum-temperature-singularity-for-a-radial-pair-potential-September-24-2026/paper.pdf"},{"title":"A radial continuum phase transition with algebraic decay","path":"preprints/A-radial-continuum-phase-transition-with-algebraic-decay-September-24-2026/paper.pdf"}]},{"id":"229","title":"Exact three- and four-state reconstruction thresholds and four-state tree capacity","desc":"Proves the exact reconstruction threshold $d\\lambda^2\\gt 1$, with nonreconstruction at equality, for three-state symmetric and four-state ferromagnetic broadcasting on regular trees (<i>d<\/i> ≥ 2) and observed Poisson trees (mean <i>d<\/i> &gt; 1 and <i>d<\/i> &gt; 0, respectively), with Poisson advantage averaged without conditioning on survival. The three-state theorem allows both signs of <i>λ<\/i> and gives the exact weak-recovery threshold for the symmetric three-community stochastic block model.","subject":"Probability and statistical mechanics","lean":1,"applied":3,"difficulty":3,"year":2001,"note":"Gives the exact threshold below which three communities in a sparse network cannot be detected. Community-detection methods are measured against it.","papers":[{"title":"The Reconstruction Threshold for the Ferromagnetic Four-State Potts Model","path":"preprints/The-Reconstruction-Threshold-for-the-Ferromagnetic-Four-State-Potts-Model-October-5-2026/four-state-potts.pdf"},{"title":"A Capacity Criterion for Four-State Potts Reconstruction on Trees","path":"preprints/A-Capacity-Criterion-for-Four-State-Potts-Reconstruction-on-Trees-October-5-2026/four-state-capacity.pdf"},{"title":"The exact reconstruction threshold for the three-state symmetric channel","path":"preprints/The-exact-reconstruction-threshold-for-the-three-state-symmetric-channel-September-25-2026/paper.pdf"}]},{"id":"230","title":"Exact Hausdorff gauges for SLE","desc":"Resolves Schramm’s Hausdorff-measure question for chordal SLE<sub><i>κ<\/i><\/sub>, $0\\lt \\kappa\\lt 8$. The explicit gauge $r^d(\\log\\log(1/r))^{(2-d)/2}$, $d=1+\\kappa/8$, gives almost surely positive finite measure to every trace segment $\\gamma([s,t])$ with $0\\lt s\\lt t\\lt \\infty$, and finite expected measure to the trace in every bounded disk.","subject":"Probability and statistical mechanics","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Fractal geometry of random curves. No route identified.","papers":[{"title":"An exact Hausdorff gauge for SLE","path":"preprints/An-exact-Hausdorff-gauge-for-SLE-September-25-2026/An-exact-Hausdorff-gauge-for-SLE-September-25-2026.pdf"},{"title":"An explicit exact Hausdorff gauge for SLE","path":"preprints/An-explicit-exact-Hausdorff-gauge-for-SLE-September-26-2026/An-explicit-exact-Hausdorff-gauge-for-SLE-September-26-2026.pdf"}]},{"id":"231","title":"The free uniform spanning forest is a factor of IID","desc":"On every infinite connected locally finite simple unweighted graph, the free uniform spanning forest is a factor of independent vertex labels, by one isomorphism-equivariant rule using no root. Translation-invariant strongly Rayleigh binary processes on every countable group, including invariant determinantal processes with Hermitian positive-contraction kernels, are also factors of IID.","subject":"Probability and statistical mechanics","lean":1,"applied":1,"difficulty":2,"year":null,"note":"Spanning forests as local algorithms. A weak link to distributed computing.","papers":[{"title":"The free uniform spanning forest is a factor of IID","path":"preprints/The-free-uniform-spanning-forest-is-a-factor-of-IID-September-25-2026/The-free-uniform-spanning-forest-is-a-factor-of-IID-September-25-2026.pdf"}]},{"id":"232","title":"Gaussian fields and interfaces for triangular-lattice Lipschitz heights","desc":"Proves Gaussian free field limits on bounded smooth simply connected domains for triangular-lattice height models: uniform odd heights with increments $0,\\pm2$ and two-arc boundary values $\\pm1$, and zero-boundary integer Lipschitz heights weighted by fixed $x\\in[1/\\sqrt2,1]$. Uniform real Lipschitz heights also converge to a Gaussian field; at a tuned opposite-boundary amplitude, their interface converges to chordal SLE<sub>4<\/sub>, establishing Schramm’s real-field/interface predictions.","subject":"Probability and statistical mechanics","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Random height functions. No route identified.","papers":[{"title":"Gaussian free-field limits of weighted integer Lipschitz heights","path":"preprints/Gaussian-free-field-limits-of-weighted-integer-Lipschitz-heights-September-25-2026/paper.pdf"},{"title":"The Gaussian free field limit of integer Lipschitz heights with two-arc boundary data","path":"preprints/The-Gaussian-free-field-limit-of-integer-Lipschitz-heights-with-two-arc-boundary-data-September-25-2026/paper.pdf"},{"title":"Uniform real Lipschitz surfaces on the triangular lattice","path":"preprints/Uniform-real-Lipschitz-surfaces-on-the-triangular-lattice-September-25-2026/paper.pdf"}]},{"id":"233","title":"The joint critical Ashkin–Teller current limit","desc":"Identifies the joint scaling limit of Ashkin–Teller heights and both complete current-cluster collections throughout the critical line, including the four-state Potts endpoint. In bounded Jordan domains with admissible lattice approximations and wired primal/free dual boundaries, the height converges to the predicted Gaussian free field, and the clusters to canonical recursive sets of that same field, retaining every nesting depth.","subject":"Probability and statistical mechanics","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Ashkin-Teller model. No route identified.","papers":[{"title":"The joint scaling limit of critical Ashkin-Teller currents","path":"preprints/The-joint-scaling-limit-of-critical-Ashkin-Teller-currents-September-25-2026/main.pdf"}]},{"id":"234","title":"All-temperature pressure of orthogonally invariant Ising spin glasses","desc":"Gives an exact variational formula for the limiting pressure of orthogonally invariant Ising spin glasses at every fixed temperature, both almost surely and in expectation. The coupling matrix is a Haar-random rotation of a deterministic spectrum converging to a compactly supported law, with extreme eigenvalues converging to its support edges. The zero-field ground-state energy follows as temperature tends to zero.","subject":"Probability and statistical mechanics","lean":1,"applied":3,"difficulty":3,"year":null,"note":"Rotationally invariant couplings are the model behind message-passing algorithms for inference with structured matrices.","papers":[{"title":"All-temperature pressure for orthogonally invariant Ising spin glasses","path":"preprints/All-temperature-pressure-for-orthogonally-invariant-Ising-spin-glasses-September-25-2026/paper.pdf"}]},{"id":"235","title":"Limiting random SAT thresholds, sharp variance and computability","desc":"For random <i>k<\/i>-SAT with independent uniformly signed proper clauses sampled with replacement, proves finite positive limiting thresholds and hitting-time variance $\\Theta_k(n)$ for every fixed <i>k<\/i> ≥ 3, and computability of the 3-SAT threshold. We credit Gaia Carenini with priority for resolving the threshold-existence conjecture in her concurrent <a href=\"https://eccc.weizmann.ac.il/report/2026/229/\">ECCC TR26-229<\/a>, made public October 5, 2026; this family supplies another proof and the sharper variance and computability results.","subject":"Probability and statistical mechanics","lean":1,"applied":3,"difficulty":5,"year":1992,"note":"The satisfiability threshold is the benchmark regime for SAT solvers. The limit exists for every clause length.","papers":[{"title":"A Limiting Satisfiability Threshold for Every Fixed Clause Size","path":"preprints/A-Limiting-Satisfiability-Threshold-for-Every-Fixed-Clause-Size-September-25-2026/article.pdf"},{"title":"Linear Variance of the Random 3-SAT Hitting Time","path":"preprints/Linear-Variance-of-the-Random-3-SAT-Hitting-Time-October-5-2026/linear-variance-of-the-random-3-sat-hitting-time.pdf"},{"title":"Variance of the Random k-SAT Hitting Time","path":"preprints/Variance-of-the-Random-k-SAT-Hitting-Time-September-27-2026/article.pdf"},{"title":"Computing the Random 3-SAT Threshold","path":"preprints/Computing-the-Random-3-SAT-Threshold-September-27-2026/article.pdf"}]},{"id":"236","title":"The exact factor-of-IID threshold for free Ising spins on trees","desc":"Determines when the free zero-field ferromagnetic Ising state on the infinite <i>d<\/i>-regular tree is a factor of independent vertex labels: exactly when $\\tanh\\beta\\le(d-1)^{-1/2}$, including equality, for <i>d<\/i> ≥ 3 and <i>β<\/i> ≥ 0. The construction uses no root and is almost surely equivariant for each fixed tree automorphism, resolving the ferromagnetic case of Lyons&#x27;s question.","subject":"Probability and statistical mechanics","lean":2,"applied":1,"difficulty":2,"year":null,"note":"Ising model on trees. A weak link to local algorithms.","papers":[{"title":"The sharp factor-of-IID threshold for the free Ising model on regular trees","path":"preprints/The-sharp-factor-of-IID-threshold-for-the-free-Ising-model-on-regular-trees-September-26-2026/article.pdf"}]},{"id":"237","title":"The three-quarter exponent for honeycomb self-avoiding walk","desc":"Proves the diameter form of Nienhuis&#x27;s predicted three-quarter exponent: a uniformly chosen <i>n<\/i>-step self-avoiding walk on the honeycomb lattice has diameter $n^{3/4+o(1)}$. Its local mass and covering numbers have exponent 4/3. These estimates hold at every sufficiently large fixed length, simultaneously across scales, with arbitrarily high polynomial probability.","subject":"Probability and statistical mechanics","lean":1,"applied":2,"difficulty":5,"year":1982,"note":"The exponent for the size of a polymer chain in two dimensions, predicted in physics and used in polymer modelling.","papers":[{"title":"Radial transfer estimates and polygon length laws for honeycomb walks","path":"preprints/Radial-transfer-estimates-and-polygon-length-laws-for-honeycomb-walks-September-26-2026/main.pdf"},{"title":"Critical honeycomb chords with prescribed boundary endpoints","path":"preprints/Critical-honeycomb-chords-with-prescribed-boundary-endpoints-September-26-2026/main.pdf"},{"title":"Cylinder loop weights and planar nesting","path":"preprints/Cylinder-loop-weights-and-planar-nesting-September-26-2026/main.pdf"},{"title":"Mass and covering exponents for fixed-length honeycomb walks","path":"preprints/Mass-and-covering-exponents-for-fixed-length-honeycomb-walks-September-26-2026/main.pdf"},{"title":"Signed cylinder propagation and marked polygons on the honeycomb lattice","path":"preprints/Signed-cylinder-propagation-and-marked-polygons-on-the-honeycomb-lattice-September-26-2026/main.pdf"},{"title":"Cylinder amplitudes and logarithmic bridge-length windows on the honeycomb lattice","path":"preprints/Cylinder-amplitudes-and-logarithmic-bridge-length-windows-on-the-honeycomb-lattice-September-26-2026/main.pdf"},{"title":"Marked polygon correlations and one-arc bounds","path":"preprints/Marked-polygon-correlations-and-one-arc-bounds-September-26-2026/main.pdf"},{"title":"Disk transfer representations and confined bridge mass","path":"preprints/Disk-transfer-representations-and-confined-bridge-mass-September-26-2026/main.pdf"},{"title":"Polynomial vacuum representations and bridge mass for honeycomb walks","path":"preprints/Polynomial-vacuum-representations-and-bridge-mass-for-honeycomb-walks-September-26-2026/main.pdf"},{"title":"Renewal and changes of law for critical honeycomb walks","path":"preprints/Renewal-and-changes-of-law-for-critical-honeycomb-walks-September-26-2026/main.pdf"},{"title":"Critical strip-crossing mass on the honeycomb lattice","path":"preprints/Critical-strip-crossing-mass-on-the-honeycomb-lattice-September-26-2026/main.pdf"},{"title":"Uniform marked-polygon estimates and sharp finite bridge moments","path":"preprints/Uniform-marked-polygon-estimates-and-sharp-finite-bridge-moments-September-26-2026/main.pdf"},{"title":"Cap-selected amplitudes and triangle chords for honeycomb walks","path":"preprints/Cap-selected-amplitudes-and-triangle-chords-for-honeycomb-walks-September-26-2026/main.pdf"}]},{"id":"238","title":"Optimal logarithmic mixing of the Thorp shuffle","desc":"Proves that the Thorp shuffle randomizes $N=2^d$ labeled cards in $\\Theta(\\log N)$ physical shuffles, settling its optimal mixing order for power-of-two deck sizes. Convergence is in total variation from the worst initial ordering and concerns the entire permutation, not just individual card positions.","subject":"Probability and statistical mechanics","lean":2,"applied":3,"difficulty":4,"year":1973,"note":"The number of rounds needed by Thorp-shuffle ciphers and permutation networks. Asymptotic, for power-of-two sizes.","papers":[{"title":"Optimal-order mixing of the Thorp shuffle","path":"preprints/Optimal-order-mixing-of-the-Thorp-shuffle-September-26-2026/paper.pdf"},{"title":"Random coordinate frames and partial permutation laws","path":"preprints/Random-coordinate-frames-and-partial-permutation-laws-September-26-2026/main.pdf"},{"title":"From partial permutation information to Fourier bounds","path":"preprints/From-partial-permutation-information-to-Fourier-bounds-September-26-2026/main.pdf"},{"title":"Conditional information under deterministic coordinate sweeps","path":"preprints/Conditional-information-under-deterministic-coordinate-sweeps-September-26-2026/main.pdf"},{"title":"Conditional permutations in a revealed switching environment","path":"preprints/Conditional-permutations-in-a-revealed-switching-environment-September-26-2026/paper.pdf"},{"title":"Routing densities and representation contraction for Thorp sweeps","path":"preprints/Routing-densities-and-representation-contraction-for-Thorp-sweeps-September-26-2026/paper.pdf"},{"title":"Row–column symmetry and contraction of coordinate sweeps","path":"preprints/Row-column-symmetry-and-contraction-of-coordinate-sweeps-September-26-2026/paper.pdf"},{"title":"Random-subspace tests and trace smoothing for coordinate sweeps","path":"preprints/Random-subspace-tests-and-trace-smoothing-for-coordinate-sweeps-September-26-2026/paper.pdf"},{"title":"Compatibility entropy and the spectrum of a Thorp sweep","path":"preprints/Compatibility-entropy-and-the-spectrum-of-a-Thorp-sweep-September-26-2026/paper.pdf"},{"title":"Signed tensor densities and diagram budgets for the Thorp shuffle","path":"preprints/Signed-tensor-densities-and-diagram-budgets-for-coordinate-sweeps-September-26-2026/paper.pdf"},{"title":"Conditional coordinate sweeps and analytic transfer","path":"preprints/Conditional-coordinate-sweeps-and-analytic-transfer-September-26-2026/main.pdf"},{"title":"A strict four-row permanent inequality and permutation moments","path":"preprints/A-strict-four-row-permanent-inequality-and-permutation-moments-September-26-2026/main.pdf"}]},{"id":"239","title":"Sharp singularity rates for symmetric random sign matrices","desc":"Determines the sharp exponential singularity rate of symmetric random sign matrices with independent entries on and above the diagonal. Uniform signs give $\\Pr(\\det A_n=0)=(1/2+o(1))^n$; for fixed bias $p\\in(0,1)\\setminus\\{1/2\\}$, the rate is $(p^2+(1-p)^2+o(1))^n$. In the biased case, agreeing rows attain this rate.","subject":"Probability and statistical mechanics","lean":0,"applied":2,"difficulty":3,"year":2006,"note":"Invertibility of random symmetric discrete matrices. The quantitative version needed in numerical analysis is not addressed.","papers":[{"title":"The sharp exponential rate of singularity for symmetric Bernoulli matrices","path":"preprints/The-sharp-exponential-rate-of-singularity-for-symmetric-Bernoulli-matrices-October-3-2026/symmetric-bernoulli-singularity.pdf"},{"title":"The sharp singularity rate for biased symmetric sign matrices","path":"preprints/The-sharp-singularity-rate-for-biased-symmetric-sign-matrices-October-4-2026/biased-symmetric-sign-singularity.pdf"}]},{"id":"240","title":"Shelah&#x27;s eventual categoricity and the prescribed-threshold obstruction","desc":"Proves Shelah&#x27;s eventual categoricity conjecture in ZFC: for each bound on the Löwenheim–Skolem number, a uniform threshold makes categoricity of an abstract elementary class in one cardinal above that threshold imply categoricity throughout the same tail. Categoricity means uniqueness up to isomorphism at a given cardinality. Under the continuum hypothesis, a proposed specific Hanf threshold need not suffice.","subject":"Mathematical logic","lean":2,"applied":1,"difficulty":5,"year":null,"note":"Model theory. No route identified.","papers":[{"title":"A CH obstruction to a prescribed categoricity threshold","path":"preprints/A-CH-Obstruction-to-a-Prescribed-Categoricity-Threshold-September-24-2026/paper.pdf"},{"title":"Eventual categoricity for abstract elementary classes","path":"preprints/Eventual-Categoricity-for-Abstract-Elementary-Classes-September-24-2026/paper.pdf"}]},{"id":"241","title":"Rigidity of the Turing degrees","desc":"Every order automorphism of the Turing degrees is the identity, resolving their rigidity problem. Thus no nontrivial relabeling of degrees preserves the ordering by relative computability.","subject":"Mathematical logic","lean":2,"applied":1,"difficulty":5,"year":1967,"note":"Computability theory. No route identified.","papers":[{"title":"Rigidity of the Turing degrees","path":"preprints/Rigidity-of-the-Turing-degrees-September-24-2026/paper.pdf"}]},{"id":"242","title":"Single-fold Diophantine representations and undecidability under an at-most-one-solution promise","desc":"Every recursively enumerable set of tuples of natural numbers has a Diophantine representation with exactly one auxiliary solution for each member and none for nonmembers. This proves the single-fold conjecture and hence the finite-fold conjecture. Diophantine solvability over the nonnegative integers remains undecidable even with an at-most-one-solution promise.","subject":"Mathematical logic","lean":2,"applied":1,"difficulty":4,"year":null,"note":"Diophantine representations. No route identified.","papers":[{"title":"Single-fold Diophantine representations","path":"preprints/Single-fold-Diophantine-representations-September-24-2026/paper.pdf"}]},{"id":"243","title":"Separating choiceless counting from polynomial time and witnessed choice","desc":"Confirms the Blass–Gurevich–Shelah noncapture conjecture: consistency of a linear system over 𝔽<sub>3<\/sub> defines a polynomial-time query on unordered finite structures that choiceless polynomial time with counting cannot express. A separate result shows that adding witnessed symmetric choice strictly increases expressive power. Both separations hold for the full counting formalism, allowing hereditarily finite sets of arbitrary finite rank.","subject":"Mathematical logic","lean":2,"applied":2,"difficulty":4,"year":1999,"note":"A candidate logic for polynomial time fails to capture it. Bears on database query languages.","papers":[{"title":"Choiceless polynomial time with counting does not capture polynomial time","path":"preprints/Choiceless-polynomial-time-with-counting-does-not-capture-polynomial-time-September-23-2026/paper.pdf"},{"title":"Witnessed symmetric choice is strictly stronger than choiceless polynomial time with counting","path":"preprints/Witnessed-symmetric-choice-is-strictly-stronger-than-choiceless-polynomial-time-with-counting-September-24-2026/paper.pdf"}]},{"id":"244","title":"The Partition Principle does not imply Choice","desc":"Assuming ZF is consistent, constructs a model in which every surjective image of a set injects into that set, yet the axiom of choice fails. Choice for ordinal-indexed families still holds. From any countable transitive model of ZFC, a separate construction gives a transitive symmetric extension with these properties and no new countable sequences of ground-model elements.","subject":"Mathematical logic","lean":2,"applied":1,"difficulty":5,"year":1902,"note":"Set theory without choice. No route identified.","papers":[{"title":"The Partition Principle does not imply Choice","path":"preprints/The-Partition-Principle-does-not-imply-Choice-September-24-2026/partition-principle-without-choice.pdf"}]},{"id":"245","title":"Weak normalization implies strong normalization in pure type systems","desc":"Proves that weak normalization implies strong normalization for every pure type system: if every legal expression in every valid context has a <i>β<\/i>-normal form, every <i>β<\/i>-reduction sequence terminates. This resolves the <i>β<\/i>-Barendregt–Geuvers–Klop conjecture, including nonfunctional rules and open contexts.","subject":"Mathematical logic","lean":1,"applied":2,"difficulty":4,"year":null,"note":"Type systems underlie proof assistants and typed programming languages. The theorem relates two termination properties across all pure type systems.","papers":[{"title":"Weak and strong normalization in pure type systems","path":"preprints/Weak-and-strong-normalization-in-pure-type-systems-September-25-2026/paper.pdf"}]},{"id":"246","title":"Cannon&#x27;s conjecture","desc":"Every word-hyperbolic group with boundary homeomorphic to <i>S<\/i><sup>2<\/sup> admits a proper cocompact isometric action on hyperbolic three-space with finite kernel, proving Cannon&#x27;s conjecture. Every torsion-free such group is therefore the fundamental group of a closed hyperbolic three-manifold.","subject":"Group theory","lean":1,"applied":1,"difficulty":5,"year":1994,"note":"Geometric group theory. No route identified.","papers":[{"title":"A Modulus Proof of Cannon’s Conjecture","path":"preprints/A-Modulus-Proof-of-Cannons-Conjecture-September-23-2026/paper.pdf"}]},{"id":"247","title":"An infinite finitely presented residually finite 2-group and a finitely presented nil algebra","desc":"Constructs an infinite finitely presented residually finite group whose elements all have finite 2-power order, answering the finitely presented Burnside problem negatively even in this class. The construction also yields an infinite-dimensional finitely presented nil associative 𝔽<sub>2<\/sub>-algebra and a finitely presented infinite-dimensional algebraic unitization, giving negative answers to the corresponding nilpotence and Kurosh finiteness questions.","subject":"Group theory","lean":1,"applied":1,"difficulty":5,"year":null,"note":"Burnside-type problems. No route identified.","papers":[{"title":"An infinite finitely presented residually finite 2-group","path":"preprints/An-infinite-finitely-presented-residually-finite-2-group-October-5-2026/residually-finite-torsion.pdf"},{"title":"An infinite finitely presented periodic group","path":"preprints/An-infinite-finitely-presented-periodic-group-September-23-2026/paper.pdf"}]},{"id":"248","title":"Thompson&#x27;s group <i>F<\/i> is nonamenable","desc":"Proves that Thompson&#x27;s group <i>F<\/i>, the group of dyadic piecewise linear homeomorphisms of the interval, is nonamenable, resolving its longstanding amenability problem.","subject":"Group theory","lean":2,"applied":1,"difficulty":5,"year":1979,"note":"Amenability. No route identified.","papers":[{"title":"Thompson&#x27;s group F is nonamenable","path":"preprints/Thompsons-group-F-is-nonamenable-September-23-2026/paper.pdf"}]},{"id":"249","title":"A finitely generated Eilenberg–Ganea counterexample","desc":"Constructs a finitely generated residually finite group with integral cohomological dimension two and geometric dimension three, disproving the Eilenberg–Ganea conjecture. It has no two-dimensional classifying space, even with infinitely many cells.","subject":"Group theory","lean":1,"applied":1,"difficulty":5,"year":1957,"note":"Cohomological dimension of groups. No route identified.","papers":[{"title":"A finitely generated counterexample to the Eilenberg–Ganea conjecture","path":"preprints/A-finitely-generated-counterexample-to-the-Eilenberg-Ganea-conjecture-September-23-2026/paper.pdf"}]},{"id":"250","title":"Boone–Higman embeddings with higher finiteness","desc":"A finitely generated group has decidable word problem exactly when it embeds in a finitely presented simple group, proving the Boone–Higman conjecture. The target can have type <i>F<\/i><sub>∞<\/sub>: a classifying space with finitely many cells in each dimension. A single group of type <i>F<\/i><sub>∞<\/sub> can also contain every finitely presented group.","subject":"Group theory","lean":2,"applied":1,"difficulty":5,"year":1973,"note":"Word problem and simple groups. No route identified.","papers":[{"title":"Finite algebraic envelopes and the Boone–Higman conjecture","path":"preprints/Finite-algebraic-envelopes-and-the-Boone-Higman-conjecture-September-23-2026/paper.pdf"},{"title":"Simple F∞ overgroups of groups with decidable word problem","path":"preprints/Simple-F-infinity-overgroups-of-groups-with-decidable-word-problem-September-23-2026/paper.pdf"},{"title":"A universal group of type F∞","path":"preprints/A-universal-group-of-type-F-infinity-September-23-2026/paper.pdf"}]},{"id":"251","title":"Amenability, unitarizability, and strong Ulam stability","desc":"Resolves Dixmier&#x27;s problem for all discrete groups: amenability is equivalent to every uniformly bounded Hilbert-space representation being similar to a unitary representation. For countable discrete groups, amenability is also equivalent to strong Ulam stability: sufficiently accurate unitary approximate representations are uniformly close in operator norm to genuine representations on the same, possibly infinite-dimensional, Hilbert space.","subject":"Group theory","lean":2,"applied":1,"difficulty":5,"year":1950,"note":"Representation theory of groups. No route identified.","papers":[{"title":"Unitarizability implies amenability for discrete groups","path":"preprints/Unitarizability-Implies-Amenability-for-Countable-Groups-September-23-2026/paper.pdf"},{"title":"Strong Ulam Stability Characterizes Amenability","path":"preprints/Strong-Ulam-Stability-Characterizes-Amenability-October-5-2026/strong-ulam-stability.pdf"}]},{"id":"252","title":"A torsion-free hyperbolic group that is neither residually finite nor linear over any field","desc":"Constructs a torsion-free word-hyperbolic group that is not residually finite, answering the residual-finiteness question negatively. One fixed nonidentity element is killed by every finite-dimensional linear representation over every commutative field, so the group is not linear over any such field.","subject":"Group theory","lean":2,"applied":1,"difficulty":5,"year":1987,"note":"Hyperbolic groups. No route identified.","papers":[{"title":"A torsion-free hyperbolic group that is not residually finite","path":"preprints/a-torsion-free-hyperbolic-group-that-is-not-residually-finite-September-23-2026/paper.pdf"}]},{"id":"253","title":"An infinite finitely presented simple amenable group","desc":"Constructs an infinite finitely presented simple amenable group, answering the longstanding question of whether these properties can occur simultaneously.","subject":"Group theory","lean":2,"applied":1,"difficulty":4,"year":null,"note":"Amenable groups. No route identified.","papers":[{"title":"An infinite finitely presented simple amenable group","path":"preprints/An-Infinite-Finitely-Presented-Simple-Amenable-Group-September-23-2026/paper.pdf"}]},{"id":"254","title":"Classifying spaces and geometric obstructions for Artin groups","desc":"The Salvetti complex of every finite-rank Artin group is aspherical, proving the Artin $K(\\pi,1)$ conjecture. Arbitrary intersections of its parabolic subgroups are parabolic, proving the Parabolic Intersection Conjecture. An explicit Artin group admits no proper cocompact isometric action on any nonempty proper CAT$(0)$ space.","subject":"Group theory","lean":2,"applied":1,"difficulty":5,"year":null,"note":"Artin groups. No route identified.","papers":[{"title":"Harmonic heights and the Artin K(pi,1) conjecture","path":"preprints/Harmonic-heights-and-the-Artin-K-pi-1-conjecture-September-23-2026/paper.pdf"},{"title":"An Artin group with no geometric CAT(0) action","path":"preprints/An-Artin-group-with-no-geometric-CAT-0-action-September-23-2026/paper.pdf"},{"title":"Parabolic intersections in Artin groups","path":"preprints/Parabolic-intersections-in-Artin-groups-September-23-2026/paper.pdf"}]},{"id":"255","title":"Quasi-isometric recognition of virtually polycyclic groups","desc":"Proves that every finitely generated group quasi-isometric to a finitely generated virtually polycyclic group is virtually polycyclic, resolving the Eskin–Fisher–Whyte lattice-recognition conjecture. Equivalently, a group quasi-isometric to a lattice in a connected simply connected solvable Lie group is virtually a uniform lattice in some such Lie group, possibly a different one.","subject":"Group theory","lean":1,"applied":1,"difficulty":4,"year":null,"note":"Quasi-isometric rigidity. No route identified.","papers":[{"title":"Quasi-isometric recognition of virtually polycyclic groups","path":"preprints/quasi-isometric-recognition-of-virtually-polycyclic-groups-September-24-2026/paper.pdf"}]},{"id":"256","title":"Nonsingular systems of equations over arbitrary groups","desc":"Proves that every finite system of equations over an arbitrary group whose exponent-sum matrix has full row rank over ℚ has a simultaneous solution in an overgroup, resolving Howie&#x27;s conjecture. The coefficient group embeds in the presented quotient. A companion proves Kervaire&#x27;s conjecture: adjoining one generator and one relation cannot trivialize a nontrivial group.","subject":"Group theory","lean":1,"applied":1,"difficulty":4,"year":1981,"note":"Equations over groups. No route identified.","papers":[{"title":"Nonsingular systems of equations over arbitrary groups","path":"preprints/Nonsingular-systems-of-equations-over-arbitrary-groups-October-5-2026/nonsingular-systems-over-arbitrary-groups.pdf"},{"title":"The Kervaire theorem for groups","path":"preprints/The-Kervaire-Theorem-for-Groups-September-24-2026/The-Kervaire-Theorem-for-Groups-September-24-2026.pdf"}]},{"id":"257","title":"A hyperbolic group without a geometric CAT(0) action","desc":"Answers negatively whether every word-hyperbolic group is a CAT(0) group. Constructs one with a finite classifying space but no proper cocompact isometric action on any proper complete $\\mathop{\\mathrm{CAT}}\\nolimits (0)$ space, in any dimension.","subject":"Group theory","lean":2,"applied":1,"difficulty":4,"year":null,"note":"Hyperbolic groups. No route identified.","papers":[{"title":"A hyperbolic group with no geometric CAT(0) action","path":"preprints/A-hyperbolic-group-with-no-geometric-CAT0-action-September-25-2026/paper.pdf"}]},{"id":"258","title":"Gersten’s conjecture and virtual compact specialness of one-relator groups","desc":"Proves Gersten&#x27;s conjecture: every finitely generated one-relator group containing no Baumslag–Solitar subgroup $\\mathrm{BS}(m,n)$, with $m,n\\ne0$, is word-hyperbolic. It also proves that every word-hyperbolic one-relator group is virtually compact special.","subject":"Group theory","lean":0,"applied":1,"difficulty":4,"year":1992,"note":"One-relator groups. No route identified.","papers":[{"title":"Baumslag-Solitar-free one-relator groups are hyperbolic","path":"preprints/Baumslag-Solitar-free-one-relator-groups-are-hyperbolic-September-25-2026/paper.pdf"},{"title":"Virtual compact specialness of hyperbolic one-relator groups","path":"preprints/Virtual-compact-specialness-of-hyperbolic-one-relator-groups-September-25-2026/paper.pdf"}]},{"id":"259","title":"A group without fixed price","desc":"Constructs a finitely generated group with two essentially free probability-measure-preserving actions of different costs, answering the general fixed-price problem negatively. Its Bernoulli action has cost bounded away from one, while a sequence of finite height extensions has costs tending to one.","subject":"Group theory","lean":0,"applied":1,"difficulty":4,"year":2000,"note":"Measured group theory. No route identified.","papers":[{"title":"A group without fixed price","path":"preprints/A-group-without-fixed-price-October-5-2026/unequal-costs-rank-100-amalgam.pdf"}]},{"id":"260","title":"Spacetime Penrose inequalities: enclosing area, charge, rotation, and anti-de Sitter extensions","desc":"Proves the sharp enclosing-area spacetime Penrose inequality for smooth one-ended asymptotically flat initial data in every spatial dimension <i>n<\/i> ≥ 3, under dominant energy, weak future trapping, positive enclosing area, and the stated decay assumptions. It bounds invariant ADM mass below using minimum enclosing area, with equality rigidity under additional horizon hypotheses. Charged upper-area bounds treat dyonic three-dimensional data; the higher-dimensional purely electric extension uses the matched neutral theorem.","subject":"Mathematical physics","lean":1,"applied":1,"difficulty":5,"year":1973,"note":"General relativity. No computational consequence identified.","papers":[{"title":"The spacetime Penrose inequality with charge and original-data rigidity","path":"preprints/The-spacetime-Penrose-inequality-with-charge-and-original-data-rigidity-October-5-2026/paper.pdf"},{"title":"A Charged Reduction of the Spacetime Penrose Inequality in Spatial Dimensions at Least Four","path":"preprints/A-Charged-Reduction-of-the-Spacetime-Penrose-Inequality-in-Spatial-Dimensions-at-Least-Four-October-5-2026/paper.pdf"},{"title":"Spacetime Penrose inequalities: enclosing area, charge, and rigidity","path":"preprints/Spacetime-Penrose-inequalities-enclosing-area-charge-and-rigidity-October-5-2026/paper.pdf"},{"title":"The Kerr–Newman Penrose Inequality for Axisymmetric Electrovacuum Exteriors","path":"preprints/The-Kerr-Newman-Penrose-Inequality-for-Axisymmetric-Electrovacuum-Exteriors-October-5-2026/paper.pdf"},{"title":"Electromagnetic tails and the Kerr–Newman Penrose inequality","path":"preprints/Electromagnetic-tails-and-the-Kerr-Newman-Penrose-inequality-October-5-2026/paper.pdf"},{"title":"The nonmaximal anti-de Sitter Penrose Inequality and original-data rigidity","path":"preprints/The-nonmaximal-anti-de-Sitter-Penrose-Inequality-and-original-data-rigidity-October-5-2026/paper.pdf"},{"title":"The Penrose inequality for maximal asymptotically hyperbolic initial data","path":"preprints/The-Penrose-inequality-for-maximal-asymptotically-hyperbolic-initial-data-October-5-2026/paper.pdf"},{"title":"A local Penrose inequality for conformal perturbations of Schwarzschild–anti-de Sitter data","path":"preprints/A-local-Penrose-inequality-for-conformal-perturbations-of-Schwarzschild-anti-de-Sitter-data-October-5-2026/paper.pdf"},{"title":"The spacetime Penrose inequality and enclosing area","path":"preprints/The-spacetime-Penrose-inequality-and-enclosing-area-September-27-2026/paper.pdf"},{"title":"Conformal flow and the Riemannian Penrose inequality with minimizing frontiers","path":"preprints/Conformal-flow-and-the-Riemannian-Penrose-inequality-with-minimizing-frontiers-September-27-2026/paper.pdf"},{"title":"Equality and rigidity in the spacetime Penrose inequality","path":"preprints/Equality-and-rigidity-in-the-spacetime-Penrose-inequality-September-27-2026/paper.pdf"},{"title":"Boundary graph deformations for the spacetime Penrose inequality","path":"preprints/Boundary-graph-deformations-for-the-spacetime-Penrose-inequality-September-27-2026/paper.pdf"},{"title":"Area-controlled end replacement and the Bondi Penrose inequality in the CKS class","path":"preprints/Area-controlled-end-replacement-and-the-Bondi-Penrose-inequality-in-the-CKS-class-September-27-2026/paper.pdf"}]},{"id":"261","title":"Localization and delocalization in the Anderson model","desc":"Resolves the predicted spectral contrast for the lattice Anderson model with independent uniform site potentials. In dimension two, every positive disorder strength gives almost surely pure-point spectrum. In every fixed dimension <i>d<\/i> ≥ 3, sufficiently weak positive disorder gives purely absolutely continuous spectrum on a fixed open interval with nonzero spectral weight.","subject":"Mathematical physics","lean":1,"applied":3,"difficulty":5,"year":1958,"note":"Localization and extended states are the mathematical basis of the metal-insulator transition and of wave transport in disordered media.","papers":[{"title":"Absolutely Continuous Spectrum for Weak-Disorder Anderson Models in Dimensions at Least Three","path":"preprints/Absolutely-Continuous-Spectrum-for-Weak-Disorder-Anderson-Models-in-Dimensions-at-Least-Three-September-23-2026/paper.pdf"},{"title":"Pure-Point Spectrum for the Two-Dimensional Anderson Model at Every Positive Disorder","path":"preprints/Pure-Point-Spectrum-for-the-Two-Dimensional-Anderson-Model-at-Every-Positive-Disorder-September-23-2026/paper.pdf"}]},{"id":"262","title":"Sharp finite-matrix Lieb–Thirring inequalities and all equality cases","desc":"Proves the sharp one-dimensional Lieb–Thirring inequality for $1/2\\lt \\gamma\\lt 3/2$ and arbitrary finite-matrix potentials <i>W<\/i> ≥ 0 with $\\int\\mathop{\\mathrm{tr}}\\nolimits (W^{\\gamma+1/2})\\lt \\infty$: the optimal constant is the scalar one-bound-state value, independent of matrix size. All equality cases are direct sums, in one constant unitary basis, of scalar sech<sup>2<\/sup> solitons with independent scales and centers, and zero channels.","subject":"Mathematical physics","lean":2,"applied":2,"difficulty":4,"year":1976,"note":"Bounds on bound-state energies of Schrödinger operators. Sharp constants enter stability-of-matter estimates.","papers":[{"title":"Equality cases in the sharp one-dimensional matrix Lieb–Thirring inequality","path":"preprints/Equality-cases-in-the-sharp-one-dimensional-matrix-Lieb-Thirring-inequality-October-5-2026/sharp-one-dimensional-lieb-thirring-inequalities-matrix-potentials.pdf"},{"title":"Sharp one-dimensional Lieb–Thirring inequalities for matrix potentials","path":"preprints/Sharp-one-dimensional-Lieb-Thirring-inequalities-for-matrix-potentials-October-5-2026/sharp-matrix-lieb-thirring.pdf"},{"title":"Sharp one-dimensional Lieb–Thirring constants","path":"preprints/Sharp-One-Dimensional-Lieb-Thirring-Constants-September-23-2026/paper.pdf"}]},{"id":"263","title":"The ionization and generalized ionization conjectures","desc":"For the full nonrelativistic Coulomb model with two electron spin states, proves that a molecule with <i>M<\/i> fixed nuclei of charges at least one and total charge <i>Z<\/i> strictly binds at most $Z+CM$ electrons. Neutral-atom first ionization energies and radii containing all but an expected half-electron have universal positive upper and lower bounds. The energy cost of removing <i>m<\/i> electrons has Thomas–Fermi asymptotics as $m\\to\\infty$ and $Z/m\\to\\infty$; neutral-atom outer radii have the corresponding iterated-limit asymptotics, taking $Z\\to\\infty$ first.","subject":"Mathematical physics","lean":2,"applied":2,"difficulty":5,"year":1984,"note":"Bounds how many extra electrons an atom or molecule can bind. A constraint for quantum chemistry.","papers":[{"title":"Uniform excess charge for Coulomb molecules and the outer radius of neutral atoms","path":"preprints/Uniform-excess-charge-for-Coulomb-molecules-and-the-outer-radius-of-neutral-atoms-September-24-2026/paper.pdf"},{"title":"Generalized ionization energies for full Coulomb atoms","path":"preprints/Generalized-ionization-energies-for-full-Coulomb-atoms-September-24-2026/paper.pdf"},{"title":"Generalized outer-electron radii of neutral Coulomb atoms","path":"preprints/Generalized-outer-electron-radii-of-neutral-Coulomb-atoms-September-24-2026/paper.pdf"}]},{"id":"264","title":"Strong cosmic censorship near two-ended Kerr data","desc":"Proves local strong cosmic censorship near each fixed rotating subextremal Kerr bridge. A dense <i>G<\/i><sub><i>δ<\/i><\/sub> subset of a weighted smooth neighborhood of smooth complete two-ended asymptotically flat vacuum data has full maximal globally hyperbolic developments with no future continuous nondegenerate extension whose weak connection is locally square-integrable. No symmetry is imposed; extensions need not satisfy the vacuum equations.","subject":"Mathematical physics","lean":0,"applied":1,"difficulty":5,"year":null,"note":"General relativity. No computational consequence identified.","papers":[{"title":"Generic Future Inextendibility with Square-Integrable Connection Near a Fixed Kerr Spacetime","path":"preprints/Generic-Future-Inextendibility-with-Square-Integrable-Connection-Near-a-Fixed-Kerr-Spacetime-September-23-2026/paper.pdf"},{"title":"Generic C1 Future Inextendibility Near Rotating Subextremal Kerr Spacetimes","path":"preprints/Generic-C1-Future-Inextendibility-Near-Rotating-Subextremal-Kerr-Spacetimes-September-23-2026/paper.pdf"},{"title":"Quantitative Near-Kerr Evolution and Generic C2 Future Inextendibility","path":"preprints/Quantitative-Near-Kerr-Evolution-and-Generic-C2-Future-Inextendibility-September-23-2026/paper.pdf"}]},{"id":"265","title":"Area laws and tensor networks for two-dimensional gapped systems","desc":"Proves an entropy area law for unique ground states of finite-range Hamiltonians on arbitrary finite induced square-lattice domains, using only a uniform full-system spectral gap and bounds on the local interactions. On open $L\\times L$ squares, uniformly gapped nearest-neighbor ground states also admit projected entangled-pair state approximations with polynomial bond dimension and global vector error at most <i>L<\/i><sup>−1<\/sup>.","subject":"Mathematical physics","lean":0,"applied":4,"difficulty":5,"year":2007,"note":"An area law in two dimensions justifies tensor-network representations of gapped ground states, the basis of tensor-network simulation.","papers":[{"title":"A two-dimensional area law from a global spectral gap","path":"preprints/A-two-dimensional-area-law-from-a-global-spectral-gap-September-24-2026/paper.pdf"},{"title":"Polynomial PEPS approximation of gapped square-grid ground states","path":"preprints/Polynomial-PEPS-approximation-of-gapped-square-grid-ground-states-September-24-2026/paper.pdf"}]},{"id":"266","title":"Exactly three mutually unbiased bases in dimension six","desc":"Proves $N(6)=3$, resolving Zauner&#x27;s dimension-six mutually unbiased bases conjecture: three such bases exist in ℂ<sup>6<\/sup>, but four cannot. The exclusion is a complete certified computation under the stated binary64 arithmetic and compiler conditions. An independent companion proves the Matolcsi–Ruzsa–Weiner Fourier-vanishing conjecture for order-six complex Hadamard matrices outside Tao&#x27;s cubic equivalence class.","subject":"Mathematical physics","lean":1,"applied":3,"difficulty":4,"year":1999,"note":"Mutually unbiased bases are used in quantum state tomography and key distribution. Six is the smallest dimension that is not a prime power.","papers":[{"title":"The maximum number of mutually unbiased bases in dimension six","path":"preprints/The-maximum-number-of-mutually-unbiased-bases-in-dimension-six-September-24-2026/The-maximum-number-of-mutually-unbiased-bases-in-dimension-six-September-24-2026.pdf"},{"title":"Exact Fourier certificates for complex Hadamard matrices of order six","path":"preprints/Exact-Fourier-certificates-for-complex-Hadamard-matrices-of-order-six-September-24-2026/Exact-Fourier-certificates-for-complex-Hadamard-matrices-of-order-six-September-24-2026.pdf"}]},{"id":"267","title":"Positive-temperature Bose–Einstein condensation and exact quantum depletion","desc":"Proves Bose–Einstein condensation for the exact canonical Gibbs state of the three-dimensional hard-sphere gas: each fixed exclusion distance and sufficiently small fixed density admit a strictly positive temperature, independent of volume, with positive condensate fraction in the thermodynamic limit. At zero temperature, proves the Bogoliubov leading quantum-depletion law for hard spheres and fixed bounded nonnegative radial finite-range potentials of positive scattering length, taking the thermodynamic limit before the dilute limit.","subject":"Mathematical physics","lean":1,"applied":2,"difficulty":5,"year":1925,"note":"Proof of condensation for an interacting gas. Physical modelling assumes it.","papers":[{"title":"Bose–Einstein condensation at positive temperature in the dilute hard-sphere gas","path":"preprints/Bose-Einstein-condensation-at-positive-temperature-in-the-dilute-hard-sphere-gas-October-5-2026/positive-temperature-hard-spheres.pdf"},{"title":"Quantum Depletion and Momentum Distribution in the Dilute Hard-Sphere Bose Gas","path":"preprints/Quantum-Depletion-and-Momentum-Distribution-in-the-Dilute-Hard-Sphere-Bose-Gas-October-5-2026/Quantum-Depletion-in-the-Dilute-Hard-Sphere-Bose-Gas.pdf"},{"title":"Quantum Depletion for Fixed Bounded Repulsive Potentials","path":"preprints/Quantum-Depletion-for-Fixed-Bounded-Repulsive-Potentials-October-5-2026/fixed-repulsion-quantum-depletion.pdf"},{"title":"A density-uniform condensate bound for dilute Bose gases","path":"preprints/A-density-uniform-condensate-bound-for-dilute-Bose-gases-September-27-2026/paper.pdf"},{"title":"Ground-state condensation in the dilute hard-sphere gas","path":"preprints/Ground-state-condensation-in-the-dilute-hard-sphere-gas-September-24-2026/paper.pdf"}]},{"id":"268","title":"The spin-one Haldane gap","desc":"Proves the spin-one Haldane gap conjecture for the pure antiferromagnetic Heisenberg chain on even periodic rings: the spectral gap stays uniformly positive as the chain grows. A companion establishes a gap for odd open chains with endpoint field $h=3/5$ and gives boundary-selected infinite-volume states with topological index −1.","subject":"Mathematical physics","lean":0,"applied":2,"difficulty":5,"year":1983,"note":"Spectral gap of the spin-one chain. Physical modelling assumes it.","papers":[{"title":"The periodic spin-one Haldane gap","path":"preprints/The-periodic-spin-one-Haldane-gap-September-24-2026/paper.pdf"},{"title":"A boundary-field gap for the spin-one Heisenberg chain","path":"preprints/A-boundary-field-gap-for-the-spin-one-Heisenberg-chain-September-24-2026/paper.pdf"}]},{"id":"269","title":"Uniform Laughlin gap and stability under bounded scalar disorder","desc":"Proves the fermionic Laughlin spectral-gap conjecture for the full <i>V<\/i><sub>1<\/sub> interaction at filling 1/3 on the round sphere. The unique ground state remains uniformly gapped under sufficiently weak bounded real scalar one-body potentials projected to the lowest Landau level. Both the gap and disorder threshold are uniform over all sufficiently large particle numbers and all normalized potential profiles.","subject":"Mathematical physics","lean":2,"applied":2,"difficulty":4,"year":1983,"note":"Spectral gap in the fractional quantum Hall effect. Physical modelling assumes it.","papers":[{"title":"Uniform Stability of the Spherical Laughlin Gap","path":"preprints/Uniform-Stability-of-the-Spherical-Laughlin-Gap-October-5-2026/uniform-stability-spherical-laughlin-gap.pdf"},{"title":"A Fock-space inequality and the Laughlin spectral gap","path":"preprints/A-Fock-space-inequality-and-the-Laughlin-spectral-gap-September-24-2026/A-Fock-space-inequality-and-the-Laughlin-spectral-gap-September-24-2026.pdf"}]},{"id":"270","title":"Threshold and positive-energy bound states of the BFSS matrix model","desc":"Proves that the undeformed relative $\\mathrm{SU}(N)$ BFSS model has exactly one normalizable zero-energy state for every finite <i>N<\/i> ≥ 2, resolving the threshold-bound-state conjecture. For $\\mathrm{SU}(2)$, a companion proves infinitely many normalizable positive-energy eigenstates with unbounded energies, contradicting the original BFSS paper&#x27;s exclusion of additional bound states at <i>N<\/i> = 2.","subject":"Mathematical physics","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Matrix models of string theory. No route identified.","papers":[{"title":"The unique threshold bound state of the SU(N) BFSS model","path":"preprints/The-unique-threshold-bound-state-of-the-SU-N-BFSS-model-September-24-2026/paper.pdf"},{"title":"Positive eigenvalues of the relative SU(2) BFSS Hamiltonian","path":"preprints/Positive-eigenvalues-of-the-relative-SU-2-BFSS-Hamiltonian-October-5-2026/positive-eigenvalues-relative-su2-bfss.pdf"}]},{"id":"271","title":"Bloch&#x27;s law, its lattice correction, and the spherical magnetization law","desc":"Proves Bloch&#x27;s <i>T<\/i><sup>3/2<\/sup> law with its exact coefficient for three-dimensional quantum Heisenberg ferromagnets at every positive quantum spin, allowing nonnegative symmetric finite-range couplings whose support generates ℤ<sup>3<\/sup>. The thermodynamic limit precedes the zero-field derivative and low-temperature limit. The family also proves spontaneous magnetization for nearest-neighbor models in every dimension <i>d<\/i> ≥ 3 and determines the first lattice correction for three-dimensional nearest-neighbor couplings.","subject":"Mathematical physics","lean":1,"applied":2,"difficulty":5,"year":1930,"note":"Low-temperature magnetization of a ferromagnet. Physical modelling assumes the law.","papers":[{"title":"Bloch&#x27;s Law for Finite-Range Heisenberg Ferromagnets in Three Dimensions","path":"preprints/Blochs-Law-for-Finite-Range-Heisenberg-Ferromagnets-in-Three-Dimensions-October-5-2026/bloch-law-heisenberg.pdf"},{"title":"The first lattice correction to Bloch&#x27;s law","path":"preprints/The-first-lattice-correction-to-Blochs-law-October-5-2026/first-lattice-correction-bloch-law.pdf"},{"title":"The spherical magnetization law for the three-dimensional quantum Heisenberg ferromagnet","path":"preprints/The-spherical-magnetization-law-for-the-three-dimensional-quantum-Heisenberg-ferromagnet-October-5-2026/spherical-magnetization.pdf"},{"title":"Spontaneous magnetization in the quantum Heisenberg ferromagnet","path":"preprints/Spontaneous-magnetization-in-the-quantum-Heisenberg-ferromagnet-September-24-2026/paper.pdf"}]},{"id":"272","title":"Entanglement without distillable secret key","desc":"Constructs an entangled state on $\\mathbb C^{10}\\otimes\\mathbb C^{10}$ with zero distillable secret key for the specified local-instrument protocols that complete almost surely. These allow joint local processing and authenticated two-way public communication, with no other shared private resource and an eavesdropper holding the input purification and public record. A trace-preserving PPT channel on $M_{21}(\\mathbb C)$ whose square is not entanglement breaking disproves Christandl&#x27;s PPT-square conjecture.","subject":"Mathematical physics","lean":1,"applied":2,"difficulty":4,"year":2005,"note":"Whether every entangled state can yield a secret key. The statement covers a specified class of protocols.","papers":[{"title":"Entanglement with zero distillable secret key in local dimension ten","path":"preprints/Entanglement-with-zero-distillable-secret-key-in-local-dimension-ten-September-27-2026/paper.pdf"}]},{"id":"273","title":"The entropy photon-number inequality","desc":"Proves the entropy photon-number inequality for beam-splitter mixing of two independent finite-energy bosonic inputs in any finite number of modes: the output&#x27;s entropy photon number is at least the transmissivity-weighted average of the inputs&#x27;. Arbitrary entanglement within each input is allowed, and product thermal inputs attain equality even when their entropies differ.","subject":"Mathematical physics","lean":1,"applied":4,"difficulty":4,"year":2008,"note":"The inequality gives the capacity region of the optical broadcast channel and the secrecy capacity of the optical wiretap channel.","papers":[{"title":"The entropy photon-number inequality","path":"preprints/The-entropy-photon-number-inequality-September-24-2026/paper.pdf"}]},{"id":"274","title":"Parity is not in QAC<sup>0<\/sup>","desc":"Resolves Moore&#x27;s parity conjecture in the measured-output model: constant-depth quantum circuits with arbitrary one-qubit gates, unbounded-arity Toffoli gates and polynomially many total qubits cannot compute parity with any fixed positive worst-case advantage. Ancillas start in zero, one output qubit is measured, and all other registers may be discarded. Xu–Li&#x27;s reductions give the same bounded-error obstruction for strict majority.","subject":"Mathematical physics","lean":2,"applied":2,"difficulty":4,"year":1999,"note":"A limit on what constant-depth quantum circuits compute.","papers":[{"title":"Product-projection localization and the QAC0 parity lower bound","path":"preprints/Product-projection-localization-and-the-QAC0-parity-lower-bound-September-24-2026/paper.pdf"},{"title":"Regular trajectories, pruning and quantum parity","path":"preprints/Regular-trajectories-pruning-and-quantum-parity-September-24-2026/paper.pdf"}]},{"id":"275","title":"QMA-hardness of continuum Coulomb energy","desc":"Proves QMA-hardness of approximating the electronic Coulomb energy infimum in three dimensions, minimizing over the full spinful fermionic continuum space. Deterministic polynomial-time reductions work even with only unit-charge nuclei at distinct rational positions, polynomially many electrons and an energy-threshold separation of at least one.","subject":"Mathematical physics","lean":1,"applied":3,"difficulty":3,"year":null,"note":"Ground-state energy of electrons, the target of quantum chemistry, has no efficient general algorithm even on a quantum computer unless QMA collapses.","papers":[{"title":"Continuum Coulomb hardness with binary nuclear charges","path":"preprints/Continuum-Coulomb-hardness-with-binary-nuclear-charges-September-24-2026/Continuum-Coulomb-hardness-with-binary-nuclear-charges-September-24-2026.pdf"},{"title":"QMA-hardness of continuum Coulomb energy with unit nuclear charges","path":"preprints/QMA-hardness-of-continuum-Coulomb-energy-with-unit-nuclear-charges-September-24-2026/QMA-hardness-of-continuum-Coulomb-energy-with-unit-nuclear-charges-September-24-2026.pdf"}]},{"id":"276","title":"Classical capacity of generalized amplitude damping","desc":"Determines the unassisted classical capacity of every qubit generalized amplitude-damping channel, including all damping and thermal parameters. An explicit one-variable optimization gives the capacity, attained by independent two-state signal ensembles with collective decoding. Holevo capacity, minimum output entropy and regularized classical capacity are additive when tensoring with any finite-dimensional quantum channel.","subject":"Mathematical physics","lean":2,"applied":3,"difficulty":3,"year":null,"note":"Capacity of a standard noise model for qubits with thermal relaxation.","papers":[{"title":"Classical capacity and entropy inequalities for generalized amplitude damping","path":"preprints/Classical-capacity-and-entropy-inequalities-for-generalized-amplitude-damping-September-24-2026/paper.pdf"}]},{"id":"277","title":"Threshold repetition for entangled games","desc":"Proves exponential threshold repetition for every finite two-player one-round game: if its entangled value is <i>v<\/i> &lt; 1, the probability of winning at least a fraction $v+\\delta$ of <i>k<\/i> independent repetitions decays exponentially in <i>k<\/i>, for $0\\lt \\delta\\lt 1-v$. Arbitrary joint finite-dimensional entangled strategies and correlated question distributions are allowed.","subject":"Mathematical physics","lean":2,"applied":2,"difficulty":3,"year":null,"note":"Repetition of entangled games, used in device-independent cryptography.","papers":[{"title":"Threshold parallel repetition for finite-dimensional entangled games","path":"preprints/Threshold-parallel-repetition-for-finite-dimensional-entangled-games-September-25-2026/paper.pdf"}]},{"id":"278","title":"Failure of Kohn–Sham ensemble representation","desc":"Constructs a three-electron Coulomb molecule with two equal positive-integer-charge nuclei whose absolute ground-state density has no noninteracting ground-state ensemble representation by a single real spin-independent local potential in $L^{3/2}(\\mathbb R^3)+L^\\infty(\\mathbb R^3)$. This disproves Kohn–Sham ensemble representability for that potential class; the required nuclear charge is specified nonnumerically.","subject":"Mathematical physics","lean":0,"applied":3,"difficulty":4,"year":null,"note":"Density functional calculations assume the interacting density can be reproduced by a noninteracting system. The assumption fails for a three-electron molecule.","papers":[{"title":"A Coulomb ground-state density without Kohn-Sham ensemble representation","path":"preprints/A-Coulomb-Ground-State-Density-without-Kohn-Sham-Ensemble-Representation-September-25-2026/paper.pdf"}]},{"id":"279","title":"Exact quantum factoring over a fixed finite gate set","desc":"Gives a polynomial-time uniform quantum circuit family that outputs the complete prime factorization of every integer with probability one. Both gate count and qubit count are polynomial in the input length, and one fixed finite gate set suffices.","subject":"Mathematical physics","lean":1,"applied":2,"difficulty":3,"year":1994,"note":"Removes the failure probability from quantum factoring. No practical change.","papers":[{"title":"Exact quantum factoring over a fixed finite gate set","path":"preprints/Exact-quantum-factoring-over-a-fixed-finite-gate-set-September-25-2026/main.pdf"}]},{"id":"280","title":"Unitary vertex operator algebras and conformal nets","desc":"Proves the strongly rational case of the strong-locality conjecture: every simple unitary strongly rational complex vertex operator algebra generates a completely rational conformal net. Its simple modules are unitarizable, and its representation category agrees with the net’s finite-index sectors as a braided unitary tensor category.","subject":"Mathematical physics","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Conformal field theory. No route identified.","papers":[{"title":"Strongly rational unitary vertex operator algebras and conformal nets","path":"preprints/Strongly-rational-unitary-vertex-operator-algebras-and-conformal-nets-September-25-2026/paper.pdf"}]},{"id":"281","title":"QAOA attains the SK optimum in the thermodynamic-first limit","desc":"Proves that QAOA approaches the ground-state energy of the Gaussian zero-field Sherrington–Kirkpatrick model when system size tends to infinity before circuit depth. For every accuracy, finite depth and deterministic angles independent of size and disorder achieve the required limiting expected energy per spin. This also yields leading-order optimal expected MaxCut values on large-degree random regular graphs, with size tending to infinity before degree.","subject":"Mathematical physics","lean":1,"applied":3,"difficulty":2,"year":2019,"note":"The quantum approximate optimization algorithm reaches the optimum of a standard spin-glass benchmark when size grows before depth.","papers":[{"title":"QAOA attains the SK ground-state energy in the thermodynamic-first limit","path":"preprints/QAOA-attains-the-SK-ground-state-energy-in-the-thermodynamic-first-limit-September-25-2026/QAOA-attains-the-SK-ground-state-energy-in-the-thermodynamic-first-limit-September-25-2026.pdf"},{"title":"Full support of the zero-temperature Sherrington-Kirkpatrick order parameter","path":"preprints/Full-support-of-the-zero-temperature-Sherrington-Kirkpatrick-order-parameter-September-27-2026/main.pdf"}]},{"id":"282","title":"From scale symmetry to local conformal symmetry in four-dimensional QFT","desc":"Under the stated bounded-local-net and field-reconstruction hypotheses, proves that scale symmetry implies local conformal symmetry for four-dimensional unitary positive-energy theories with a discrete bounded-below scaling spectrum of finite multiplicity, finite scaling support and a physical local scale current. The stress tensor has a traceless improvement with unchanged spacetime charges. The conclusion concerns local Ward identities, not a global conformal action on the whole net.","subject":"Mathematical physics","lean":0,"applied":1,"difficulty":4,"year":1988,"note":"Quantum field theory. No route identified.","papers":[{"title":"Scale and conformal symmetry in four-dimensional operational quantum field theory","path":"preprints/Scale-and-conformal-symmetry-in-four-dimensional-operational-quantum-field-theory-September-26-2026/main.pdf"}]},{"id":"283","title":"Polynomial-time unitary synthesis from a Boolean oracle","desc":"Solves the constant-error Aaronson–Kuperberg unitary synthesis problem: a uniform polynomial-size quantum oracle circuit approximates every <i>n<\/i>-qubit unitary channel within diamond-norm error 1/2, after a suitable Boolean oracle is chosen. Gates, qubits, oracle calls and query length are polynomially bounded. The target-dependent oracle may have an unrestricted truth table; its efficient classical construction is not asserted.","subject":"Mathematical physics","lean":0,"applied":2,"difficulty":3,"year":2007,"note":"Circuit synthesis for arbitrary unitaries relative to an oracle.","papers":[{"title":"Polynomial-Time Unitary Synthesis from a Boolean Oracle","path":"preprints/Polynomial-Time-Unitary-Synthesis-from-a-Boolean-Oracle-October-5-2026/paper.pdf"}]},{"id":"284","title":"The optimal quartic separation between randomized and quantum queries","desc":"Shows that the universal bound $R(f)=O((1+Q(f))^4)$ for total Boolean functions is sharp in its exponent, ruling out every smaller power and disproving the conjectured cubic relation. Here <i>R<\/i> and <i>Q<\/i> are randomized and quantum worst-case bit-query complexities with error at most 1/3; computation between queries is unrestricted.","subject":"Mathematical physics","lean":0,"applied":1,"difficulty":2,"year":2020,"note":"Query complexity. No route identified.","papers":[{"title":"A Nearly Quartic Separation Between Randomized and Quantum Query Complexity","path":"preprints/A-Nearly-Quartic-Separation-Between-Randomized-and-Quantum-Query-Complexity-October-5-2026/quartic-query-separation.pdf"}]},{"id":"285","title":"Counterexamples to Baum–Connes and Kadison–Kaplansky","desc":"Disproves the coefficient-free reduced Baum–Connes conjecture through a failure of rational injectivity and a separate failure of surjectivity of assembly. A finitely generated torsion-free example witnesses the injectivity failure. Separately, a torsion-free group has a nontrivial projection in its reduced group <i>C<\/i><sup>∗<\/sup>-algebra, disproving the Kadison–Kaplansky conjecture.","subject":"Operator algebras","lean":0,"applied":1,"difficulty":5,"year":1982,"note":"Operator K-theory. No route identified.","papers":[{"title":"A torsion-free counterexample to reduced Baum–Connes injectivity","path":"preprints/A-Torsion-Free-Counterexample-to-Reduced-Baum-Connes-Injectivity-September-23-2026/paper.pdf"},{"title":"A torsion-free counterexample to the Kadison–Kaplansky projection conjecture","path":"preprints/A-Torsion-Free-Counterexample-to-the-Kadison-Kaplansky-Projection-Conjecture-September-23-2026/paper.pdf"},{"title":"An irrational-trace counterexample to reduced Baum–Connes","path":"preprints/An-Irrational-Trace-Counterexample-to-Reduced-Baum-Connes-September-23-2026/paper.pdf"}]},{"id":"286","title":"Rigidity and arithmetic of lattice von Neumann algebras","desc":"Classifies finite-index bimodules between scalar-twisted group factors of ICC groups commensurable with property-$(T)$ lattices over characteristic-zero local fields and arbitrary ICC group factors. Every such bimodule is a summand of finite sums of models arising from finite-index subgroup isomorphisms and finite-dimensional projective representations. The classification also recovers the group, scalar cocycle and amplification scale up to the stated stable equivalence.","subject":"Operator algebras","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Von Neumann algebras. No route identified.","papers":[{"title":"Arithmeticity of twisted finite correspondences for lattices over local fields","path":"preprints/Arithmeticity-of-twisted-finite-correspondences-for-lattices-over-local-fields-September-23-2026/paper.pdf"},{"title":"The arithmetic category and stable recovery of lattice factors","path":"preprints/The-arithmetic-category-and-stable-recovery-of-lattice-factors-September-23-2026/paper.pdf"}]},{"id":"287","title":"Isomorphism of the free group factors","desc":"Resolves the free group factor isomorphism problem: $L(\\mathbb F_2)\\cong L(\\mathbb F_3)$, and hence all interpolated free group factors, including $L(\\mathbb F_\\infty)$, are isomorphic. Their common factor has fundamental group $\\mathbb R_{\\gt 0}$.","subject":"Operator algebras","lean":1,"applied":1,"difficulty":5,"year":1943,"note":"Von Neumann algebras. No route identified.","papers":[{"title":"An isomorphism of the free group factors","path":"preprints/An-isomorphism-of-the-free-group-factors-September-23-2026/An-isomorphism-of-the-free-group-factors-September-23-2026.pdf"}]},{"id":"288","title":"Kadison&#x27;s similarity conjecture","desc":"Proves Kadison&#x27;s similarity conjecture: every bounded complex-linear unital algebra homomorphism from a unital complex <i>C<\/i><sup>∗<\/sup>-algebra to operators on a Hilbert space becomes a $*$-homomorphism after conjugation by a bounded invertible operator.","subject":"Operator algebras","lean":1,"applied":1,"difficulty":5,"year":1955,"note":"Operator algebras. No route identified.","papers":[{"title":"Kadison&#x27;s similarity theorem through uniform derivation estimates","path":"preprints/Kadisons-similarity-theorem-through-uniform-derivation-estimates-September-23-2026/paper.pdf"}]},{"id":"289","title":"Strong Kadison–Kastler stability and its spatial boundaries","desc":"Proves that sufficiently close unital von Neumann algebras on the same Hilbert space are conjugate by a unitary arbitrarily close to the identity, with a universal tolerance in the operator-norm distance between unit balls. Counterexamples show that near-identity conjugacy fails for one-sided near inclusions, and that arbitrarily close norm-separable <i>C<\/i><sup>∗<\/sup>-algebras need not be ambiently unitarily conjugate.","subject":"Operator algebras","lean":1,"applied":1,"difficulty":4,"year":1972,"note":"Perturbation of operator algebras. No route identified.","papers":[{"title":"Universal strong Kadison–Kastler stability","path":"preprints/Universal-strong-Kadison-Kastler-stability-September-23-2026/paper.pdf"},{"title":"Near Inclusions of von Neumann Algebras Without Small Spatial Embeddings","path":"preprints/Near-Inclusions-of-von-Neumann-Algebras-Without-Small-Spatial-Embeddings-October-5-2026/near-inclusions.pdf"},{"title":"Close Separable C*-Algebras Without Spatial Conjugacy","path":"preprints/Close-Separable-Cstar-Algebras-Without-Spatial-Conjugacy-October-5-2026/paper.pdf"}]},{"id":"290","title":"Relative bicentralizers and modular spectral recovery","desc":"Proves Connes&#x27; bicentralizer conjecture for every type III<sub>1<\/sub> factor with separable predual and every faithful normal state. More generally, for every inclusion $N\\subset M$ of von Neumann algebras with separable preduals admitting a faithful normal conditional expectation, constructs an amenable expected subalgebra $P\\subset N$ with $P&#x27;\\cap c(M)=N&#x27;\\cap c(M)$, resolving the relative bicentralizer conjecture.","subject":"Operator algebras","lean":2,"applied":1,"difficulty":5,"year":null,"note":"Type III factors. No route identified.","papers":[{"title":"Expected amenable subalgebras preserving core commutants","path":"preprints/Expected-amenable-subalgebras-preserving-core-commutants-September-23-2026/Expected-amenable-subalgebras-preserving-core-commutants-September-23-2026.pdf"},{"title":"Bounded recovery for modular spectral averages","path":"preprints/Bounded-recovery-for-modular-spectral-averages-September-23-2026/Bounded-recovery-for-modular-spectral-averages-September-23-2026.pdf"}]},{"id":"291","title":"Cuntz comparison, nuclear dimension, and equivariant Jiang–Su stability","desc":"Proves equivariant Jiang–Su stability for every countable discrete amenable group action on a simple separable unital infinite-dimensional nuclear stably finite Jiang–Su-stable <i>C<\/i><sup>∗<\/sup>-algebra, resolving this case of Szabó&#x27;s conjecture without restrictions on trace dynamics. The family also proves the unital Toms–Winter conjecture, equating strict comparison, finite nuclear dimension and Jiang–Su stability in the simple separable unital infinite-dimensional nuclear setting.","subject":"Operator algebras","lean":2,"applied":1,"difficulty":3,"year":null,"note":"Classification of C*-algebras. No route identified.","papers":[{"title":"Equivariant Jiang–Su Stability for Amenable Actions in the Unital Stably Finite Case","path":"preprints/Equivariant-Jiang-Su-Stability-for-Amenable-Actions-in-the-Unital-Stably-Finite-Case-October-5-2026/paper.pdf"},{"title":"Cuntz comparison and Jiang–Su absorption","path":"preprints/Cuntz-comparison-and-Jiang-Su-absorption-September-23-2026/paper.pdf"},{"title":"Nuclear dimension and Jiang–Su stability without elementary subquotients","path":"preprints/Nuclear-dimension-and-Jiang-Su-stability-without-elementary-subquotients-September-23-2026/paper.pdf"},{"title":"Tracial projection methods and uniform property Gamma","path":"preprints/Tracial-projection-methods-and-uniform-property-Gamma-September-23-2026/paper.pdf"}]},{"id":"292","title":"Kirchberg&#x27;s $\\mathcal O_2$ norm-ultrapower embedding problem","desc":"Constructs an explicit separable unital full group <i>C<\/i><sup>∗<\/sup>-algebra that cannot embed unitally into the norm ultrapower of any fixed nonzero unital nuclear <i>C<\/i><sup>∗<\/sup>-algebra, for any free ultrafilter on the natural numbers. Taking the target to be $\\mathcal O_2$ answers Kirchberg&#x27;s norm-ultrapower embedding problem negatively.","subject":"Operator algebras","lean":1,"applied":1,"difficulty":3,"year":null,"note":"C*-algebras. No route identified.","papers":[{"title":"An explicit obstruction to nuclear norm-ultrapower embeddings","path":"preprints/An-explicit-obstruction-to-nuclear-norm-ultrapower-embeddings-September-23-2026/paper.pdf"}]},{"id":"293","title":"Invariant projections, hyperinvariant subspaces, and transitive algebras","desc":"Constructs a nonzero norm-quasinilpotent operator on every infinite-dimensional separable complex Hilbert space with no nonzero proper closed subspace invariant under every commuting operator. The construction also gives operators with no nontrivial invariant projection in the hyperfinite type II<sub>1<\/sub> factor.","subject":"Operator algebras","lean":2,"applied":1,"difficulty":5,"year":null,"note":"Invariant subspaces. No route identified.","papers":[{"title":"Invariant-projection counterexamples for every irrational rotation","path":"preprints/Invariant-projection-counterexamples-for-every-irrational-rotation-September-27-2026/paper.pdf"},{"title":"Backward intertwiners and a transitive commutant","path":"preprints/Backward-intertwiners-and-a-transitive-commutant-September-27-2026/paper.pdf"}]},{"id":"294","title":"Kaplansky&#x27;s quasitrace conjecture and failure of tensor-product stable finiteness","desc":"Disproves Kaplansky&#x27;s quasitrace conjecture by constructing a separable unital complex <i>C<\/i><sup>∗<\/sup>-algebra admitting normalized 2-quasitraces, all of which are nonadditive. As a consequence, two unital simple stably finite <i>C<\/i><sup>∗<\/sup>-algebras can have a properly infinite minimal tensor product, with one factor $C_r^*(\\mathbb F_2)$.","subject":"Operator algebras","lean":2,"applied":1,"difficulty":5,"year":null,"note":"C*-algebras. No route identified.","papers":[{"title":"A counterexample to Kaplansky&#x27;s quasitrace conjecture and failure of tensor-product stable finiteness","path":"preprints/A-counterexample-to-Kaplanskys-quasitrace-conjecture-September-23-2026/paper.pdf"}]},{"id":"295","title":"The Kadison–Ringrose cohomology conjecture","desc":"Proves that every bounded Hochschild cocycle of degree at least two on a complex von Neumann algebra, with coefficients in the algebra itself, has a bounded primitive. Equivalently, all higher bounded Hochschild cohomology groups vanish, resolving the Kadison–Ringrose conjecture.","subject":"Operator algebras","lean":1,"applied":1,"difficulty":5,"year":1971,"note":"Cohomology of operator algebras. No route identified.","papers":[{"title":"Vanishing of higher bounded Hochschild cohomology","path":"preprints/Vanishing-of-higher-bounded-Hochschild-cohomology-September-23-2026/paper.pdf"}]},{"id":"296","title":"The generator problem for finite factors","desc":"Proves that every type II<sub>1<\/sub> factor with separable predual is generated by a single operator, equivalently by two self-adjoint operators, resolving the generator problem. More strongly, for every irreducible inclusion $P\\subset M$ of such factors, the unitaries <i>u<\/i> with $M=W^*(P,u)$ form a dense <i>G<\/i><sub><i>δ<\/i><\/sub> subset in the trace 2-norm topology.","subject":"Operator algebras","lean":2,"applied":1,"difficulty":5,"year":1967,"note":"Von Neumann algebras. No route identified.","papers":[{"title":"Relative generation and the generator problem for finite factors","path":"preprints/Relative-generation-and-the-generator-problem-for-finite-factors-September-23-2026/paper.pdf"}]},{"id":"297","title":"A ZFC counterexample to Naimark&#x27;s problem","desc":"Gives an alternative to <a href=\"https://arxiv.org/abs/2609.26930v1\">Tanaka&#x27;s ZFC construction<\/a> of a unital infinite-dimensional simple complex <i>C<\/i><sup>∗<\/sup>-algebra with a faithful tracial state and exactly one nonzero irreducible representation up to unitary equivalence. Thus the unrestricted compact-operator characterization fails without additional set-theoretic assumptions; the counterexample is nonseparable.","subject":"Operator algebras","lean":1,"applied":1,"difficulty":2,"year":1951,"note":"C*-algebras. An alternative to a construction already published. No route identified.","papers":[{"title":"A counterexample to Naimark&#x27;s problem in ZFC","path":"preprints/A-counterexample-to-Naimarks-problem-in-ZFC-September-24-2026/naimark-counterexample-zfc.pdf"}]},{"id":"298","title":"Two notions of free entropy differ even when both are finite","desc":"Constructs a bounded self-adjoint tuple in a tracial von Neumann algebra whose microstates and nonmicrostates free entropies satisfy $-\\infty\\lt \\chi\\lt \\chi^*\\lt \\infty$. This answers Voiculescu’s finite-entropy equality question negatively: the matrix-approximation and free-Fisher-information definitions differ even when both are finite.","subject":"Operator algebras","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Free probability. A weak link to random matrix theory.","papers":[{"title":"A finite-entropy separation of microstates and nonmicrostates free entropy","path":"preprints/A-finite-entropy-separation-of-microstates-and-nonmicrostates-free-entropy-September-25-2026/paper.pdf"}]},{"id":"299","title":"The Kirchberg–Rørdam character criterion and infinite tensor-power Jiang–Su stability","desc":"A nonzero unital separable complex <i>C<\/i><sup>∗<\/sup>-algebra is Jiang–Su stable exactly when its norm central-sequence algebra has no characters, for every free ultrafilter. This answers the Kirchberg–Rørdam character question. Also, the infinite minimal tensor power of every such algebra without characters is Jiang–Su stable, answering the Dadarlat–Toms question.","subject":"Operator algebras","lean":2,"applied":1,"difficulty":3,"year":null,"note":"Classification of C*-algebras. No route identified.","papers":[{"title":"The Kirchberg–Rørdam character criterion","path":"preprints/The-Kirchberg-Rordam-character-criterion-September-25-2026/paper.pdf"}]},{"id":"300","title":"Approximation and quadratic strong-operator paving","desc":"Proves that every self-adjoint element of a complex von Neumann algebra admits strong-operator paving relative to any maximal abelian subalgebra with $O(\\varepsilon^{-2})$ blocks. The norm bound holds after compression by a projection arbitrarily close to the identity in the strong topology, resolving the Popa–Vaes quadratic paving conjecture.","subject":"Operator algebras","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Paving in operator algebras. A weak link to frame theory.","papers":[{"title":"Approximation Paving over Arbitrary Maximal Abelian Subalgebras","path":"preprints/Approximation-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026/Approximation-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026.pdf"},{"title":"Quadratic Strong-Operator Paving over Arbitrary Maximal Abelian Subalgebras","path":"preprints/Quadratic-Strong-Operator-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026/Quadratic-Strong-Operator-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026.pdf"}]},{"id":"301","title":"Trace cones and Razak–Jacelon stabilization","desc":"Classifies separable nuclear complex <i>C<\/i><sup>∗<\/sup>-algebras after tensoring with the Razak–Jacelon algebra and the compact operators, using their full topological cones of extended lower-semicontinuous tracial weights. This answers Robert’s trace-cone question, including algebras with arbitrary ideal structure and both finite and infinite subquotients.","subject":"Operator algebras","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Classification of C*-algebras. No route identified.","papers":[{"title":"The trace cone classifies Razak–Jacelon stabilizations","path":"preprints/The-trace-cone-classifies-Razak-Jacelon-stabilizations-September-25-2026/The-trace-cone-classifies-Razak-Jacelon-stabilizations-September-25-2026.pdf"}]},{"id":"302","title":"Radius of comparison equals half the mean dimension","desc":"For every minimal homeomorphism <i>h<\/i> of an infinite compact metrizable space <i>X<\/i>, the radius of comparison of $C(X)\\rtimes_h\\mathbb Z$ equals $\\tfrac12\\mathrm{mdim}(X,h)$, including infinite values. Zero mean dimension is equivalent to the small boundary property, Jiang–Su stability and finite nuclear dimension; in this case nuclear dimension is at most one.","subject":"Operator algebras","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Crossed products and mean dimension. No route identified.","papers":[{"title":"Filtered products and boundary-preserving compression in complex cobordism","path":"preprints/Filtered-products-and-boundary-preserving-compression-in-complex-cobordism-September-25-2026/paper.pdf"},{"title":"Radius of comparison equals half the mean dimension","path":"preprints/Radius-of-comparison-equals-half-the-mean-dimension-September-25-2026/paper.pdf"}]},{"id":"303","title":"Weak pure infiniteness and Cuntz-algebra absorption","desc":"Resolves the ordinary-to-strong pure-infiniteness question of Kirchberg and Rørdam for complex <i>C<\/i><sup>∗<\/sup>-algebras. For exact algebras, proper infiniteness of one fixed finite amplification of every positive element also suffices. Consequently, every separable nuclear algebra with this property absorbs $\\mathcal O_\\infty$, without unitality or simplicity assumptions.","subject":"Operator algebras","lean":1,"applied":1,"difficulty":3,"year":null,"note":"C*-algebras. No route identified.","papers":[{"title":"Weak pure infiniteness and O-infinity absorption","path":"preprints/Weak-pure-infiniteness-and-O-infinity-absorption-September-25-2026/paper.pdf"}]},{"id":"304","title":"The Hilbert–Smith conjecture in every dimension","desc":"Every locally compact second-countable Hausdorff group acting faithfully and jointly continuously on a connected finite-dimensional topological manifold is a Lie group. This proves the Hilbert–Smith conjecture in all finite dimensions, for Hausdorff second-countable manifolds without boundary.","subject":"Topology","lean":0,"applied":1,"difficulty":5,"year":1941,"note":"Transformation groups. No route identified.","papers":[{"title":"The Hilbert–Smith conjecture in every finite dimension","path":"preprints/The-Hilbert-Smith-conjecture-in-every-finite-dimension-September-23-2026/paper.pdf"}]},{"id":"305","title":"Four-dimensional disk embedding and Wall&#x27;s conjecture","desc":"The unrestricted four-dimensional disk-embedding conjecture fails: framed algebraic dual spheres do not suffice to obtain disjoint locally flat spanning disks. In particular, the free group <i>F<\/i><sub>2<\/sub> is not good in the sense of Freedman–Quinn. Also constructs a finitely presented integral Poincaré duality group of dimension four with a finite classifying space but no realization as the fundamental group of a closed aspherical topological four-manifold, disproving Wall&#x27;s conjecture.","subject":"Topology","lean":0,"applied":1,"difficulty":5,"year":1982,"note":"Four-manifold topology. No route identified.","papers":[{"title":"A boundary-only obstruction to four-dimensional disk embedding","path":"preprints/A-boundary-only-obstruction-to-four-dimensional-disk-embedding-September-24-2026/paper.pdf"},{"title":"A marked tensor obstruction to four-dimensional disk embedding","path":"preprints/A-marked-tensor-obstruction-to-four-dimensional-disk-embedding-September-24-2026/paper.pdf"},{"title":"A PD4 group without an aspherical manifold model","path":"preprints/A-PD4-group-without-an-aspherical-manifold-model-September-24-2026/paper.pdf"}]},{"id":"306","title":"The purely cosmetic surgery conjecture","desc":"Distinct Dehn surgery slopes on a nontrivial smooth knot in <i>S<\/i><sup>3<\/sup> never produce orientation-preservingly homeomorphic manifolds, proving the purely cosmetic surgery conjecture. The statement includes the meridional slope.","subject":"Topology","lean":0,"applied":1,"difficulty":4,"year":1990,"note":"Knot theory. No route identified.","papers":[{"title":"Purely cosmetic surgery on knots in the three-sphere","path":"preprints/Purely-Cosmetic-Surgery-on-Knots-in-the-Three-Sphere-September-23-2026/paper.pdf"}]},{"id":"307","title":"Failure of rational injectivity for maximal coarse assembly","desc":"Constructs a uniformly discrete bounded-geometry space whose maximal coarse assembly map is not rationally injective. The example is a coarse disjoint union of finite connected graphs of uniformly bounded degree, with an infinite-order kernel class. A companion gives the analogous failure for reduced coarse assembly, disproving the rational coarse Novikov conjecture.","subject":"Topology","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Coarse geometry. No route identified.","papers":[{"title":"Failure of rational injectivity for maximal coarse assembly","path":"preprints/Failure-of-rational-injectivity-for-maximal-coarse-assembly-October-5-2026/paper.pdf"},{"title":"A counterexample to the coarse Novikov conjecture","path":"preprints/A-counterexample-to-the-coarse-Novikov-conjecture-September-23-2026/paper.pdf"}]},{"id":"308","title":"Finite Smith–Toda complexes at every height","desc":"For every <i>n<\/i> ≥ 0, constructs a finite Smith–Toda spectrum at a prime <i>p<\/i> depending on <i>n<\/i>, with Brown–Peterson homology $BP_*/(p,v_1,\\ldots,v_n)$ and the canonical comodule structure. Thus Smith–Toda complexes exist at every height when the prime may vary; an explicit example realizes $V(4)$ at <i>p<\/i> = 1009.","subject":"Topology","lean":0,"applied":1,"difficulty":4,"year":1971,"note":"Stable homotopy theory. No route identified.","papers":[{"title":"Finite Smith–Toda Complexes at Varying Primes","path":"preprints/Finite-Smith-Toda-Complexes-at-Varying-Primes-September-23-2026/paper.pdf"},{"title":"A finite Smith–Toda complex V(4) at the prime 1009","path":"preprints/A-finite-Smith-Toda-complex-V4-at-the-prime-1009-September-23-2026/paper.pdf"}]},{"id":"309","title":"The Kervaire invariant problem at the prime three","desc":"Resolves the odd-primary Kervaire invariant problem at the prime three: exactly the standard classes with indices 0, 2, and 3 survive in the mod-three Adams spectral sequence, in stems 10, 106, and 322. Each surviving detection coset contains an element of exact additive order three.","subject":"Topology","lean":0,"applied":1,"difficulty":4,"year":1978,"note":"Stable homotopy theory. No route identified.","papers":[{"title":"The Kervaire invariant problem at the prime three","path":"preprints/The-Kervaire-Invariant-Problem-at-the-Prime-Three-September-24-2026/paper.pdf"}]},{"id":"310","title":"Quillen&#x27;s conjecture in rational homology","desc":"Proves the rational-homology form of Quillen&#x27;s conjecture for every finite group and every prime. If the largest normal <i>p<\/i>-subgroup of <i>G<\/i> is trivial, the poset of nontrivial elementary abelian <i>p<\/i>-subgroups has nonzero augmented reduced rational homology and is therefore not contractible.","subject":"Topology","lean":0,"applied":1,"difficulty":5,"year":1978,"note":"Subgroup posets of finite groups. No route identified.","papers":[{"title":"Rational homology and Quillen&#x27;s conjecture","path":"preprints/Rational-homology-and-Quillens-conjecture-September-24-2026/paper.pdf"}]},{"id":"311","title":"The Hovey–Strickland and Chai conjectures","desc":"Proves Chai&#x27;s invariant-ideal conjecture for Lubin–Tate deformation rings over finite residue fields, at every prime and positive height <i>n<\/i>. Through the implication of Barthel–Heard–Naumann, this proves the Hovey–Strickland conjecture: dualizable $K(n)$-local spectra have exactly $n+2$ thick tensor ideals, and their Balmer spectrum is a chain of $n+1$ points.","subject":"Topology","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Chromatic homotopy theory. No route identified.","papers":[{"title":"Stabilizer orbits and thick tensor ideals of dualizable K(n)-local spectra","path":"preprints/Stabilizer-Orbits-and-Thick-Tensor-Ideals-of-Dualizable-Kn-Local-Spectra-September-24-2026/paper.pdf"}]},{"id":"312","title":"The Grothendieck homotopy hypothesis","desc":"Proves the Grothendieck homotopy hypothesis for ∞-groupoids associated with every Grothendieck coherator in the Ara–Henry convention: these algebraic objects recover the homotopy theory of spaces.","subject":"Topology","lean":2,"applied":1,"difficulty":5,"year":1983,"note":"Higher category theory. A weak link to foundations of homotopy type theory.","papers":[{"title":"The Grothendieck homotopy hypothesis via elementary expansions","path":"preprints/The-Grothendieck-homotopy-hypothesis-via-elementary-expansions-September-24-2026/paper.pdf"}]},{"id":"313","title":"Finite generation for the $K(n)$-local sphere","desc":"Answers the degreewise finiteness question of Hovey and Hovey–Strickland: every homotopy group of the $K(n)$-local sphere is a finitely generated ℤ<sub><i>p<\/i><\/sub>-module, for every prime, positive height and integer degree. The same conclusion holds after $K(n)$-localizing any finite <i>p<\/i>-local spectrum.","subject":"Topology","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Chromatic homotopy theory. No route identified.","papers":[{"title":"Finite generation for the K(n)-local sphere","path":"preprints/Finite-generation-for-the-Kn-local-sphere-September-24-2026/Finite-generation-for-the-Kn-local-sphere-September-24-2026.pdf"}]},{"id":"314","title":"Cyclic length and chromatic fixed-point loss","desc":"Determines the optimal chromatic loss from geometric <i>H<\/i>-fixed points to geometric <i>G<\/i>-fixed points for every subgroup <i>H<\/i> of a finite <i>p<\/i>-group <i>G<\/i>. At every nonnegative height, the loss equals the shortest subnormal-chain length from <i>H<\/i> to <i>G<\/i> with cyclic quotients. Each quotient counts once regardless of order, and finite spectra witness sharpness.","subject":"Topology","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Equivariant homotopy theory. No route identified.","papers":[{"title":"Cyclic length and chromatic fixed-point loss","path":"preprints/Cyclic-Length-and-Chromatic-Fixed-Point-Loss-September-24-2026/Cyclic-Length-and-Chromatic-Fixed-Point-Loss-September-24-2026.pdf"}]},{"id":"315","title":"The four-dimensional Singer conjecture","desc":"Proves that the <i>L<\/i><sup>2<\/sup>-Betti numbers of the universal cover of every closed connected aspherical topological four-manifold vanish outside degree two. More generally, the same conclusion holds for every finite connected aspherical integral Poincaré complex of formal dimension four, proving the four-dimensional Singer conjecture in this wider class.","subject":"Topology","lean":0,"applied":1,"difficulty":4,"year":null,"note":"L2 invariants. No route identified.","papers":[{"title":"The Singer conjecture in dimension four","path":"preprints/The-Singer-conjecture-in-dimension-four-September-25-2026/paper.pdf"}]},{"id":"316","title":"Curtis’s conjecture","desc":"Proves Curtis’s conjecture: the positive-degree mod-two stable Hurewicz image of the sphere is spanned by the images of the Hopf-invariant-one classes <i>η<\/i>, <i>ν<\/i>, <i>σ<\/i> and the Kervaire-invariant-one classes that exist.","subject":"Topology","lean":0,"applied":1,"difficulty":4,"year":1975,"note":"Stable homotopy theory. No route identified.","papers":[{"title":"The Stable Hurewicz Image of the Sphere at Two","path":"preprints/The-Stable-Hurewicz-Image-of-the-Sphere-at-Two-September-25-2026/paper.pdf"}]},{"id":"317","title":"Thomason model structures in all strict higher dimensions","desc":"Resolves the Ara–Maltsiniotis conjecture: for every <i>n<\/i> ≥ 1 and <i>n<\/i> = <i>ω<\/i>, small strict globular <i>n<\/i>-categories admit proper combinatorial Thomason model structures Quillen equivalent to simplicial sets. Thus strict higher categories model the homotopy theory of spaces in every stated dimension.","subject":"Topology","lean":1,"applied":1,"difficulty":2,"year":null,"note":"Higher category theory. No route identified.","papers":[{"title":"Thomason Model Structures in Every Strict Higher Dimension","path":"preprints/Thomason-Model-Structures-in-Every-Strict-Higher-Dimension-September-25-2026/paper.pdf"}]},{"id":"318","title":"Chromatic splitting: filtrations and counterexamples","desc":"Disproves strong chromatic splitting at height three for primes <i>p<\/i> ≥ 5, and weak splitting for the derived <i>p<\/i>-completed sphere at heights <i>p<\/i> (<i>p<\/i> ≥ 5) and $p+1$ (<i>p<\/i> ≥ 7). Nevertheless, for <i>n<\/i> ≥ 1 and $p\\gt n+1$, the overlap $L_{n-1}L_{K(n)}S_p^\\wedge$ admits a $2^n$-stage filtration by the predicted localized-sphere pieces. At height three and prime three, even finite assembly from such pieces fails in the category of $E(2)$-local modules over the derived completed sphere.","subject":"Topology","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Chromatic homotopy theory. No route identified.","papers":[{"title":"Filtered chromatic splitting at generic primes","path":"preprints/Filtered-chromatic-splitting-at-generic-primes-September-25-2026/paper.pdf"},{"title":"The height-three chromatic overlap: an explicit filtration and its attachments","path":"preprints/The-height-three-chromatic-overlap-an-explicit-filtration-and-its-attachments-September-27-2026/paper.pdf"},{"title":"A rational obstruction to strong chromatic splitting at height three","path":"preprints/A-rational-obstruction-to-strong-chromatic-splitting-at-height-three-September-25-2026/paper.pdf"},{"title":"Failure of finite assembly for a chromatic overlap at the prime three","path":"preprints/Failure-of-finite-assembly-for-a-chromatic-overlap-at-the-prime-three-September-25-2026/paper.pdf"},{"title":"Counterexamples to weak chromatic splitting: sphere kernels and descent exponents","path":"preprints/Counterexamples-to-weak-chromatic-splitting-sphere-kernels-and-descent-exponents-September-27-2026/paper.pdf"}]},{"id":"319","title":"Counterexamples to finite generation at chromatic height two","desc":"Refutes the Hahn–Wilson conjecture at chromatic height two. For every sufficiently large prime <i>p<\/i>, constructs a connective <i>p<\/i>-complete spectrum of exact fp-type two that cannot be built from completed $\\mathrm{BP}\\langle2\\rangle$ by finitely many sums, shifts, cones and retracts. The examples nevertheless satisfy the finite and telescopic localization comparisons.","subject":"Topology","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Chromatic homotopy theory. No route identified.","papers":[{"title":"Counterexamples to the Hahn-Wilson conjecture at height two","path":"preprints/Counterexamples-to-the-Hahn-Wilson-conjecture-at-height-two-September-26-2026/paper.pdf"}]},{"id":"320","title":"Nonhomeomorphic closed aspherical four-manifolds","desc":"Constructs closed connected aspherical topological four-manifolds that are homotopy equivalent but not homeomorphic, with a common word-hyperbolic fundamental group. This disproves even the homeomorphism-existence formulation of the Borel conjecture in dimension four.","subject":"Topology","lean":0,"applied":1,"difficulty":5,"year":1953,"note":"Topological rigidity. No route identified.","papers":[{"title":"Nonhomeomorphic closed aspherical four-manifolds with the same homotopy type","path":"preprints/Nonhomeomorphic-closed-aspherical-four-manifolds-with-the-same-homotopy-type-October-4-2026/paper.pdf"}]},{"id":"321","title":"A counterexample to Wall&#x27;s finite D(2) problem","desc":"Constructs a finite connected three-dimensional CW complex whose universal cover has no integral homology above degree two and whose third cohomology vanishes for every local coefficient module, but which has no finite two-dimensional homotopy model. This disproves Wall&#x27;s finite D(2) conjecture; the example has infinite fundamental group.","subject":"Topology","lean":0,"applied":1,"difficulty":5,"year":1965,"note":"Low-dimensional homotopy theory. No route identified.","papers":[{"title":"A Counterexample to Wall&#x27;s D(2) Problem","path":"preprints/A-Counterexample-to-Walls-D2-Problem-October-6-2026/wall-d2-counterexample.pdf"}]},{"id":"322","title":"Tingley’s sphere-isometry problem","desc":"Resolves Tingley&#x27;s problem: every surjective isometry between the unit spheres of nonzero real Banach spaces extends uniquely to a surjective real-linear isometry of the whole spaces. No dimension restriction is imposed, so the metric geometry of the unit sphere determines the Banach space up to linear isometry.","subject":"Functional analysis","lean":2,"applied":1,"difficulty":4,"year":1987,"note":"Geometry of Banach spaces. No route identified.","papers":[{"title":"A positive solution to Tingley’s problem","path":"preprints/A-positive-solution-to-Tingleys-problem-September-23-2026/paper.pdf"}]},{"id":"323","title":"Independence of the separable quotient problem","desc":"Establishes, relative to the consistency of a measurable cardinal, that the separable quotient problem is independent of ZFC. The assertion that every infinite-dimensional Banach space has a separable infinite-dimensional quotient can hold for all real and complex Banach spaces, whereas the continuum hypothesis yields counterexamples over both fields.","subject":"Functional analysis","lean":1,"applied":1,"difficulty":5,"year":null,"note":"Banach spaces and set theory. No route identified.","papers":[{"title":"Relative independence of the separable quotient problem","path":"preprints/Relative-independence-of-the-separable-quotient-problem-September-23-2026/paper.pdf"}]},{"id":"324","title":"Lipschitz equivalent Banach spaces need not be linearly isomorphic","desc":"Constructs separable real Banach spaces that are globally bi-Lipschitz equivalent but not linearly isomorphic, resolving the separable Lipschitz-isomorphism problem negatively. Thus even the complete metric structure up to bi-Lipschitz equivalence does not determine a separable Banach space&#x27;s linear isomorphism class.","subject":"Functional analysis","lean":2,"applied":1,"difficulty":4,"year":null,"note":"Nonlinear geometry of Banach spaces. No route identified.","papers":[{"title":"Lipschitz Equivalent Separable Banach Spaces Need Not Be Linearly Isomorphic","path":"preprints/Lipschitz-Equivalent-Separable-Banach-Spaces-Need-Not-Be-Linearly-Isomorphic-September-24-2026/paper.pdf"},{"title":"Bi-Lipschitz Absorption of c0 Without a Linear Copy of c0","path":"preprints/Bi-Lipschitz-Absorption-of-c0-Without-a-Linear-Copy-of-c0-September-26-2026/paper.pdf"}]},{"id":"325","title":"The complete Crouzeix conjecture","desc":"Resolves the complete Crouzeix conjecture: for every bounded operator <i>A<\/i> on a complex Hilbert space and every finite matrix-valued polynomial <i>P<\/i>, one has $\\lVert P[A]\\rVert\\le2\\sup_{z\\in W(A)}\\lVert P(z)\\rVert$, where $W(A)$ is the numerical range. The constant 2 is sharp, independent of the matrix size, and valid in infinite dimensions.","subject":"Functional analysis","lean":2,"applied":4,"difficulty":4,"year":2004,"note":"The Crouzeix bound controls functions of a matrix by their values on the numerical range. Convergence estimates for GMRES and matrix-function approximation use it; the constant drops from 1 + √2 to 2.","papers":[{"title":"A direct proof of the complete Crouzeix inequality","path":"preprints/A-direct-proof-of-the-complete-Crouzeix-inequality-September-26-2026/paper.pdf"},{"title":"The complete Crouzeix theorem: optimal similarity and a common positive boundary representation","path":"preprints/The-complete-Crouzeix-theorem-September-23-2026/paper.pdf"}]},{"id":"326","title":"The cotype–cotype conjecture under the approximation property","desc":"Resolves the cotype–cotype conjecture for real Banach spaces with the approximation property. Such a nonzero space is <i>K<\/i>-convex if and only if both it and its dual have finite Rademacher cotype, with possibly different exponents. Equivalently, these cotype assumptions force nontrivial Rademacher type.","subject":"Functional analysis","lean":2,"applied":1,"difficulty":3,"year":null,"note":"Banach space geometry. No route identified.","papers":[{"title":"The cotype–cotype conjecture under the approximation property","path":"preprints/The-cotype-cotype-conjecture-under-the-approximation-property-September-23-2026/paper.pdf"}]},{"id":"327","title":"Markov type characterizes superreflexivity","desc":"Proves that every real Banach space with Markov type <i>p<\/i> for some <i>p<\/i> &gt; 1 admits an equivalent uniformly convex norm, answering Naor&#x27;s renorming question. Together with the known converse, this characterizes superreflexivity by nontrivial Markov type.","subject":"Functional analysis","lean":2,"applied":1,"difficulty":3,"year":null,"note":"Metric geometry of Banach spaces. No route identified.","papers":[{"title":"Nontrivial Markov Type Forces Superreflexivity","path":"preprints/Nontrivial-Markov-Type-Forces-Superreflexivity-September-23-2026/paper.pdf"}]},{"id":"328","title":"Nonexpansive fixed points in reflexive Banach spaces","desc":"Resolves Kirk&#x27;s reflexive-space fixed-point problem: every nonexpansive selfmap of a nonempty closed bounded convex subset of a real reflexive Banach space has a fixed point. The result uses the original norm, without assuming uniform convexity.","subject":"Functional analysis","lean":2,"applied":2,"difficulty":5,"year":1965,"note":"Existence of fixed points for nonexpansive maps underlies iterative splitting methods outside Hilbert space. The theorem is existence only.","papers":[{"title":"Fixed Points of Nonexpansive Maps in Reflexive Banach Spaces","path":"preprints/Fixed-Points-of-Nonexpansive-Maps-in-Reflexive-Banach-Spaces-September-24-2026/paper.pdf"}]},{"id":"329","title":"A counterexample to metric-entropy duality","desc":"Disproves Pietsch&#x27;s dimension-free duality conjecture for metric entropy. Origin-symmetric convex bodies violate every proposed choice of universal constants in the conjectured comparison between covering numbers and those of the polar bodies, even when the covering body is a cube.","subject":"Functional analysis","lean":2,"applied":2,"difficulty":4,"year":1972,"note":"Duality of covering numbers is used in learning-theory bounds. The dimension-free form fails.","papers":[{"title":"Counterexamples to the duality conjecture for metric entropy","path":"preprints/Counterexamples-to-the-duality-conjecture-for-metric-entropy-September-24-2026/main.pdf"}]},{"id":"330","title":"A uniformly discrete counterexample to bounded approximation in Lipschitz-free spaces","desc":"Constructs a countable uniformly discrete metric space whose real Lipschitz-free Banach space has the approximation property but not the bounded approximation property, answering Kalton&#x27;s question negatively. Finite-rank operators approximate the identity on every compact set, but their norms cannot share a finite bound.","subject":"Functional analysis","lean":1,"applied":1,"difficulty":2,"year":null,"note":"Lipschitz-free spaces. No route identified.","papers":[{"title":"A uniformly discrete counterexample to bounded approximation in Lipschitz-free spaces","path":"preprints/Failure-of-Bounded-Approximation-in-a-Lipschitz-Free-Space-over-a-Uniformly-Discrete-Metric-Space-September-26-2026/main.pdf"}]},{"id":"331","title":"Reflexive midpoint convexity and diamond distortion","desc":"Constructs a real reflexive Banach space with an asymptotically midpoint uniformly convex norm but no equivalent asymptotically uniformly convex norm, extending Baudier&#x27;s separation to reflexive spaces. In the same space, depth-<i>k<\/i> countably branching diamonds require distortion at least $\\sqrt{1+k/12}$, so midpoint uniform convexity does not force uniformly bounded diamond distortion even under reflexivity.","subject":"Functional analysis","lean":2,"applied":1,"difficulty":2,"year":null,"note":"Banach space geometry. No route identified.","papers":[{"title":"Asymptotic midpoint uniform convexity and unbounded diamond distortion in a reflexive tree space","path":"preprints/Asymptotic-midpoint-uniform-convexity-and-unbounded-diamond-distortion-in-a-reflexive-tree-space-September-27-2026/manuscript.pdf"},{"title":"Midpoint lenses in segment spaces","path":"preprints/Midpoint-lenses-in-segment-spaces-September-27-2026/manuscript.pdf"},{"title":"Distortion of countably branching diamonds from midpoint and tree energies","path":"preprints/Diamond-distortion-from-midpoint-and-tree-energies-September-27-2026/manuscript.pdf"},{"title":"Exact asymptotic moduli in a Daugavet subspace of L1","path":"preprints/Exact-asymptotic-moduli-in-a-Daugavet-subspace-of-L1-September-27-2026/manuscript.pdf"},{"title":"Midpoint convexity from bounded tree potentials and path costs","path":"preprints/Midpoint-convexity-from-bounded-tree-potentials-and-path-costs-September-27-2026/manuscript.pdf"},{"title":"Independent products in real L1: asymptotic midpoint convexity without AUC renormings","path":"preprints/Independent-products-in-real-L1-asymptotic-midpoint-convexity-without-AUC-renormings-September-27-2026/manuscript.pdf"},{"title":"Midpoint convexity from two recursive potentials","path":"preprints/Midpoint-convexity-from-two-recursive-potentials-September-27-2026/manuscript.pdf"}]},{"id":"332","title":"Metric Markov cotype of <i>ℓ<\/i><sub>1<\/sub> and Hilbert-space Lipschitz extension","desc":"Proves that real <i>ℓ<\/i><sub>1<\/sub> has metric Markov cotype two, answering Mendel and Naor&#x27;s question. Consequently, every Lipschitz map from an arbitrary subset of a real Hilbert space into <i>ℓ<\/i><sub>1<\/sub> extends to the whole space with a universal multiplicative loss in its Lipschitz constant, resolving Ball&#x27;s extension problem for this target.","subject":"Functional analysis","lean":0,"applied":2,"difficulty":3,"year":null,"note":"Extension of Lipschitz maps from Hilbert space into L1. An indirect link to metric embedding methods.","papers":[{"title":"Metric Markov Cotype Two of <i>ℓ<\/i><sub>1<\/sub>","path":"preprints/Metric-Markov-Cotype-Two-of-l1-October-5-2026/l1-markov-cotype.pdf"}]},{"id":"333","title":"Smooth isometric immersions of surfaces into ℝ<sup>4<\/sup>","desc":"Every closed smooth Riemannian surface admits a smooth isometric immersion into ℝ<sup>4<\/sup>, resolving the closed-surface form of the four-dimensional isometric-immersion problem. This includes nonorientable surfaces and metrics of arbitrary Gaussian curvature.","subject":"Differential geometry","lean":1,"applied":1,"difficulty":4,"year":null,"note":"Isometric immersions. No route identified.","papers":[{"title":"Smooth isometric immersions of closed surfaces into Euclidean four-space","path":"preprints/Smooth-isometric-immersions-of-closed-surfaces-into-Euclidean-four-space-September-23-2026/paper.pdf"}]},{"id":"334","title":"A smooth surface metric with no local isometric immersion in ℝ<sup>3<\/sup>","desc":"Constructs a smooth positive-definite metric on $(-1,1)^2$ for which no neighborhood of the origin admits a smooth isometric immersion into ℝ<sup>3<\/sup>. This answers the unrestricted smooth local isometric realization problem for surfaces negatively, even after shrinking the neighborhood.","subject":"Differential geometry","lean":2,"applied":1,"difficulty":5,"year":null,"note":"Isometric embedding of surfaces. A weak link to shape modelling.","papers":[{"title":"A Smooth Metric with No Local Isometric Immersion into Three-Space","path":"preprints/A-Smooth-Metric-with-No-Local-Isometric-Immersion-into-Three-Space-September-24-2026/paper.pdf"}]},{"id":"335","title":"Gromov’s integral scalar-curvature bound for simplicial volume","desc":"Proves $\\int_M(\\mathrm{Scal}_g^-)^{n/2}\\,dV_g\\ge a_n\\lVert M\\rVert$ for every closed connected oriented smooth <i>n<\/i>-manifold, <i>n<\/i> ≥ 3, and every smooth metric, with $a_n\\gt 0$ depending only on dimension. Here $\\mathrm{Scal}_g^-=\\max\\{0,-\\mathrm{Scal}_g\\}$ and $\\lVert M\\rVert$ is real simplicial volume. Also proves rational inessentiality under positive scalar curvature, resolving the Gromov–Lawson conjecture; every nonnegative-scalar-curvature metric on a closed aspherical manifold is flat.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Scalar curvature. No route identified.","papers":[{"title":"An integral scalar curvature bound for real simplicial volume","path":"preprints/An-integral-scalar-curvature-bound-for-real-simplicial-volume-October-5-2026/v126-proof.pdf"},{"title":"Positive scalar curvature forces rational inessentiality","path":"preprints/Positive-scalar-curvature-forces-rational-inessentiality-September-23-2026/paper.pdf"}]},{"id":"336","title":"Spectral scalar curvature, Urysohn width, and macroscopic dimension","desc":"Every complete connected smooth boundaryless <i>n<\/i>-manifold, <i>n<\/i> ≥ 3, satisfying $-4\\Delta+\\mathrm{Scal}\\ge1$ as a quadratic-form inequality admits a continuous map to a simplicial complex of dimension at most $n-2$ whose entire fibers have diameter bounded only by <i>n<\/i> in the original metric. This strengthens Gromov&#x27;s width conclusion to spectral scalar curvature. Universal covers of closed positive-scalar-curvature manifolds also have continuous macroscopic dimension at most $n-2$ for every <i>n<\/i> ≥ 2.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Scalar curvature. No route identified.","papers":[{"title":"Spectral scalar curvature and uniform Urysohn width","path":"preprints/Spectral-scalar-curvature-and-uniform-Urysohn-width-October-5-2026/main.pdf"},{"title":"Spectral scalar curvature and Urysohn width in dimension three","path":"preprints/Spectral-scalar-curvature-and-Urysohn-width-in-dimension-three-October-5-2026/spectral-urysohn-three-manifolds.pdf"},{"title":"Positive scalar curvature and uniform codimension-two width","path":"preprints/Positive-scalar-curvature-and-uniform-codimension-two-width-September-23-2026/paper.pdf"}]},{"id":"337","title":"Sharp Cartan–Hadamard isoperimetry and rigidity","desc":"Proves generalized Cartan–Hadamard isoperimetry in every dimension: in a complete simply connected manifold with sectional curvature at most <i>κ<\/i> ≤ 0, every finite-volume finite-perimeter set satisfies the sharp comparison with the equal-volume model ball. Bounded positive-volume equality regions for <i>κ<\/i> = 0 are Euclidean balls. Also proves sharp Euclidean filling bounds for compactly supported integral <i>n<\/i>-cycles, <i>n<\/i> ≥ 2, in arbitrary proper CAT$(0)$ spaces.","subject":"Differential geometry","lean":1,"applied":1,"difficulty":5,"year":1976,"note":"Isoperimetric inequalities in negative curvature. No route identified.","papers":[{"title":"Generalized Cartan–Hadamard isoperimetry and Euclidean equality rigidity","path":"preprints/Generalized-Cartan-Hadamard-isoperimetry-and-Euclidean-equality-rigidity-September-23-2026/paper.pdf"},{"title":"Sharp integral fillings in CAT(0) spaces","path":"preprints/Sharp-integral-fillings-in-CAT(0"}]},{"id":"338","title":"Yau&#x27;s uniformization conjecture","desc":"Proves Yau&#x27;s uniformization conjecture: every complete connected noncompact Kähler manifold with strictly positive holomorphic bisectional curvature is biholomorphic to ℂ<sup><i>n<\/i><\/sup>.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":5,"year":1974,"note":"Kähler geometry. No route identified.","papers":[{"title":"Uniformization of complete Kähler manifolds with positive bisectional curvature","path":"preprints/Uniformization-of-complete-Kahler-manifolds-with-positive-bisectional-curvature-September-23-2026/paper.pdf"}]},{"id":"339","title":"Katok&#x27;s entropy rigidity conjecture","desc":"Proves Katok&#x27;s entropy rigidity conjecture for closed connected Riemannian manifolds of dimension at least three with strictly negative sectional curvature: normalized Liouville measure maximizes entropy for the geodesic flow if and only if the metric is locally symmetric.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":4,"year":1982,"note":"Geodesic flows. No route identified.","papers":[{"title":"Entropy equality and local symmetry in negative curvature","path":"preprints/Entropy-equality-and-local-symmetry-in-negative-curvature-September-23-2026/paper.pdf"}]},{"id":"340","title":"A counterexample to the nearby Lagrangian conjecture","desc":"Disproves the unrestricted nearby Lagrangian conjecture. For some sufficiently large even <i>N<\/i>, constructs a closed exact embedded Lagrangian in $T^*(S^9\\times S^{N-1})$ that is diffeomorphic to the base but not Hamiltonian isotopic to its zero section.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":4,"year":1986,"note":"Symplectic topology. No route identified.","papers":[{"title":"A counterexample to the nearby Lagrangian conjecture","path":"preprints/A-counterexample-to-the-nearby-Lagrangian-conjecture-September-23-2026/paper.pdf"}]},{"id":"341","title":"Donaldson&#x27;s hypersymplectic deformation conjecture","desc":"Proves Donaldson&#x27;s hypersymplectic deformation conjecture in a cohomology-preserving form. Every positive triple of smooth closed two-forms on a closed connected oriented four-manifold, normalized by $\\int\\omega_i\\wedge\\omega_j=\\delta_{ij}$, deforms through positive closed triples to a hyperkähler triple while preserving all three cohomology classes. Any positive triple can first be normalized by a constant linear change.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":3,"year":2006,"note":"Four-dimensional geometry. No route identified.","papers":[{"title":"Deforming hypersymplectic four-manifolds to hyperkähler triples","path":"preprints/Deforming-hypersymplectic-four-manifolds-to-hyperkahler-triples-September-23-2026/paper.pdf"}]},{"id":"342","title":"Donaldson&#x27;s tamed-to-compatible conjecture","desc":"Proves Donaldson&#x27;s tamed-to-compatible conjecture: every smooth almost complex structure on a closed four-manifold that is tamed by a symplectic form admits a compatible symplectic form. The almost complex structure stays fixed; the form&#x27;s cohomology class may change.","subject":"Differential geometry","lean":2,"applied":1,"difficulty":3,"year":2006,"note":"Symplectic geometry. No route identified.","papers":[{"title":"Taming implies compatibility on four-manifolds","path":"preprints/Taming-implies-compatibility-on-four-manifolds-September-23-2026/paper.pdf"}]},{"id":"343","title":"Symplectic ball packing in higher dimensions","desc":"Resolves the Siegel–Yao conjecture for arbitrary capacities in every dimension $2n\\ge6$. Finitely many closed symplectic balls of capacities $R_1,\\ldots,R_k$ embed disjointly into an open ball of capacity <i>R<\/i> exactly when $\\sum_iR_i^n\\lt R^n$ and $R_i+R_j\\lt R$ for every distinct pair <i>i<\/i>, <i>j<\/i>.","subject":"Differential geometry","lean":1,"applied":1,"difficulty":2,"year":null,"note":"Symplectic packing. No route identified.","papers":[{"title":"Symplectic Ball Packings in Higher Dimensions","path":"preprints/Symplectic-Ball-Packings-in-Higher-Dimensions-September-23-2026/paper.pdf"}]},{"id":"344","title":"The metric Blaschke conjecture","desc":"Proves the metric Blaschke conjecture: every closed connected Riemannian manifold of positive dimension whose injectivity radius equals its diameter is, up to scaling, a standard compact rank-one symmetric space.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":5,"year":1921,"note":"Riemannian geometry. No route identified.","papers":[{"title":"The metric Blaschke theorem","path":"preprints/The-metric-Blaschke-theorem-September-23-2026/paper.pdf"}]},{"id":"345","title":"Infinitely many closed geodesics on Riemannian spheres and closed three-manifolds","desc":"Proves that every smooth Riemannian metric on <i>S<\/i><sup><i>n<\/i><\/sup>, <i>n<\/i> ≥ 2, has infinitely many prime closed geodesics with pairwise distinct images. The same conclusion holds on every closed manifold admitting a finite smooth spherical cover and on every closed three-manifold, without orientability or nondegeneracy restrictions.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":5,"year":null,"note":"Closed geodesics. No route identified.","papers":[{"title":"Infinitely many closed geodesic images on every Riemannian sphere","path":"preprints/Infinitely-many-closed-geodesic-images-on-every-Riemannian-sphere-September-24-2026/paper.pdf"}]},{"id":"346","title":"Sharp singular-set bounds for stationary integral varifolds","desc":"Proves that every stationary integral <i>m<\/i>-varifold in a Euclidean open set has singular set of Hausdorff dimension at most $m-1$, a sharp bound in every positive dimension and codimension. On round spheres, the family also proves almost-everywhere regularity: the singular set has zero <i>m<\/i>-dimensional Hausdorff measure.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":5,"year":1972,"note":"Regularity of minimal surfaces. A weak link to soap-film models.","papers":[{"title":"A Codimension-One Bound for the Singular Set of a Stationary Integral Varifold","path":"preprints/A-Codimension-One-Bound-for-the-Singular-Set-of-a-Stationary-Integral-Varifold-October-5-2026/varifold-singular-dimension.pdf"},{"title":"Almost-everywhere regularity of stationary integral varifolds","path":"preprints/Almost-everywhere-regularity-of-stationary-integral-varifolds-September-23-2026/paper.pdf"}]},{"id":"347","title":"Counterexamples to stable-Morse and strong Arnold fixed-point bounds","desc":"Disproves stable-Morse lower bounds for nondegenerate Hamiltonian fixed points: on simply connected closed Kähler manifolds of real dimension 22, the deficit below the stable Morse number is unbounded. A separate Hamiltonian diffeomorphism of the complex quadric threefold has exactly three fixed points, fewer than the four critical points required of every smooth function.","subject":"Differential geometry","lean":2,"applied":1,"difficulty":3,"year":null,"note":"Hamiltonian dynamics. No route identified.","papers":[{"title":"Hamiltonian Fixed Points Below the Stable Morse Number in Dimension Twenty-Two","path":"preprints/Hamiltonian-Fixed-Points-Below-the-Stable-Morse-Number-in-Dimension-Twenty-Two-October-5-2026/hamiltonian-fixed-points-below-stable-morse-number.pdf"},{"title":"Sharpness of the Cyclic Integral Floer Bound Below the Stable Morse Number","path":"preprints/Sharpness-of-the-Cyclic-Integral-Floer-Bound-Below-the-Stable-Morse-Number-October-5-2026/sharp-cyclic-integral-floer-bound-below-stable-morse-number.pdf"},{"title":"Hamiltonian Fixed Points Below the Stable Morse Number","path":"preprints/Hamiltonian-Fixed-Points-Below-the-Stable-Morse-Number-October-5-2026/paper.pdf"},{"title":"A nondegenerate counterexample to the Morse-number Arnold bound","path":"preprints/A-nondegenerate-counterexample-to-the-Morse-number-Arnold-bound-September-23-2026/paper.pdf"},{"title":"Three fixed points on the symplectic quadric threefold","path":"preprints/A-degenerate-counterexample-to-the-critical-number-Arnold-bound-September-23-2026/paper.pdf"}]},{"id":"348","title":"Nonnegative-curvature Einstein classification and an <i>L<\/i><sup>2<\/sup> topological gap","desc":"Classifies closed connected Einstein four-manifolds with positive Einstein constant and nonnegative sectional curvature: up to scaling, their universal Riemannian covers are the round <i>S<\/i><sup>4<\/sup>, Fubini–Study $\\mathbb{CP}^2$, or a product of equal round two-spheres. A closed simply connected nonnegatively curved four-manifold is diffeomorphic to one of these whenever the scale-invariant <i>L<\/i><sup>2<\/sup> norm of its trace-free Ricci curvature lies below a universal positive constant.","subject":"Differential geometry","lean":1,"applied":1,"difficulty":3,"year":null,"note":"Einstein manifolds. No route identified.","papers":[{"title":"Zero-Plane Rigidity for Einstein Four-Manifolds","path":"preprints/Zero-Plane-Rigidity-for-Einstein-Four-Manifolds-October-4-2026/einstein-boundary.pdf"},{"title":"An L² Einstein Gap for Nonnegatively Curved Four-Manifolds","path":"preprints/An-L2-Einstein-Gap-for-Nonnegatively-Curved-Four-Manifolds-October-5-2026/einstein-gap.pdf"},{"title":"Positively curved Einstein four-manifolds","path":"preprints/Positively-curved-Einstein-four-manifolds-September-23-2026/paper.pdf"}]},{"id":"349","title":"The Solomon–Yau least-volume conjecture","desc":"Proves the Solomon–Yau least-volume conjecture for minimal hypersurfaces of round spheres. For every <i>m<\/i> ≥ 2, a closed connected minimal immersion into the unit sphere $S^{m+1}$ with non-totally-geodesic image has volume at least that of the smallest minimal Clifford product, counting covering multiplicity.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Minimal hypersurfaces. No route identified.","papers":[{"title":"The Solomon–Yau least-volume theorem","path":"preprints/The-Solomon-Yau-least-volume-theorem-September-23-2026/paper.pdf"}]},{"id":"350","title":"Yau’s nodal bounds: surfaces and higher dimensions","desc":"Proves the sharp $C\\sqrt\\lambda$ upper bound for nodal length on every fixed smooth closed surface, completing Yau&#x27;s conjecture there. The upper bound fails for fixed smooth metrics in dimensions three and four, including metrics on <i>S<\/i><sup>3<\/sup> arbitrarily close to round. In dimension five, nodal measure can grow faster than $\\lambda^{1/2+\\varepsilon_0}$ for some fixed $\\varepsilon_0\\gt 0$, ruling out even arbitrarily small power losses.","subject":"Differential geometry","lean":2,"applied":1,"difficulty":4,"year":1982,"note":"Nodal sets of eigenfunctions. A weak link to spectral geometry of vibrating surfaces.","papers":[{"title":"Sharp nodal length on smooth surfaces","path":"preprints/Sharp-nodal-length-on-smooth-surfaces-September-23-2026/paper.pdf"},{"title":"Smooth counterexamples to Yau&#x27;s nodal upper bound in dimensions three and four","path":"preprints/Smooth-counterexamples-to-Yaus-nodal-upper-bound-in-dimensions-three-and-four-September-23-2026/paper.pdf"},{"title":"Power-law violations of Yau&#x27;s nodal upper bound","path":"preprints/Power-law-violations-of-Yaus-nodal-upper-bound-September-23-2026/paper.pdf"}]},{"id":"351","title":"Scalar curvature and finite-time Ricci-flow singularities","desc":"Proves that a smooth Ricci flow on a closed four-manifold extends past any finite time at which scalar curvature remains uniformly bounded. A higher-dimensional counterexample has bounded scalar curvature but unbounded full curvature at its finite maximal time, disproving the unrestricted scalar-curvature extension conjecture.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":4,"year":null,"note":"Ricci flow. No route identified.","papers":[{"title":"A closed Ricci flow with bounded scalar curvature and finite-time curvature blowup","path":"preprints/A-closed-Ricci-flow-with-bounded-scalar-curvature-and-finite-time-curvature-blowup-September-24-2026/paper.pdf"},{"title":"Bounded scalar curvature and smooth extension of four-dimensional Ricci flow","path":"preprints/Bounded-scalar-curvature-and-smooth-extension-of-four-dimensional-Ricci-flow-September-24-2026/paper.pdf"},{"title":"Path selection and an elliptic inequality on degenerating Ricci-flat trees","path":"preprints/Path-selection-and-an-elliptic-inequality-on-degenerating-Ricci-flat-trees-September-24-2026/paper.pdf"}]},{"id":"352","title":"A finite-time singularity of Calabi flow","desc":"Disproves Chen&#x27;s smooth long-time existence conjecture for Calabi flow by constructing a smooth $U(10)$-invariant Kähler metric on $\\mathbb{CP}^{10}$ whose flow develops a finite-time singularity. The metric lies in the Fubini–Study class, so the failure occurs even in a class containing a constant-scalar-curvature metric.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Calabi flow. No route identified.","papers":[{"title":"A finite-time singularity of Calabi flow on projective space","path":"preprints/A-finite-time-singularity-of-Calabi-flow-on-projective-space-September-24-2026/paper.pdf"}]},{"id":"353","title":"Affine Bernstein rigidity through dimension nine and a smooth dimension-ten counterexample","desc":"Proves that every smooth locally uniformly convex affine-maximal graph of dimension three through nine, complete for its induced Euclidean metric, is an elliptic paraboloid. A smooth entire nonquadratic example in dimension ten makes this range sharp. In dimensions three through nine, the paraboloid classification also holds for connected open locally uniformly convex affine-maximal hypersurfaces complete for the affine Berwald–Blaschke metric.","subject":"Differential geometry","lean":1,"applied":1,"difficulty":4,"year":null,"note":"Affine differential geometry. No route identified.","papers":[{"title":"A Smooth Nonquadratic Entire Affine Maximal Graph in Dimension Ten","path":"preprints/Smooth-Nonquadratic-Affine-Maximal-Graph-in-Dimension-Ten-October-5-2026/affine-maximal-dimension-ten.pdf"},{"title":"The affine Bernstein theorem in dimensions three through nine","path":"preprints/The-affine-Bernstein-theorem-in-dimensions-three-through-nine-September-24-2026/main.pdf"}]},{"id":"354","title":"The isoperimetric profile of the cubic three-torus","desc":"Determines the isoperimetric profile of the unit cubic flat three-torus and classifies every finite-perimeter minimizer: balls, circular tubes around shortest closed geodesics, coordinate slabs, and their complements. The transition volumes are $4\\pi/81$ and $1/\\pi$, with exactly the adjacent two types minimizing at each transition.","subject":"Differential geometry","lean":1,"applied":2,"difficulty":4,"year":null,"note":"The periodic isoperimetric problem models the sphere, cylinder and lamella morphologies of phase-separated materials.","papers":[{"title":"The Isoperimetric Conjecture for the Cubic Flat Three-Torus","path":"preprints/The-Isoperimetric-Conjecture-for-the-Cubic-Flat-Three-Torus-September-24-2026/article.pdf"}]},{"id":"355","title":"Unique tangent flows at the first surface singularity","desc":"Proves the first-singular-time case of tangent-flow uniqueness for smooth compact connected embedded surfaces without boundary in ℝ<sup>3<\/sup>. At every singular point, all fixed-center backward tangent flows agree as area measures at every negative time in the original ambient coordinates, without mean-convexity or a prescribed tangent model.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":3,"year":null,"note":"Mean curvature flow. A weak link to interface evolution models.","papers":[{"title":"Uniqueness of tangent flows at the first singular time of embedded surface mean-curvature flow","path":"preprints/Tangent-flow-uniqueness-2026-09-24/paper.pdf"}]},{"id":"356","title":"Gigli’s characterization of Alexandrov curvature","desc":"Proves Gigli&#x27;s conjecture: in every integer dimension <i>n<\/i> ≥ 2, Alexandrov curvature at least <i>κ<\/i> is characterized by the full-support $\\mathop{\\mathrm{RCD}}\\nolimits ((n-1)\\kappa,n)$ condition with reference measure $\\mathcal H^n$ and distributional sectional curvature at least <i>κ<\/i> in the original global test classes. The RCD condition is unreduced.","subject":"Differential geometry","lean":2,"applied":1,"difficulty":2,"year":null,"note":"Metric measure geometry. No route identified.","papers":[{"title":"Gigli’s distributional curvature characterization of Alexandrov spaces","path":"preprints/Giglis-distributional-curvature-characterization-of-Alexandrov-spaces-September-24-2026/main.pdf"},{"title":"Weak Hessian bounds along every geodesic in RCD spaces","path":"preprints/Weak-Hessian-bounds-along-every-geodesic-in-RCD-spaces-September-24-2026/weak-hessian-geodesics.pdf"}]},{"id":"357","title":"Bi-Lipschitz coordinates at every regular RCD point","desc":"Proves that every regular point of a noncollapsed $\\mathop{\\mathrm{RCD}}\\nolimits (K,n)$ space, for <i>K<\/i> ∈ ℝ and integer <i>n<\/i> ≥ 2, has an open neighborhood bi-Lipschitz to an open subset of ℝ<sup><i>n<\/i><\/sup>. Regularity requires all pointed tangents to be Euclidean, the reference measure is exactly $\\mathcal H^n$, and the chart compares ambient distances with a point-dependent finite constant.","subject":"Differential geometry","lean":0,"applied":1,"difficulty":2,"year":null,"note":"Metric measure geometry. No route identified.","papers":[{"title":"Bi-Lipschitz Coordinates at Regular Points of Noncollapsed RCD Spaces","path":"preprints/Bi-Lipschitz-Coordinates-at-Regular-Points-of-Noncollapsed-RCD-Spaces-September-25-2026/paper.pdf"}]},{"id":"358","title":"A three-manifold without conjugate points or nonpositive curvature","desc":"Constructs a closed connected orientable smooth three-manifold that admits a metric without conjugate points but no metric of nonpositive sectional curvature. This answers negatively, already in dimension three, whether the first metric-existence property implies the second.","subject":"Differential geometry","lean":2,"applied":1,"difficulty":3,"year":null,"note":"Riemannian geometry. No route identified.","papers":[{"title":"A Three-Manifold Without Conjugate Points and Without a Nonpositively Curved Metric","path":"preprints/A-Three-Manifold-Without-Conjugate-Points-and-Without-a-Nonpositively-Curved-Metric-September-24-2026/paper.pdf"}]},{"id":"359","title":"Negative Kähler curvature without bounded holomorphic coordinates","desc":"Constructs a contractible domain in ℂ<sup>3<\/sup> with a complete negatively pinched Kähler metric but no bounded holomorphic coordinates, disproving bounded-domain uniformization in this setting. A higher-dimensional example has sectional curvature at most −1 and only constant bounded holomorphic functions; its curvature is not bounded below.","subject":"Differential geometry","lean":2,"applied":1,"difficulty":2,"year":null,"note":"Kähler geometry. No route identified.","papers":[{"title":"A negatively pinched Kähler threefold without bounded holomorphic coordinates","path":"preprints/A-negatively-pinched-Kahler-threefold-without-bounded-holomorphic-coordinates-September-25-2026/paper.pdf"},{"title":"One-sided negative sectional curvature and the holomorphic Liouville property","path":"preprints/One-sided-negative-sectional-curvature-and-the-holomorphic-Liouville-property-September-25-2026/paper.pdf"}]},{"id":"360","title":"Weak MTW curvature gives convexity and regular optimal transport","desc":"On every closed connected Riemannian manifold of dimension at least two satisfying weak Ma–Trudinger–Wang curvature, all tangent injectivity domains are convex, resolving Villani’s conjecture in this setting. For squared-distance transport between measurable probability densities bounded above and away from zero, the optimal map and its inverse are Hölder continuous.","subject":"Differential geometry","lean":2,"applied":3,"difficulty":3,"year":2008,"note":"Regularity of optimal transport maps on curved domains, which decides when numerical transport returns a smooth map.","papers":[{"title":"Global Support and Convex Injectivity Domains under Weak MTW","path":"preprints/Global-Support-and-Convex-Injectivity-Domains-under-Weak-MTW-September-25-2026/paper.pdf"},{"title":"Uniform Bi-Holder Transport from Weak MTW","path":"preprints/Uniform-Bi-Holder-Transport-from-Weak-MTW-September-25-2026/paper.pdf"}]},{"id":"361","title":"Failure of integer-degree harmonic dimension comparison","desc":"Disproves Yau&#x27;s proposed Euclidean dimension bound for harmonic functions of integer growth on manifolds with nonnegative Ricci curvature. For every sufficiently large integer <i>k<\/i>, a complete smooth metric on ℝ<sup>3<\/sup> has at least $(k+2)^2$ independent harmonic functions of growth at most <i>k<\/i>, exceeding the Euclidean count $(k+1)^2$. The metric may depend on <i>k<\/i>.","subject":"Differential geometry","lean":2,"applied":1,"difficulty":3,"year":null,"note":"Harmonic functions on manifolds. No route identified.","papers":[{"title":"A counterexample to integer-degree harmonic dimension comparison","path":"preprints/A-counterexample-to-integer-degree-harmonic-dimension-comparison-September-25-2026/paper.pdf"},{"title":"A Three-Dimensional Counterexample to Integer-Degree Harmonic Dimension Comparison","path":"preprints/A-Three-Dimensional-Counterexample-to-Integer-Degree-Harmonic-Dimension-Comparison-September-26-2026/paper.pdf"}]},{"id":"362","title":"Global smoothness for relativistic Vlasov–Maxwell","desc":"Proves large-data global existence and uniqueness for the three-dimensional, one-species relativistic Vlasov–Maxwell system. Smooth admissible initial data may be arbitrary provided the particle density is compactly supported and the electromagnetic fields have finite energy and bounded derivatives of every order; the solution remains smooth on every finite time interval.","subject":"Partial differential equations","lean":2,"applied":3,"difficulty":5,"year":1986,"note":"Vlasov-Maxwell is the kinetic model of collisionless plasma used in fusion and space physics. Smooth solutions exist for all time, so solvers face no singularity.","papers":[{"title":"Global classical solutions of the three-dimensional relativistic Vlasov–Maxwell system","path":"preprints/Global-classical-solutions-of-the-three-dimensional-relativistic-Vlasov-Maxwell-system-September-23-2026/paper.pdf"}]},{"id":"363","title":"Nonuniqueness with local conservation for the hard-sphere Boltzmann equation","desc":"Constructs two distinct global entropy solutions of the three-dimensional periodic hard-sphere Boltzmann equation from the same nonnegative initial density, with bounded velocity support and finite mass, energy and absolute entropy. Both are strongly continuous in <i>L<\/i><sup>1<\/sup> and satisfy exact local conservation of mass, momentum and kinetic energy.","subject":"Partial differential equations","lean":1,"applied":3,"difficulty":4,"year":null,"note":"Entropy solutions of the Boltzmann equation are not unique, so the weak-solution framework does not select the physical flow.","papers":[{"title":"Nonuniqueness with local conservation for the hard-sphere Boltzmann equation","path":"preprints/Nonuniqueness-with-local-conservation-for-the-hard-sphere-Boltzmann-equation-October-5-2026/paper.pdf"},{"title":"Nonuniqueness for the periodic hard-sphere Boltzmann equation","path":"preprints/Nonuniqueness-for-the-periodic-hard-sphere-Boltzmann-equation-September-23-2026/paper.pdf"}]},{"id":"364","title":"Kinetic limits and fluctuations over the Boltzmann lifespan","desc":"Derives the nonlinear Boltzmann equation from three-dimensional grand-canonical Newtonian gases throughout every regular kinetic interval with uniform Gaussian decay. Stable finite-range radial potentials may have attractive wells and a singular repulsive core; initial pair exclusion and spatially summable Gaussian density and gradient bounds are assumed. A companion gives finite-dimensional hard-sphere Gaussian fluctuations, centered at the exact microscopic expectation and governed by the linear fluctuating Boltzmann equation.","subject":"Partial differential equations","lean":0,"applied":2,"difficulty":4,"year":1975,"note":"Derivation of the Boltzmann equation from particle dynamics over long times. Justifies the kinetic model.","papers":[{"title":"The Boltzmann–Grad limit for stable radial potentials on regular kinetic intervals","path":"preprints/The-Boltzmann-Grad-limit-for-stable-radial-potentials-on-regular-kinetic-intervals-September-23-2026/paper.pdf"},{"title":"Hard-sphere fluctuations on the regular Boltzmann lifespan","path":"preprints/Hard-sphere-fluctuations-on-the-regular-Boltzmann-lifespan-September-23-2026/paper.pdf"}]},{"id":"365","title":"Joint metric and connection recovery from one boundary patch","desc":"Zero-frequency measurements on any nonempty open boundary patch determine a smooth metric and smooth unitary connection on a trivial Hermitian rank-two bundle over a compact connected manifold of dimension at least three, up to diffeomorphism and gauge fixed on that patch. Inputs and observations use the same patch. In contrast, distinct uniformly positive bounded measurable scalar conductivities on a three-dimensional ball can have identical full-boundary data.","subject":"Partial differential equations","lean":2,"applied":2,"difficulty":3,"year":null,"note":"Recovery of a metric and a connection from boundary measurements on a patch. Theory of inverse problems.","papers":[{"title":"Determination of a metric and a unitary connection from one boundary patch","path":"preprints/Determination-of-a-metric-and-a-unitary-connection-from-one-boundary-patch-October-5-2026/paper.pdf"},{"title":"Smooth anisotropic uniqueness in the Calderón problem from one boundary patch","path":"preprints/Smooth-Anisotropic-Uniqueness-in-the-Calderon-Problem-from-One-Boundary-Patch-September-24-2026/paper.pdf"},{"title":"Nonuniqueness for bounded measurable scalar conductivities in three dimensions","path":"preprints/Nonuniqueness-for-Bounded-Measurable-Scalar-Conductivities-in-Three-Dimensions-September-23-2026/paper.pdf"}]},{"id":"366","title":"The planar Mumford–Shah regularity conjecture and local weak-<i>L<\/i><sup>4<\/sup> gradient bounds","desc":"Resolves the interior regularity conjecture for reduced absolute planar Mumford–Shah minimizers with bounded fidelity data. Locally, the closed discontinuity set is a $C^{1,\\alpha}$ arc, a regular crack tip, or three arcs meeting at $120^\\circ$; only finitely many global connected components meet any compact interior region.","subject":"Partial differential equations","lean":0,"applied":3,"difficulty":5,"year":1989,"note":"The Mumford-Shah functional is the variational model for image segmentation and fracture. Edge sets of planar minimizers are arcs, crack tips or triple junctions.","papers":[{"title":"Interior regularity of planar Mumford–Shah minimizers","path":"preprints/Interior-regularity-of-planar-Mumford-Shah-minimizers-September-24-2026/Interior-regularity-of-planar-Mumford-Shah-minimizers-September-24-2026.pdf"}]},{"id":"367","title":"The critical dimension for the one-phase Bernoulli problem","desc":"Establishes seven as the first dimension admitting a nonflat, one-homogeneous global minimizer of the one-phase Bernoulli energy. Consequently, minimizing free boundaries are smooth through dimension six, and their singular sets have dimension at most $n-7$ in higher dimensions.","subject":"Partial differential equations","lean":1,"applied":2,"difficulty":4,"year":null,"note":"Regularity of free boundaries in jet and cavity flow models up to dimension six.","papers":[{"title":"The critical dimension for one-phase Bernoulli minimizers","path":"preprints/The-critical-dimension-for-one-phase-Bernoulli-minimizers-September-24-2026/The-critical-dimension-for-one-phase-Bernoulli-minimizers-September-24-2026.pdf"}]},{"id":"368","title":"The three-dimensional Ball–Evans approximation problem","desc":"Resolves the three-dimensional Ball–Evans approximation problem: every $W^{1,p}$ homeomorphism between arbitrary bounded domains in ℝ<sup>3<\/sup>, for $1\\le p\\lt \\infty$, is a strong $W^{1,p}$ limit of smooth diffeomorphisms onto the same target.","subject":"Partial differential equations","lean":0,"applied":3,"difficulty":4,"year":2001,"note":"Nonlinear elasticity needs deformations approximated by smooth invertible maps. The theorem supplies that in three dimensions.","papers":[{"title":"Strong diffeomorphic approximation in three dimensions for 1≤p≤2","path":"preprints/Strong-diffeomorphic-approximation-in-three-dimensions-for-1-le-p-le-2-September-24-2026/main.pdf"},{"title":"Strong diffeomorphic approximation in three dimensions for p&gt;2","path":"preprints/Strong-diffeomorphic-approximation-in-three-dimensions-for-p-gt-2-September-24-2026/main.pdf"}]},{"id":"369","title":"The hot spots conjecture for simply connected planar domains","desc":"Proves a strict form of Burdzy&#x27;s simply connected hot spots conjecture. On every smooth bounded simply connected planar domain, each nonzero eigenfunction for the first positive Neumann eigenvalue has no interior critical point, so all global extrema lie on the boundary. Eigenvalue multiplicity is allowed.","subject":"Partial differential equations","lean":1,"applied":2,"difficulty":5,"year":1974,"note":"Location of the hottest point of an insulated plate at long times.","papers":[{"title":"Strict hot spots and absence of interior critical points on smooth simply connected planar domains","path":"preprints/Strict-hot-spots-and-absence-of-interior-critical-points-on-smooth-simply-connected-planar-domains-September-24-2026/main.pdf"}]},{"id":"370","title":"The Lane–Emden and Hénon–Lane–Emden conjectures","desc":"Resolves the subcritical Lane–Emden conjecture and its weighted Hénon extension. For <i>n<\/i> ≥ 2, $p,q\\gt 0$ and real <i>A<\/i>, <i>B<\/i>, the system $-\\Delta u=|x|^A v^p$, $-\\Delta v=|x|^B u^q$ has no positive entire solution when $(n+A)/(p+1)+(n+B)/(q+1)\\gt n-2$, with solutions continuous at the origin and classical elsewhere. No symmetry or growth assumption is needed. Known radial existence gives the exact existence criterion for <i>n<\/i> ≥ 3 and $A,B\\gt -2$.","subject":"Partial differential equations","lean":2,"applied":1,"difficulty":4,"year":1996,"note":"Nonexistence for elliptic systems. A weak link to astrophysical models.","papers":[{"title":"The Subcritical Hénon–Lane–Emden Conjecture","path":"preprints/The-Subcritical-Henon-Lane-Emden-Conjecture-September-24-2026/paper.pdf"}]},{"id":"371","title":"Stable blowup for the defocusing Schrödinger equation","desc":"For a sufficiently large odd nonlinearity power, constructs a nonempty open set of initial data in $H^k(\\mathbb T^{12})$, with <i>k<\/i> &gt; 8, whose solutions of the scalar defocusing nonlinear Schrödinger equation blow up in finite time. Thus finite-time blowup is stable under Sobolev perturbations in this supercritical regime.","subject":"Partial differential equations","lean":1,"applied":2,"difficulty":3,"year":null,"note":"Blowup for a defocusing wave equation in high dimension. A caution for numerical continuation.","papers":[{"title":"Stable self-similar blowup for a supercritical defocusing Schrödinger equation on the torus","path":"preprints/Stable-Self-Similar-Blowup-for-a-Supercritical-Defocusing-Schrodinger-Equation-on-the-Torus-September-24-2026/paper.pdf"}]},{"id":"372","title":"Global uniqueness in smooth isotropic elasticity","desc":"Proves that full static boundary displacement-to-traction data determine both smooth real Lamé moduli on every bounded connected smooth domain in ℝ<sup>3<\/sup>, provided <i>μ<\/i> &gt; 0 and $3\\lambda+2\\mu\\gt 0$ on the closure. Neither analyticity, proximity to constant coefficients nor prior knowledge near the boundary is required.","subject":"Partial differential equations","lean":1,"applied":4,"difficulty":4,"year":1994,"note":"Both elastic moduli of a body are determined by boundary measurements. This is the identifiability question behind elastography and static seismic inversion.","papers":[{"title":"Global Uniqueness for the Smooth Isotropic Elasticity Inverse Problem","path":"preprints/Global-Uniqueness-for-the-Smooth-Isotropic-Elasticity-Inverse-Problem-September-24-2026/article.pdf"}]},{"id":"373","title":"Nonattainment of the three-marginal Coulomb Monge problem","desc":"An optimal three-particle Coulomb configuration need not be a deterministic function of the first particle, even for smooth identical spatial densities. The Monge and Kantorovich infima agree, but the Monge infimum is not attained. The same phenomenon occurs for every inverse-power Riesz exponent in each dimension at least two, with a suitable density in each case.","subject":"Partial differential equations","lean":1,"applied":3,"difficulty":3,"year":null,"note":"Strictly correlated electron methods in density functional theory assume a deterministic transport map. It need not exist for three electrons.","papers":[{"title":"A counterexample to the Monge ansatz for the three-marginal Coulomb cost","path":"preprints/A-counterexample-to-the-Monge-ansatz-for-the-three-marginal-Coulomb-cost-September-25-2026/paper.pdf"}]},{"id":"374","title":"Sharp one-third stability of Brenier maps","desc":"For uniform source measure <i>ρ<\/i> on a compact convex body with interior in dimension at least two, quadratic optimal transport maps satisfy $\\|T_\\mu-T_\\nu\\|_{L^2(\\rho)}\\le C W_2(\\mu,\\nu)^{1/3}$ uniformly over targets in a fixed compact set. The exponent is sharp, even for three-atom targets, disproving Letrouit&#x27;s conjectured square-root bound.","subject":"Partial differential equations","lean":1,"applied":3,"difficulty":2,"year":null,"note":"The stability exponent sets convergence rates when optimal transport maps are estimated from samples.","papers":[{"title":"Sharp One-Third Stability of Brenier Maps","path":"preprints/Sharp-One-Third-Stability-of-Brenier-Maps-September-25-2026/article.pdf"}]},{"id":"375","title":"De Giorgi&#x27;s conjecture in dimension eight","desc":"Proves De Giorgi&#x27;s conjecture at its sharp dimension-eight endpoint: every entire <i>C<\/i><sup>2<\/sup> solution $u:\\mathbb R^8\\to(-1,1)$ of $\\Delta u=u^3-u$ that is strictly increasing in one direction depends on only one linear coordinate. A stronger theorem classifies all stable entire solutions $v:\\mathbb R^7\\to[-1,1]$ as constant wells or planar transitions, without an energy-growth assumption.","subject":"Partial differential equations","lean":0,"applied":1,"difficulty":5,"year":1978,"note":"Phase-transition models. The endpoint dimension has no modelling consequence.","papers":[{"title":"A positive resolution of De Giorgi&#x27;s conjecture in dimension eight","path":"preprints/De-Giorgis-conjecture-in-dimension-eight-September-26-2026/article.pdf"}]},{"id":"376","title":"Universal computation in forced Navier–Stokes flows","desc":"Constructs viscous incompressible flows starting from rest on a fixed flat three-dimensional domain that perform universal computation under smooth external forcing. A terminating compiler turns a Turing machine and input into a finite program for the force, so a designated particle reaches a fixed region exactly when the machine halts. The viscosity is fixed, positive and computable.","subject":"Partial differential equations","lean":1,"applied":2,"difficulty":3,"year":2014,"note":"Forced viscous flows can simulate any computation, so long-time prediction of such flows is undecidable in general.","papers":[{"title":"Finite Instructions and Solenoidal Shear Flows","path":"preprints/Finite-Instructions-and-Solenoidal-Shear-Flows-September-27-2026/manuscript.pdf"},{"title":"A Fixed Particle Test for Computation in a Forced Viscous Flow","path":"preprints/A-Fixed-Particle-Test-for-Computation-in-a-Forced-Viscous-Flow-September-27-2026/manuscript.pdf"},{"title":"Universal Computation with Eventually Stationary Navier–Stokes Forcing","path":"preprints/Universal-Computation-with-Eventually-Stationary-Navier-Stokes-Forcing-September-27-2026/manuscript.pdf"},{"title":"Geometric Programs for Solenoidal Forcing","path":"preprints/Geometric-Programs-for-Solenoidal-Forcing-September-27-2026/manuscript.pdf"},{"title":"Prefix Instructions and Incompressible Flows","path":"preprints/Prefix-Instructions-and-Incompressible-Flows-September-27-2026/manuscript.pdf"},{"title":"Computation under Rapidly Vanishing Navier–Stokes Forcing","path":"preprints/Computation-under-Rapidly-Vanishing-Navier-Stokes-Forcing-September-27-2026/manuscript.pdf"},{"title":"Velocity-Field Detection of Computation in Forced Navier–Stokes Flows","path":"preprints/Velocity-Field-Detection-of-Computation-in-Forced-Navier-Stokes-Flows-September-27-2026/manuscript.pdf"},{"title":"Scalar Potentials and Slow Clocks for Forced Fluid Computation","path":"preprints/Scalar-Potentials-and-Slow-Clocks-for-Forced-Fluid-Computation-September-27-2026/manuscript.pdf"},{"title":"Incompressible Box Transport and Finite Computation","path":"preprints/Incompressible-Box-Transport-and-Finite-Computation-September-27-2026/manuscript.pdf"}]},{"id":"377","title":"Interior $C^{1,\\alpha}$ regularity for infinity-harmonic functions","desc":"Proves uniform interior $C^{1,\\alpha_d}$ regularity for bounded infinity-harmonic functions in every dimension <i>d<\/i> ≥ 3, for a positive exponent depending only on dimension. The gradient&#x27;s supremum norm and Hölder seminorm on the half unit ball are bounded by a dimension-dependent constant times the oscillation on the unit ball. The exponent is not explicit.","subject":"Partial differential equations","lean":0,"applied":2,"difficulty":4,"year":null,"note":"The infinity Laplacian arises in tug-of-war games and image interpolation. Regularity in every dimension.","papers":[{"title":"Uniform Interior $C^{1,\\alpha}$ Estimates for Infinity-Harmonic Functions","path":"preprints/Uniform-Interior-C1alpha-Estimates-for-Infinity-Harmonic-Functions-October-4-2026/interior-c1-infinity-harmonic.pdf"}]}];
